public func rotated(_ center: PyreonChartPt, _ x: Double, _ y: Double, _ cosA: Double, _ sinA: Double) -> PyreonChartPt { PyreonChartPt(x: center.x + x * cosA - y * sinA, y: center.y + x * sinA + y * cosA) }

public func patternMarks(_ p: PyreonChartPattern, _ bounds: PyreonChartRect) -> [PyreonDrawCmd] {
    var out: [PyreonDrawCmd] = []
    let spacing = p.spacing > 2.0 ? p.spacing : 2.0
    let width = p.width > 0.5 ? p.width : 0.5
    let center = PyreonChartPt(x: bounds.x + bounds.w / 2.0, y: bounds.y + bounds.h / 2.0)
    let reach = sqrt(Double(bounds.w * bounds.w + bounds.h * bounds.h)) / 2.0 + spacing
    if p.kind == "image" {
      return out
    }
    if p.kind == "dots" {
      var y = bounds.y
      while y <= bounds.y + bounds.h {
        var x = bounds.x
        while x <= bounds.x + bounds.w {
          out.append(PyreonDrawCmd(kind: "circle", fill: p.color, center: PyreonChartPt(x: x, y: y), radius: width / 2.0))
          x = x + spacing
        }
        y = y + spacing
      }
      return out
    }
    if p.kind == "symbols" {
      let angle = ((p.angle ?? 0.0)) * DEG
      let cosA = cos(Double(angle))
      let sinA = sin(Double(angle))
      let stepY = ((p.spacingY ?? spacing)) > 2.0 ? (p.spacingY ?? spacing) : 2.0
      let half = width / 2.0
      let symbol = (p.symbol ?? "rect")
      let shape = (p.shape ?? [])
      let rings = (p.shapeRings ?? [])
      var gy = -reach
      while gy <= reach {
        var gx = -reach
        while gx <= reach {
          let c = rotated(center, gx, gy, cosA, sinA)
          if symbol == "circle" {
            out.append(PyreonDrawCmd(kind: "circle", fill: p.color, center: c, radius: half))
          } else {
            if symbol == "triangle" {
              out.append(PyreonDrawCmd(kind: "polygon", fill: p.color, points: [rotated(center, gx, gy - half, cosA, sinA), rotated(center, gx + half, gy + half, cosA, sinA), rotated(center, gx - half, gy + half, cosA, sinA)]))
            } else {
              if symbol == "path" {
                var at = 0
                for count in rings {
                  var pts: [PyreonChartPt] = []
                  var k = 0.0
                  while k < count && at < shape.count {
                    let q = shape[at]
                    pts.append(rotated(center, gx + q.x * width, gy + q.y * width, cosA, sinA))
                    at = at + 1
                    k = k + 1.0
                  }
                  if pts.count >= 3 {
                    out.append(PyreonDrawCmd(kind: "polygon", fill: p.color, points: pts))
                  }
                }
              } else {
                if symbol == "pin" {
                  var pts: [PyreonChartPt] = []
                  let headR = half * 0.62
                  let headY = gy - half + headR
                  var t = 0.0
                  while t <= 1.0 {
                    let a = Double.pi * (0.8 + 1.4 * t)
                    pts.append(rotated(center, gx + headR * cos(Double(a)), headY + headR * sin(Double(a)), cosA, sinA))
                    t = t + 0.125
                  }
                  pts.append(rotated(center, gx, gy + half, cosA, sinA))
                  out.append(PyreonDrawCmd(kind: "polygon", fill: p.color, points: pts))
                } else {
                  if symbol == "arrow" {
                    out.append(PyreonDrawCmd(kind: "polygon", fill: p.color, points: [rotated(center, gx, gy - half, cosA, sinA), rotated(center, gx + half * 0.8, gy + half, cosA, sinA), rotated(center, gx, gy + half * 0.45, cosA, sinA), rotated(center, gx - half * 0.8, gy + half, cosA, sinA)]))
                  } else {
                    if symbol == "diamond" {
                      out.append(PyreonDrawCmd(kind: "polygon", fill: p.color, points: [rotated(center, gx, gy - half, cosA, sinA), rotated(center, gx + half, gy, cosA, sinA), rotated(center, gx, gy + half, cosA, sinA), rotated(center, gx - half, gy, cosA, sinA)]))
                    } else {
                      out.append(PyreonDrawCmd(kind: "polygon", fill: p.color, points: [rotated(center, gx - half, gy - half, cosA, sinA), rotated(center, gx + half, gy - half, cosA, sinA), rotated(center, gx + half, gy + half, cosA, sinA), rotated(center, gx - half, gy + half, cosA, sinA)]))
                    }
                  }
                }
              }
            }
          }
          gx = gx + spacing
        }
        gy = gy + stepY
      }
      return out
    }
    let base = (p.angle ?? 45.0)
    let sets = p.kind == "cross" ? 2 : 1
    for set in 0..<sets {
      let a = (set == 0 ? base : base + 90.0) * DEG
      let cosA = cos(Double(a))
      let sinA = sin(Double(a))
      var k = -reach
      while k <= reach {
        out.append(PyreonDrawCmd(kind: "line", from: rotated(center, -reach, k, cosA, -sinA), to: rotated(center, reach, k, cosA, -sinA), stroke: p.color, width: width))
        k = k + spacing
      }
    }
    return out
  }

public func patternImageCells(_ p: PyreonChartPattern, _ bounds: PyreonChartRect, _ imageW: Double, _ imageH: Double) -> [PyreonChartRect] {
    var out: [PyreonChartRect] = []
    let `repeat` = (p.`repeat` ?? "repeat")
    if `repeat` == "grid" {
      let sx = p.spacing > 2.0 ? p.spacing : 2.0
      let sy = ((p.spacingY ?? sx)) > 2.0 ? (p.spacingY ?? sx) : 2.0
      let size = p.width > 0.5 ? p.width : 0.5
      let aspect = imageW > 0.0 && imageH > 0.0 ? imageH / imageW : 1.0
      let w = aspect <= 1.0 ? size : Double(size) / Double(aspect)
      let h = aspect <= 1.0 ? size * aspect : size
      var y = floor(Double(bounds.y / Double(sy))) * sy
      while y < bounds.y + bounds.h {
        var x = floor(Double(bounds.x / Double(sx))) * sx
        while x < bounds.x + bounds.w {
          out.append(PyreonChartRect(x: x + Double((sx - w)) / 2.0, y: y + Double((sy - h)) / 2.0, w: w, h: h))
          x = x + sx
        }
        y = y + sy
      }
      return out
    }
    if !(imageW > 0.0) || !(imageH > 0.0) {
      return out
    }
    let tileX = `repeat` == "repeat" || `repeat` == "repeat-x"
    let tileY = `repeat` == "repeat" || `repeat` == "repeat-y"
    var y = tileY ? floor(Double(bounds.y / imageH)) * imageH : 0.0
    let yEnd = tileY ? bounds.y + bounds.h : 0.5
    while y < yEnd {
      var x = tileX ? floor(Double(bounds.x / imageW)) * imageW : 0.0
      let xEnd = tileX ? bounds.x + bounds.w : 0.5
      while x < xEnd {
        out.append(PyreonChartRect(x: x, y: y, w: imageW, h: imageH))
        x = x + imageW
      }
      y = y + imageH
    }
    return out
  }

public func paletteAt(_ palette: [String], _ index: Int) -> String {
    let n = palette.count
    if n == 0 {
      return DEFAULT_PALETTE[index % DEFAULT_PALETTE.count]
    }
    return palette[index % n]
  }

public func hexDigit(_ c: Double) -> Double {
    if c >= 48.0 && c <= 57.0 {
      return c - 48.0
    }
    if c >= 97.0 && c <= 102.0 {
      return c - 87.0
    }
    if c >= 65.0 && c <= 70.0 {
      return c - 55.0
    }
    return 0.0
  }

public func cornerRadii(_ rect: PyreonChartRect, _ corners: [Double]?) -> [Double] {
    let c = (corners ?? [])
    if c.count < 4 {
      return [0.0, 0.0, 0.0, 0.0]
    }
    let w = rect.w < 0.0 ? -rect.w : rect.w
    let h = rect.h < 0.0 ? -rect.h : rect.h
    let max = (w < h ? w : h) / 2.0
    var out: [Double] = []
    for raw in c {
      let v = raw < 0.0 ? 0.0 : raw
      out.append(v > max ? max : v)
    }
    return [out[0], out[1], out[2], out[3]]
  }

public func hasCorners(_ radii: [Double]) -> Bool {
    for r in radii {
      if r > 0.0 {
        return true
      }
    }
    return false
  }

public func rectCmd(_ rect: PyreonChartRect, _ fill: String, _ corners: [Double]?, _ grad: PyreonChartGradient?, _ pattern: PyreonChartPattern? = nil) -> PyreonDrawCmd {
    if pattern == nil {
      if corners == nil && grad == nil {
        return PyreonDrawCmd(kind: "rect", rect: rect, fill: fill)
      }
      if grad == nil {
        return PyreonDrawCmd(kind: "rect", rect: rect, fill: fill, corners: corners)
      }
      if corners == nil {
        return PyreonDrawCmd(kind: "rect", rect: rect, fill: fill, grad: grad)
      }
      return PyreonDrawCmd(kind: "rect", rect: rect, fill: fill, corners: corners, grad: grad)
    }
    if corners == nil && grad == nil {
      return PyreonDrawCmd(kind: "rect", rect: rect, fill: fill, pattern: pattern)
    }
    if grad == nil {
      return PyreonDrawCmd(kind: "rect", rect: rect, fill: fill, corners: corners, pattern: pattern)
    }
    if corners == nil {
      return PyreonDrawCmd(kind: "rect", rect: rect, fill: fill, grad: grad, pattern: pattern)
    }
    return PyreonDrawCmd(kind: "rect", rect: rect, fill: fill, corners: corners, grad: grad, pattern: pattern)
  }

public func polygonCmd(_ points: [PyreonChartPt], _ fill: String, _ grad: PyreonChartGradient?, _ pattern: PyreonChartPattern? = nil) -> PyreonDrawCmd {
    if grad == nil && pattern == nil {
      return PyreonDrawCmd(kind: "polygon", fill: fill, points: points)
    }
    if grad == nil {
      return PyreonDrawCmd(kind: "polygon", fill: fill, pattern: pattern, points: points)
    }
    if pattern == nil {
      return PyreonDrawCmd(kind: "polygon", fill: fill, grad: grad, points: points)
    }
    return PyreonDrawCmd(kind: "polygon", fill: fill, grad: grad, pattern: pattern, points: points)
  }

public func gradientFor(_ g: SeriesGradient, _ plot: PyreonChartRect) -> PyreonChartGradient {
    if g.shape == "radial" {
      let center = PyreonChartPt(x: plot.x + plot.w / Double(2), y: plot.y + plot.h / Double(2))
      let radius = Double(max(plot.w, plot.h)) / Double(2)
      return PyreonChartGradient(from: center, to: PyreonChartPt(x: center.x + radius, y: center.y), stops: g.stops, radial: true)
    }
    let horizontal = g.direction == "horizontal"
    let from = PyreonChartPt(x: plot.x, y: plot.y)
    let to = horizontal ? PyreonChartPt(x: plot.x + plot.w, y: plot.y) : PyreonChartPt(x: plot.x, y: plot.y + plot.h)
    return PyreonChartGradient(from: from, to: to, stops: g.stops, radial: false)
  }

public func seriesGradient(_ g: SeriesGradient?, _ plot: PyreonChartRect) -> PyreonChartGradient {
    let src = (g ?? NO_GRADIENT)
    return gradientFor(src, plot)
  }

public func gradientSolid(_ g: PyreonChartGradient, _ fallback: String) -> String {
    if g.stops.count == 0 {
      return fallback
    }
    return g.stops[0].color
  }

public func plain(_ v: Double) -> String {
    let r = ((Double(v)) + 0.5).rounded(.down)
    if abs(v - r) < 0.000001 {
      return "\(r)"
    }
    return "\(((Double(v * 1000.0)) + 0.5).rounded(.down) / 1000.0)"
  }

public func compact(_ v: Double) -> String {
    let abs = abs(v)
    let sign = v < 0.0 ? "-" : ""
    if Double(abs) >= 1000000000.0 {
      return "\(sign)\(trim(Double(abs) / 1000000000.0))B"
    }
    if Double(abs) >= 1000000.0 {
      return "\(sign)\(trim(Double(abs) / 1000000.0))M"
    }
    if Double(abs) >= 1000.0 {
      return "\(sign)\(trim(Double(abs) / 1000.0))K"
    }
    return plain(v)
  }

public func trim(_ v: Double) -> String {
    let r = ((Double(v * 10.0)) + 0.5).rounded(.down) / 10.0
    return ((r).truncatingRemainder(dividingBy: 1) == 0) ? "\(((Double(r)) + 0.5).rounded(.down))" : "\(r)"
  }

public func fixed(_ places: Int) -> (Double) -> String {
    let p = max(0, min(10, places))
    let mul = pow(Double(10.0), Double(p))
    return { v in
      let r = ((Double(v * mul)) + 0.5).rounded(.down) / mul
      if p == 0 {
        return "\(((Double(r)) + 0.5).rounded(.down))"
      }
      let s = "\(r)"
      let dot = (s.range(of: ".").map { s.distance(from: s.startIndex, to: $0.lowerBound) } ?? -1)
      if dot < 0 {
        return "\(s).\(String(repeating: "0", count: p))"
      }
      let decimals = s.utf16.count - dot - 1
      return decimals >= p ? s : "\(s)\(String(repeating: "0", count: p - decimals))"
    }
  }

public func currency(_ symbol: String, _ places: Int = 0) -> (Double) -> String {
    let f = fixed(places)
    return { v in (v < 0.0 ? "-\(symbol)\(f(-v))" : "\(symbol)\(f(v))") }
  }

public func percent(_ places: Int = 0) -> (Double) -> String {
    let f = fixed(places)
    return { v in "\(f(v * 100.0))%" }
  }

public func scaleLinear(_ d: Domain, _ r0: Double, _ r1: Double, _ v: Double) -> Double {
    let span = d.max - d.min
    if span == 0.0 {
      return (r0 + r1) / 2.0
    }
    if d.inverse == true {
      return r1 + ((v - d.min) / span) * (r0 - r1)
    }
    return r0 + ((v - d.min) / span) * (r1 - r0)
  }

public func niceStep(_ raw: Double) -> Double {
    if raw <= 0.0 {
      return 1.0
    }
    let mag = pow(Double(10.0), Double(floor(Double(log10(Double(raw))))))
    let norm = raw / mag
    var m = 10.0
    if norm <= 1.0 {
      m = 1.0
    } else {
      if norm <= 2.0 {
        m = 2.0
      } else {
        if norm <= 5.0 {
          m = 5.0
        }
      }
    }
    return m * mag
  }

public func niceDomain(_ d: Domain, _ targetCount: Double) -> Domain {
    if d.max == d.min {
      return Domain(min: d.min - 0.5, max: d.max + 0.5)
    }
    let step = niceStep((d.max - d.min) / targetCount)
    return Domain(min: floor(Double(d.min / step)) * step, max: ceil(Double(d.max / step)) * step)
  }

public func echartsNice(_ val: Double, _ round: Bool) -> Double {
    if !(val > 0.0) {
      return 1.0
    }
    let exponent = floor(Double(log10(Double(val))))
    let exp10 = pow(Double(10.0), Double(exponent))
    let f = val / exp10
    var nf = 10.0
    if round {
      if f < 1.5 {
        nf = 1.0
      } else {
        if f < 2.5 {
          nf = 2.0
        } else {
          if f < 4.0 {
            nf = 3.0
          } else {
            if f < 7.0 {
              nf = 5.0
            }
          }
        }
      }
    } else {
      if f < 1.0 {
        nf = 1.0
      } else {
        if f < 2.0 {
          nf = 2.0
        } else {
          if f < 3.0 {
            nf = 3.0
          } else {
            if f < 5.0 {
              nf = 5.0
            }
          }
        }
      }
    }
    let out = nf * exp10
    return exponent >= 0.0 ? out : roundTo(out, -exponent)
  }

public func roundTo(_ v: Double, _ digits: Double) -> Double {
    let k = pow(Double(10.0), Double(digits))
    return floor(Double(v * k + 0.5)) / k
  }

public func stepPrecision(_ step: Double) -> Double {
    if !(step > 0.0) {
      return 0.0
    }
    let e = floor(Double(log10(Double(step))))
    return e >= 0.0 ? 0.0 : -e + 1.0
  }

public func echartsNiceDomain(_ d: Domain, _ splitNumber: Double, _ fixMin: Bool, _ fixMax: Bool) -> Domain {
    var lo = d.min
    var hi = d.max
    if hi == lo {
      if lo == 0.0 {
        hi = 1.0
      } else {
        let half = Double(abs(lo)) / 2.0
        lo = lo - half
        hi = hi + half
      }
    }
    let split = splitNumber > 0.0 ? splitNumber : 5.0
    let step = echartsNice((hi - lo) / split, true)
    let p = stepPrecision(step)
    return Domain(min: fixMin ? d.min : roundTo(floor(Double(lo / step)) * step, p), max: fixMax ? d.max : roundTo(ceil(Double(hi / step)) * step, p), step: step)
  }

public func isFiniteNumber(_ v: Double) -> Bool { v == v && v - v == 0.0 }

public func makeTicks(_ d: Domain, _ r0: Double, _ r1: Double, _ count: Double, _ format: ((Double) -> String)? = nil) -> [Tick] {
    let fmt = (format ?? formatTick)
    var out: [Tick] = []
    if count <= 0.0 {
      return out
    }
    if !isFiniteNumber(d.min) || !isFiniteNumber(d.max) {
      return out
    }
    let span = d.max - d.min
    if span <= 0.0 {
      out.append(Tick(value: d.min, pos: scaleLinear(d, r0, r1, d.min), label: fmt(d.min)))
      return out
    }
    let fixed = (d.step ?? 0.0)
    let step = fixed > 0.0 ? fixed : niceStep(span / count)
    let first = ceil(Double(d.min / step)) * step
    let eps = step * 0.000001
    if fixed > 0.0 && first > d.min + eps {
      out.append(Tick(value: d.min, pos: scaleLinear(d, r0, r1, d.min), label: fmt(d.min)))
    }
    let maxTicks = 1000
    var i = 0
    var last = d.min
    while i < maxTicks {
      let v = first + step * Double(i)
      if v > d.max + eps {
        break
      }
      out.append(Tick(value: v, pos: scaleLinear(d, r0, r1, v), label: fmt(v)))
      last = v
      i = i + 1
    }
    if fixed > 0.0 && last < d.max - eps {
      out.append(Tick(value: d.max, pos: scaleLinear(d, r0, r1, d.max), label: fmt(d.max)))
    }
    return out
  }

public func formatTick(_ v: Double) -> String {
    let r = ((Double(v)) + 0.5).rounded(.down)
    if abs(v - r) < 0.000001 {
      return "\(r)"
    }
    return "\(((Double(v * 1000.0)) + 0.5).rounded(.down) / 1000.0)"
  }

public func extent(_ values: [Double]) -> Domain {
    var seen = false
    var lo = 0.0
    var hi = 1.0
    for v in values {
      if !isFiniteNumber(v) {
        continue
      }
      if !seen {
        lo = v
        hi = v
        seen = true
      } else {
        if v < lo {
          lo = v
        }
        if v > hi {
          hi = v
        }
      }
    }
    if !seen {
      return Domain(min: 0.0, max: 1.0)
    }
    return Domain(min: lo, max: hi)
  }

public func scaleLog(_ d: Domain, _ r0: Double, _ r1: Double, _ v: Double) -> Double {
    let min = d.min <= 0.0 ? 0.000001 : d.min
    let max = d.max <= min ? min * 10.0 : d.max
    let val = v <= 0.0 ? min : v
    let lo = log10(Double(min))
    let hi = log10(Double(max))
    return r0 + ((log10(Double(val)) - lo) / (hi - lo)) * (r1 - r0)
  }

public func logTicks(_ d: Domain, _ r0: Double, _ r1: Double) -> [Tick] {
    let min = d.min <= 0.0 ? 0.000001 : d.min
    let max = d.max <= min ? min * 10.0 : d.max
    var out: [Tick] = []
    let from = floor(Double(log10(Double(min))))
    let to = ceil(Double(log10(Double(max))))
    let limit = 24
    var count = 0
    var e = from
    while e <= to && count < limit {
      let v = pow(Double(10.0), Double(e))
      if v >= min && v <= max {
        out.append(Tick(value: v, pos: scaleLog(d, r0, r1, v), label: plain(v)))
        count = count + 1
      }
      e = e + 1.0
    }
    return out
  }

public func timeTicks(_ d: Domain, _ r0: Double, _ r1: Double, _ target: Double, _ format: ((Double) -> String)? = nil) -> [Tick] {
    let span = d.max - d.min
    var out: [Tick] = []
    if span <= 0.0 || target <= 0 {
      return out
    }
    let steps = [1000.0, 5000.0, 15000.0, 30000.0, MINUTE, MINUTE * 5.0, MINUTE * 15.0, MINUTE * 30.0, HOUR, HOUR * 3.0, HOUR * 6.0, HOUR * 12.0, DAY, DAY * 7.0, DAY * 30.0, DAY * 90.0, DAY * 365.0]
    let ideal = span / target
    var step = steps[steps.count - 1]
    for s in steps {
      if s >= ideal {
        step = s
        break
      }
    }
    let fmt = (format ?? ({ x in formatTime(x, step) }))
    let first = ceil(Double(d.min / step)) * step
    let limit = 200
    var i = 0
    while i < limit {
      let v = first + step * Double(i)
      if v > d.max {
        break
      }
      out.append(Tick(value: v, pos: scaleLinear(d, r0, r1, v), label: fmt(v)))
      i = i + 1
    }
    return out
  }

public func formatTime(_ ms: Double, _ step: Double) -> String {
    let p2 = { (n: Double) in (n < 10 ? "0\(trunc(Double(n)))" : "\(trunc(Double(n)))") }
    let dayMs = 86400000.0
    let days = floor(Double(ms / dayMs))
    let msOfDay = ms - days * dayMs
    let z = days + 719468.0
    let era = floor(Double(z / 146097.0))
    let doe = z - era * 146097.0
    let yoe = floor(Double((doe - floor(Double(doe / 1460.0)) + floor(Double(doe / 36524.0)) - floor(Double(doe / 146096.0))) / 365.0))
    let y0 = yoe + era * 400.0
    let doy = doe - (365.0 * yoe + floor(Double(yoe / 4.0)) - floor(Double(yoe / 100.0)))
    let mp = floor(Double((5.0 * doy + 2.0) / 153.0))
    let day = doy - floor(Double((153.0 * mp + 2.0) / 5.0)) + 1.0
    let month = mp < 10.0 ? mp + 3.0 : mp - 9.0
    let year = month <= 2.0 ? y0 + 1.0 : y0
    let hours = floor(Double(msOfDay / 3600000.0))
    let minutes = floor(Double((msOfDay - hours * 3600000.0) / 60000.0))
    let seconds = floor(Double((msOfDay - hours * 3600000.0 - minutes * 60000.0) / 1000.0))
    if step >= DAY * 300.0 {
      return "\(trunc(Double(year)))"
    }
    if step >= DAY * 25.0 {
      return "\(trunc(Double(year)))-\(p2(month))"
    }
    if step >= DAY {
      return "\(p2(month))-\(p2(day))"
    }
    if step >= MINUTE {
      return "\(p2(hours)):\(p2(minutes))"
    }
    return "\(p2(hours)):\(p2(minutes)):\(p2(seconds))"
  }

public func logViewTicks(_ lo: Double, _ hi: Double, _ r0: Double, _ r1: Double, _ format: ((Double) -> String)? = nil) -> [Tick] {
    let fmt = (format ?? plain)
    var out: [Tick] = []
    if !(lo > 0.0) || !(hi > lo) {
      return out
    }
    let view = Domain(min: 0.0, max: log10(Double(hi / lo)))
    let from = floor(Double(log10(Double(lo))))
    let to = ceil(Double(log10(Double(hi))))
    let minors = to - from < 2.0
    let limit = 48
    var count = 0
    var e = from
    while e <= to && count < limit {
      let base = pow(Double(10.0), Double(e))
      let mults = minors ? [1.0, 2.0, 5.0] : [1.0]
      for m in mults {
        let v = base * m
        if v >= lo * 0.999999 && v <= hi * 1.000001 && count < limit {
          out.append(Tick(value: v, pos: scaleLinear(view, r0, r1, log10(Double(Double(v) / lo))), label: fmt(v)))
          count = count + 1
        }
      }
      e = e + 1.0
    }
    return out
  }

public func smooth(_ points: [PyreonChartPt]) -> [PyreonChartPt] {
    let n = points.count
    if n < 3 {
      return points
    }
    var dx: [Double] = []
    var slope: [Double] = []
    for i in 0..<n - 1 {
      let dxi = points[i + 1].x - points[i].x
      dx.append(dxi)
      slope.append(dxi == 0.0 ? 0.0 : (points[i + 1].y - points[i].y) / Double(dxi))
    }
    var m = [slope[0]]
    for i in 1..<n - 1 {
      let s0 = slope[i - 1]
      let s1 = slope[i]
      if s0 * s1 <= 0.0 {
        m.append(0.0)
      } else {
        let w0 = 2.0 * dx[i] + dx[i - 1]
        let w1 = dx[i] + 2.0 * dx[i - 1]
        m.append(Double((w0 + w1)) / Double((Double(w0) / Double(s0) + Double(w1) / Double(s1))))
      }
    }
    m.append(slope[n - 2])
    let steps = 16
    var out = [points[0]]
    for i in 0..<n - 1 {
      let p0 = points[i]
      let p1 = points[i + 1]
      let h = dx[i]
      for k in 1...steps {
        let t = Double(k) / Double(steps)
        let t2 = t * t
        let t3 = t2 * t
        let h00 = 2.0 * t3 - 3.0 * t2 + 1.0
        let h10 = t3 - 2.0 * t2 + t
        let h01 = -2.0 * t3 + 3.0 * t2
        let h11 = t3 - t2
        out.append(PyreonChartPt(x: p0.x + t * h, y: h00 * p0.y + h10 * h * m[i] + h01 * p1.y + h11 * h * m[i + 1]))
      }
    }
    return out
  }

public func step(_ points: [PyreonChartPt]) -> [PyreonChartPt] {
    let n = points.count
    if n < 2 {
      return points
    }
    var out = [points[0]]
    for i in 1..<n {
      out.append(PyreonChartPt(x: points[i].x, y: points[i - 1].y))
      out.append(points[i])
    }
    return out
  }

public func layoutArcs(_ slices: [Slice]) -> [ArcGeometry] {
    var total = 0.0
    for s in slices {
      if s.value > 0.0 {
        total = total + s.value
      }
    }
    var out: [ArcGeometry] = []
    if total <= 0.0 {
      return out
    }
    var angle = START
    for s in slices {
      if s.value <= 0.0 {
        continue
      }
      let fraction = Double(s.value) / total
      let sweep = fraction * TAU
      out.append(ArcGeometry(start: angle, end: angle + sweep, mid: angle + Double(sweep) / 2.0, slice: s, fraction: fraction))
      angle = angle + sweep
    }
    return out
  }

public func fitCircle(_ box: PyreonChartRect) -> Circle {
    let r = Double(min(box.w, box.h)) / 2.0
    return Circle(center: PyreonChartPt(x: box.x + box.w / 2.0, y: box.y + box.h / 2.0), radius: max(0.0, r))
  }

public func pointOnCircle(_ center: PyreonChartPt, _ radius: Double, _ angle: Double) -> PyreonChartPt { PyreonChartPt(x: center.x + cos(Double(angle)) * radius, y: center.y + sin(Double(angle)) * radius) }

public func arcPolygon(_ center: PyreonChartPt, _ outerR: Double, _ innerR: Double, _ start: Double, _ end: Double) -> [PyreonChartPt] {
    let sweep = abs(end - start)
    let steps = max(2, ceil(Double((sweep / Double(TAU)) * 64.0)))
    var pts: [PyreonChartPt] = []
    for i in 0...Int(ceil(Double(steps))) {
      pts.append(pointOnCircle(center, outerR, start + (sweep * Double(i)) / steps))
    }
    if innerR > 0.0 {
      for i in stride(from: Int(floor(Double(steps))), through: 0, by: -1) {
        pts.append(pointOnCircle(center, innerR, start + (sweep * Double(i)) / steps))
      }
    } else {
      pts.append(center)
    }
    return pts
  }

public func renderPie(_ slices: [Slice], _ box: PyreonChartRect, _ opts: PieOptions) -> [PyreonDrawCmd] {
    let __pyDestr1 = fitCircle(box)
    let center = __pyDestr1.center
    let radius = __pyDestr1.radius
    let inner = radius * max(0.0, min(0.95, opts.innerRadius))
    var out: [PyreonDrawCmd] = []
    let arcs = layoutArcs(slices)
    for a in arcs {
      out.append(PyreonDrawCmd(kind: "polygon", fill: a.slice.color, points: arcPolygon(center, radius, inner, a.start, a.end)))
    }
    if opts.showLabels {
      for a in arcs {
        if a.fraction < 0.05 {
          continue
        }
        let at = pointOnCircle(center, (radius + inner) / 2.0, a.mid)
        out.append(PyreonDrawCmd(kind: "text", fill: opts.labelColor, text: "\(((Double(a.fraction * 100.0)) + 0.5).rounded(.down))%", at: at, size: opts.fontSize, align: "middle", baseline: "middle"))
      }
    }
    return out
  }

public func hitArc(_ arcs: [ArcGeometry], _ center: PyreonChartPt, _ outerR: Double, _ innerR: Double, _ p: PyreonChartPt) -> Int {
    let dx = p.x - center.x
    let dy = p.y - center.y
    let dist = sqrt(Double(dx * dx + dy * dy))
    if dist > outerR || dist < innerR {
      return -1
    }
    let ang = atan2(Double(dy), Double(dx))
    for i in 0..<arcs.count {
      let a = arcs[i]
      var s = a.start
      var e = a.end
      while e > Double.pi {
        s = s - TAU
        e = e - TAU
      }
      let cand = ang > e ? ang - TAU : ang
      if cand >= s && cand <= e {
        return i
      }
    }
    return -1
  }

public func renderGauge(_ value: Double, _ box: PyreonChartRect, _ opts: GaugeOptions) -> [PyreonDrawCmd] {
    let __pyDestr1 = fitCircle(box)
    let center = __pyDestr1.center
    let radius = __pyDestr1.radius
    let inner = max(0.0, radius - opts.thickness)
    let span = opts.max - opts.min
    let t = span <= 0.0 ? 0.0 : max(0.0, min(1.0, (value - opts.min) / span))
    let start = Double.pi - (opts.sweep - Double.pi) / 2.0
    return [PyreonDrawCmd(kind: "polygon", fill: opts.trackColor, points: arcPolygon(center, radius, inner, start, start + opts.sweep)), PyreonDrawCmd(kind: "polygon", fill: opts.valueColor, points: arcPolygon(center, radius, inner, start, start + opts.sweep * t))]
  }

public func radarAngles(_ count: Int) -> [Double] {
    var out: [Double] = []
    if count <= 0 {
      return out
    }
    for i in 0..<count {
      out.append(RADAR_START + (Double.pi * 2.0 * Double(i)) / Double(count))
    }
    return out
  }

public func radarPolygon(_ values: [Double], _ axes: [RadarAxis], _ center: PyreonChartPt, _ radius: Double) -> [PyreonChartPt] {
    let n = min(values.count, axes.count)
    let angles = radarAngles(n)
    var out: [PyreonChartPt] = []
    for i in 0..<n {
      let axisMax = axes[i].max
      let t = axisMax <= 0.0 ? 0.0 : max(0.0, min(1.0, values[i] / Double(axisMax)))
      out.append(pointOnCircle(center, radius * t, angles[i]))
    }
    return out
  }

public func renderRadar(_ axes: [RadarAxis], _ series: [RadarSeries], _ box: PyreonChartRect, _ opts: RadarOptions) -> [PyreonDrawCmd] {
    var out: [PyreonDrawCmd] = []
    let n = axes.count
    if n < 3 {
      return out
    }
    let pad = opts.showLabels ? opts.fontSize * 3.0 : 0.0
    let radius = max(0.0, Double(min(box.w, box.h)) / 2.0 - pad)
    let center = PyreonChartPt(x: box.x + box.w / 2.0, y: box.y + box.h / 2.0)
    let angles = radarAngles(n)
    for r in 1...opts.rings {
      let rr = (radius * Double(r)) / Double(opts.rings)
      var ring: [PyreonChartPt] = []
      for a in angles {
        ring.append(pointOnCircle(center, rr, a))
      }
      ring.append(ring[0])
      out.append(PyreonDrawCmd(kind: "polyline", stroke: opts.gridColor, width: 1.0, points: ring))
    }
    for a in angles {
      out.append(PyreonDrawCmd(kind: "line", from: center, to: pointOnCircle(center, radius, a), stroke: opts.gridColor, width: 1.0))
    }
    for s in series {
      let poly = radarPolygon(s.values, axes, center, radius)
      if poly.count < 3 {
        continue
      }
      out.append(PyreonDrawCmd(kind: "polygon", fill: withAlpha(s.color, s.fillAlpha), points: poly))
      var closed: [PyreonChartPt] = []
      for p in poly {
        closed.append(p)
      }
      closed.append(poly[0])
      out.append(PyreonDrawCmd(kind: "polyline", stroke: s.color, width: 2.0, points: closed))
    }
    if opts.showLabels {
      for i in 0..<n {
        let at = pointOnCircle(center, radius + opts.fontSize * 1.2, angles[i])
        let dx = at.x - center.x
        let align = Double(abs(dx)) < 1.0 ? "middle" : dx > 0.0 ? "start" : "end"
        out.append(PyreonDrawCmd(kind: "text", fill: opts.labelColor, text: axes[i].label, at: at, size: opts.fontSize, align: align, baseline: "middle"))
      }
    }
    return out
  }

public func withAlpha(_ color: String, _ alpha: Double) -> String {
    let a = max(0.0, min(1.0, alpha))
    if color.hasPrefix("rgb(") && color.hasSuffix(")") {
      return "rgba(\(String(color.dropFirst(4).prefix(max(0, (color.utf16.count - 1) - (4))))), \(a))"
    }
    if !color.hasPrefix("#") {
      return color
    }
    let hex = String(color.dropFirst(1))
    let code = { (c: Double) in
      if c >= 48.0 && c <= 57.0 {
        return c - 48.0
      }
      if c >= 97.0 && c <= 102.0 {
        return c - 87.0
      }
      if c >= 65.0 && c <= 70.0 {
        return c - 55.0
      }
      return 0.0
    }
    let pair = { (at: Double) in code(Double(Array(hex.utf16)[Int(at)])) * 16.0 + code(Double(Array(hex.utf16)[Int(at + 1)])) }
    let single = { (at: Double) in code(Double(Array(hex.utf16)[Int(at)])) * 17.0 }
    if hex.utf16.count == 3 {
      return "rgba(\(single(0.0)), \(single(1.0)), \(single(2.0)), \(a))"
    }
    if hex.utf16.count == 6 {
      return "rgba(\(pair(0.0)), \(pair(2.0)), \(pair(4.0)), \(a))"
    }
    return color
  }

public func hitRadarIndex(_ axes: [RadarAxis], _ series: [RadarSeries], _ box: PyreonChartRect, _ opts: RadarOptions, _ px: Double, _ py: Double, _ tolerance: Double = 8.0) -> RadarHitIndex {
    let miss = RadarHitIndex(series: -1, axis: -1)
    let n = axes.count
    if n < 3 {
      return miss
    }
    let pad = opts.showLabels ? opts.fontSize * 3.0 : 0.0
    let radius = max(0.0, Double(min(box.w, box.h)) / 2.0 - pad)
    let center = PyreonChartPt(x: box.x + box.w / 2.0, y: box.y + box.h / 2.0)
    var best = tolerance * tolerance
    var hit = miss
    for si in 0..<series.count {
      let pts = radarPolygon(series[si].values, axes, center, radius)
      for ai in 0..<pts.count {
        let dx = pts[ai].x - px
        let dy = pts[ai].y - py
        let d = dx * dx + dy * dy
        if d <= best {
          best = d
          hit = RadarHitIndex(series: si, axis: ai)
        }
      }
    }
    return hit
  }

public func computeLayout(_ cfg: LayoutConfig, _ measure: (String, Double) -> Double) -> PlotLayout {
    let padTop = 8.0
    let padRight = 12.0
    let labelGap = 6.0
    let tickLen = 4.0
    let titleH = cfg.fontSize + labelGap
    let isLog = cfg.yLog == true
    let logMin = (cfg.yLogMin ?? 1.0)
    let logMax = (cfg.yLogMax ?? 10.0)
    let valueTicksY = { (r0: Double, r1: Double) in isLog ? logViewTicks(logMin, logMax, cfg.yDomain.inverse == true ? r1 : r0, cfg.yDomain.inverse == true ? r0 : r1, cfg.yFormat) : cfg.yTime == true ? timeTicks(cfg.yDomain, r0, r1, cfg.yTickCount, cfg.yFormat) : makeTicks(cfg.yDomain, r0, r1, cfg.yTickCount, cfg.yFormat) }
    let provisionalLabels = cfg.horizontal == true ? cfg.showYAxis ? cfg.categories : [] : cfg.showYAxis ? valueTicksY(cfg.height, 0.0).map({ t in t.label }) : []
    var widest = 0.0
    for label in provisionalLabels {
      var w = measure(label, cfg.fontSize)
      if w > widest {
        widest = w
      }
    }
    let yTitleH = cfg.yTitle != nil && cfg.yTitle != "" && cfg.showYAxis ? titleH : 0.0
    let yBand = (cfg.showYAxis ? widest + labelGap + tickLen + ((cfg.yOffset ?? 0.0)) : 0.0) + yTitleH
    let xTitleH = cfg.xTitle != nil && cfg.xTitle != "" && cfg.showXAxis ? titleH : 0.0
    let y2dom = (cfg.y2Domain ?? Domain(min: 0.0, max: 1.0))
    let hasY2 = cfg.y2Domain != nil && cfg.horizontal != true && cfg.showYAxis
    var widest2 = 0.0
    if hasY2 {
      for label in makeTicks(y2dom, cfg.height, 0.0, cfg.yTickCount, cfg.y2Format).map({ t in t.label }) {
        var w = measure(label, cfg.fontSize)
        if w > widest2 {
          widest2 = w
        }
      }
    }
    let y2TitleH = hasY2 && cfg.y2Title != nil && cfg.y2Title != "" ? titleH : 0.0
    let yRight = cfg.yRight == true && !hasY2 && cfg.horizontal != true
    let leftBase = yRight ? padRight : yBand
    let rightBase = yRight ? yBand : (hasY2 ? widest2 + labelGap + tickLen + ((cfg.y2Offset ?? 0.0)) : padRight) + y2TitleH
    var leftExtra = 0.0
    var rightExtra = 0.0
    if cfg.horizontal != true && cfg.showYAxis {
      for a in (cfg.extraYAxes ?? []) {
        var w = 0.0
        for tk in makeTicks((a.domain ?? Domain(min: 0.0, max: 1.0)), cfg.height, 0.0, cfg.yTickCount, nil) {
          let lw = measure(tk.label, cfg.fontSize)
          if lw > w {
            w = lw
          }
        }
        let band = ((a.offset ?? 0.0)) + w + labelGap + tickLen + (a.title != nil && a.title != "" ? titleH : 0.0)
        if a.side == "left" {
          if band > leftExtra {
            leftExtra = band
          }
        } else {
          if band > rightExtra {
            rightExtra = band
          }
        }
      }
    }
    let left = leftBase > leftExtra ? leftBase : leftExtra
    let right = rightBase > rightExtra ? rightBase : rightExtra
    let provisionalW = max(0.0, cfg.width - left - right)
    let mode = (cfg.xLabels ?? "auto")
    var rotate = 0.0
    var every = 1
    var slantH = 0.0
    if cfg.showXAxis && cfg.horizontal != true {
      let xLabels = cfg.categories.count > 0 ? cfg.categories : (cfg.xTime == true ? timeTicks(cfg.xDomain, 0.0, provisionalW, cfg.xTickCount, cfg.xFormat) : makeTicks(cfg.xDomain, 0.0, provisionalW, cfg.xTickCount, cfg.xFormat)).map({ t in t.label })
      var need = 0.0
      var widestX = 0.0
      for label in xLabels {
        var w = measure(label, cfg.fontSize)
        need = need + w + labelGap
        if w > widestX {
          widestX = w
        }
      }
      let overflow = need > provisionalW && xLabels.count > 1
      let wantRotate = mode == "rotate" || (mode == "auto" && overflow && cfg.categories.count > 0)
      if wantRotate && xLabels.count > 0 {
        rotate = -45.0
        slantH = (widestX + cfg.fontSize) * 0.7071 - cfg.fontSize
        if slantH < 0.0 {
          slantH = 0.0
        }
        let bandW = provisionalW / Double(xLabels.count)
        let perLabel = cfg.fontSize * 1.3
        if bandW < perLabel && bandW > 0.0 {
          every = ceilRatio(perLabel, bandW)
        }
      } else {
        if mode != "all" && overflow && (mode == "thin" || mode == "auto") {
          every = ceilRatio(need, provisionalW)
        }
      }
    }
    let xBand = (cfg.showXAxis ? cfg.fontSize + labelGap + tickLen + slantH + ((cfg.xOffset ?? 0.0)) : 0.0) + xTitleH
    let xTop = cfg.xTop == true && cfg.horizontal != true
    let hasX2 = (((cfg.x2Labels ?? [])).count > 0 || cfg.x2Domain != nil) && cfg.showXAxis && cfg.horizontal != true
    let x2Band = hasX2 ? cfg.fontSize + labelGap + tickLen + (cfg.x2Title != nil && cfg.x2Title != "" ? titleH : 0.0) : padTop
    let top = (cfg.insetTop ?? (xTop ? xBand : x2Band))
    let bottom = (cfg.insetBottom ?? (xTop ? x2Band : xBand))
    let gLeft = (cfg.insetLeft ?? left)
    let gRight = (cfg.insetRight ?? right)
    let gutters = Gutters(left: gLeft, right: gRight, top: top, bottom: bottom)
    let plot = PyreonChartRect(x: gLeft, y: top, w: max(0.0, cfg.width - gLeft - gRight), h: max(0.0, cfg.height - top - bottom))
    if cfg.horizontal == true {
      let yTicks = cfg.showYAxis ? bandTicksY(cfg.categories, plot) : []
      let xTicks = cfg.showXAxis ? makeTicks(cfg.yDomain, plot.x, plot.x + plot.w, cfg.yTickCount, cfg.yFormat) : []
      var yEvery = 1
      let nCat = cfg.categories.count
      if nCat > 0 && plot.h > 0.0 {
        let bandH = plot.h / Double(nCat)
        let perLabel = cfg.fontSize + 2.0
        if bandH < perLabel {
          yEvery = ceilRatio(perLabel, bandH)
        }
      }
      return PlotLayout(plot: plot, xTicks: xTicks, yTicks: yTicks, y2Ticks: [], xDomainUsed: cfg.xDomain, xLabelRotate: 0.0, xLabelEvery: 1, yLabelEvery: yEvery, gutters: gutters, extraTicks: [], x2Ticks: [])
    }
    let yTicks = cfg.showYAxis ? valueTicksY(plot.y + plot.h, plot.y) : []
    let xTicks = cfg.showXAxis ? cfg.categories.count > 0 ? cfg.edgeCategories == true ? edgeTicks(cfg.categories, plot) : bandTicks(cfg.categories, plot) : cfg.xTime == true ? timeTicks(cfg.xDomain, plot.x, plot.x + plot.w, cfg.xTickCount, cfg.xFormat) : makeTicks(cfg.xDomain, plot.x, plot.x + plot.w, cfg.xTickCount, cfg.xFormat) : []
    let y2Ticks = hasY2 ? makeTicks(y2dom, plot.y + plot.h, plot.y, cfg.yTickCount, cfg.y2Format) : []
    var extraTicks: [ExtraTick] = []
    if cfg.showYAxis {
      var ai = 0.0
      for a in (cfg.extraYAxes ?? []) {
        for tk in makeTicks((a.domain ?? Domain(min: 0.0, max: 1.0)), plot.y + plot.h, plot.y, cfg.yTickCount, nil) {
          extraTicks.append(ExtraTick(axis: ai, pos: tk.pos, label: tk.label))
        }
        ai = ai + 1.0
      }
    }
    let x2Ticks = hasX2 && cfg.x2Domain != nil ? makeTicks((cfg.x2Domain ?? Domain(min: 0.0, max: 1.0)), plot.x, plot.x + plot.w, cfg.xTickCount, nil) : []
    return PlotLayout(plot: plot, xTicks: xTicks, yTicks: yTicks, y2Ticks: y2Ticks, xDomainUsed: cfg.xDomain, xLabelRotate: rotate, xLabelEvery: every, yLabelEvery: 1, gutters: gutters, extraTicks: extraTicks, x2Ticks: x2Ticks)
  }

public func ceilRatio(_ need: Double, _ room: Double) -> Int {
    if !(room > 0.0) {
      return 1
    }
    var every = 1
    var acc = room
    while acc < need && every < 200 {
      every = every + 1
      acc = acc + room
    }
    return every
  }

public func bandTicksY(_ categories: [String], _ plot: PyreonChartRect) -> [Tick] {
    let n = categories.count
    var out: [Tick] = []
    if n == 0 {
      return out
    }
    let bh = plot.h / Double(n)
    for i in 0..<n {
      out.append(Tick(value: Double(i), pos: plot.y + bh * (Double(i) + 0.5), label: categories[i]))
    }
    return out
  }

public func bandTicks(_ categories: [String], _ plot: PyreonChartRect) -> [Tick] {
    let n = categories.count
    var out: [Tick] = []
    if n == 0 {
      return out
    }
    let bw = plot.w / Double(n)
    for i in 0..<n {
      out.append(Tick(value: Double(i), pos: plot.x + bw * (Double(i) + 0.5), label: categories[i]))
    }
    return out
  }

public func layoutBars(_ values: [Double], _ plot: PyreonChartRect, _ yDomain: Domain, _ gapRatio: Double) -> [PyreonChartRect] {
    let n = values.count
    var out: [PyreonChartRect] = []
    if n == 0 {
      return out
    }
    let ratio = gapRatio < 0.0 ? 0.0 : gapRatio > 0.9 ? 0.9 : gapRatio
    let band = plot.w / Double(n)
    let bw = band * (1.0 - ratio)
    let zero = yDomain.min < 0.0 && yDomain.max > 0.0 ? 0.0 : yDomain.min
    let zeroY = scaleLinear(yDomain, plot.y + plot.h, plot.y, zero)
    for i in 0..<n {
      let raw = values[i]
      let v = isFiniteNumber(raw) ? raw : zero
      let vy = scaleLinear(yDomain, plot.y + plot.h, plot.y, v)
      let top = vy < zeroY ? vy : zeroY
      let h = abs(zeroY - vy)
      out.append(PyreonChartRect(x: plot.x + band * Double(i) + (band - bw) / 2.0, y: top, w: bw, h: h))
    }
    return out
  }

public func layoutSeriesPoints(_ values: [Double], _ plot: PyreonChartRect, _ yDomain: Domain) -> [PyreonChartPt] {
    let n = values.count
    var out: [PyreonChartPt] = []
    if n == 0 {
      return out
    }
    let band = plot.w / Double(n)
    for i in 0..<n {
      out.append(PyreonChartPt(x: plot.x + band * Double(i) + band / 2.0, y: scaleLinear(yDomain, plot.y + plot.h, plot.y, values[i])))
    }
    return out
  }

public func layoutSeriesPointsEdge(_ values: [Double], _ plot: PyreonChartRect, _ yDomain: Domain) -> [PyreonChartPt] {
    let n = values.count
    var out: [PyreonChartPt] = []
    if n == 0 {
      return out
    }
    if n == 1 {
      out.append(PyreonChartPt(x: plot.x + plot.w / 2.0, y: scaleLinear(yDomain, plot.y + plot.h, plot.y, values[0])))
      return out
    }
    for i in 0..<n {
      out.append(PyreonChartPt(x: plot.x + (Double(i) / Double((n - 1))) * plot.w, y: scaleLinear(yDomain, plot.y + plot.h, plot.y, values[i])))
    }
    return out
  }

public func edgeTicks(_ categories: [String], _ plot: PyreonChartRect) -> [Tick] {
    let n = categories.count
    var out: [Tick] = []
    if n == 0 {
      return out
    }
    for i in 0..<n {
      out.append(Tick(value: Double(i), pos: n == 1 ? plot.x + plot.w / 2.0 : plot.x + (Double(i) / Double((n - 1))) * plot.w, label: categories[i]))
    }
    return out
  }

public func layoutSeriesPointsH(_ values: [Double], _ plot: PyreonChartRect, _ vDomain: Domain) -> [PyreonChartPt] {
    let n = values.count
    var out: [PyreonChartPt] = []
    if n == 0 {
      return out
    }
    let band = plot.h / Double(n)
    for i in 0..<n {
      out.append(PyreonChartPt(x: scaleLinear(vDomain, plot.x, plot.x + plot.w, values[i]), y: plot.y + band * Double(i) + band / 2.0))
    }
    return out
  }

public func layoutSeriesPointsAt(_ values: [Double], _ xs: [Double], _ plot: PyreonChartRect, _ yDomain: Domain, _ xDomain: Domain) -> [PyreonChartPt] {
    let n = min(values.count, xs.count)
    var out: [PyreonChartPt] = []
    for i in 0..<n {
      out.append(PyreonChartPt(x: scaleLinear(xDomain, plot.x, plot.x + plot.w, xs[i]), y: scaleLinear(yDomain, plot.y + plot.h, plot.y, values[i])))
    }
    return out
  }

public func layoutBarsH(_ values: [Double], _ plot: PyreonChartRect, _ vDomain: Domain, _ gapRatio: Double) -> [PyreonChartRect] {
    let n = values.count
    var out: [PyreonChartRect] = []
    if n == 0 {
      return out
    }
    let ratio = gapRatio < 0.0 ? 0.0 : gapRatio > 0.9 ? 0.9 : gapRatio
    let band = plot.h / Double(n)
    let bh = band * (1.0 - ratio)
    let zero = vDomain.min < 0.0 && vDomain.max > 0.0 ? 0.0 : vDomain.min
    let zeroX = scaleLinear(vDomain, plot.x, plot.x + plot.w, zero)
    for i in 0..<n {
      let raw = values[i]
      let v = isFiniteNumber(raw) ? raw : zero
      let vx = scaleLinear(vDomain, plot.x, plot.x + plot.w, v)
      let left = vx < zeroX ? vx : zeroX
      out.append(PyreonChartRect(x: left, y: plot.y + band * Double(i) + (band - bh) / 2.0, w: abs(vx - zeroX), h: bh))
    }
    return out
  }

public func hitBar(_ bars: [PyreonChartRect], _ px: Double, _ py: Double) -> Int {
    for i in 0..<bars.count {
      let b = bars[i]
      if px >= b.x && px <= b.x + b.w && py >= b.y && py <= b.y + b.h {
        return i
      }
    }
    return -1
  }

public func hitNearestX(_ points: [PyreonChartPt], _ px: Double) -> Int {
    if points.count == 0 {
      return -1
    }
    var best = 0
    var bestD = abs(points[0].x - px)
    for i in 1..<points.count {
      let d = abs(points[i].x - px)
      if d < bestD {
        bestD = d
        best = i
      }
    }
    return best
  }

public func layoutStackedBars(_ seriesValues: [[Double]], _ plot: PyreonChartRect, _ yDomain: Domain, _ gapRatio: Double) -> [StackSegment] {
    var out: [StackSegment] = []
    if seriesValues.count == 0 {
      return out
    }
    var n = 0
    for s in seriesValues {
      if s.count > n {
        n = s.count
      }
    }
    if n == 0 {
      return out
    }
    let ratio = gapRatio < 0.0 ? 0.0 : gapRatio > 0.9 ? 0.9 : gapRatio
    let band = plot.w / Double(n)
    let bw = band * (1.0 - ratio)
    for i in 0..<n {
      var acc = 0.0
      for s in 0..<seriesValues.count {
        let v = (seriesValues[s][i] ?? 0.0)
        if !(v > 0.0) {
          continue
        }
        let yTop = scaleLinear(yDomain, plot.y + plot.h, plot.y, acc + v)
        let yBot = scaleLinear(yDomain, plot.y + plot.h, plot.y, acc)
        out.append(StackSegment(rect: PyreonChartRect(x: plot.x + band * Double(i) + (band - bw) / 2.0, y: yTop < yBot ? yTop : yBot, w: bw, h: Double(abs(yBot - yTop))), seriesIndex: s, datumIndex: i, value: v))
        acc = acc + v
      }
    }
    return out
  }

public func layoutStackedBarsH(_ seriesValues: [[Double]], _ plot: PyreonChartRect, _ vDomain: Domain, _ gapRatio: Double) -> [StackSegment] {
    var out: [StackSegment] = []
    if seriesValues.count == 0 {
      return out
    }
    var n = 0
    for s in seriesValues {
      if s.count > n {
        n = s.count
      }
    }
    if n == 0 {
      return out
    }
    let ratio = gapRatio < 0.0 ? 0.0 : gapRatio > 0.9 ? 0.9 : gapRatio
    let band = plot.h / Double(n)
    let bh = band * (1.0 - ratio)
    for i in 0..<n {
      var acc = 0.0
      for s in 0..<seriesValues.count {
        let v = (seriesValues[s][i] ?? 0.0)
        if !(v > 0.0) {
          continue
        }
        let xEnd = scaleLinear(vDomain, plot.x, plot.x + plot.w, acc + v)
        let xStart = scaleLinear(vDomain, plot.x, plot.x + plot.w, acc)
        out.append(StackSegment(rect: PyreonChartRect(x: xStart < xEnd ? xStart : xEnd, y: plot.y + band * Double(i) + (band - bh) / 2.0, w: Double(abs(xEnd - xStart)), h: bh), seriesIndex: s, datumIndex: i, value: v))
        acc = acc + v
      }
    }
    return out
  }

public func layoutGroupedBarsH(_ seriesValues: [[Double]], _ plot: PyreonChartRect, _ vDomain: Domain, _ gapRatio: Double) -> [StackSegment] {
    var out: [StackSegment] = []
    let k = seriesValues.count
    if k == 0 {
      return out
    }
    var n = 0
    for s in seriesValues {
      if s.count > n {
        n = s.count
      }
    }
    if n == 0 {
      return out
    }
    let ratio = gapRatio < 0.0 ? 0.0 : gapRatio > 0.9 ? 0.9 : gapRatio
    let band = plot.h / Double(n)
    let groupH = band * (1.0 - ratio)
    let barH = groupH / Double(k)
    let zero = vDomain.min < 0.0 && vDomain.max > 0.0 ? 0.0 : vDomain.min
    let zeroX = scaleLinear(vDomain, plot.x, plot.x + plot.w, zero)
    for i in 0..<n {
      let gy = plot.y + band * Double(i) + (band - groupH) / 2.0
      for s in 0..<k {
        let raw = (seriesValues[s][i] ?? 0.0)
        let v = raw == raw ? raw : zero
        let vx = scaleLinear(vDomain, plot.x, plot.x + plot.w, v)
        out.append(StackSegment(rect: PyreonChartRect(x: vx < zeroX ? vx : zeroX, y: gy + barH * Double(s), w: abs(vx - zeroX), h: barH), seriesIndex: s, datumIndex: i, value: v))
      }
    }
    return out
  }

public func stackCumulative(_ seriesValues: [[Double]]) -> [[Double]] {
    var out: [[Double]] = []
    var n = 0
    for s in seriesValues {
      if s.count > n {
        n = s.count
      }
    }
    var acc: [Double] = []
    for i in 0..<n {
      acc.append(0.0)
    }
    for s in seriesValues {
      var row: [Double] = []
      for i in 0..<n {
        let v = i < s.count ? s[i] : 0.0
        if v > 0.0 {
          acc[i] = acc[i] + v
        }
        row.append(acc[i])
      }
      out.append(row)
    }
    return out
  }

public func stackHasNegatives(_ seriesValues: [[Double]]) -> Bool {
    for s in seriesValues {
      for v in s {
        if v < 0.0 {
          return true
        }
      }
    }
    return false
  }

public func stackedExtent(_ seriesValues: [[Double]]) -> Domain {
    var n = 0
    for s in seriesValues {
      if s.count > n {
        n = s.count
      }
    }
    var max = 0.0
    for i in 0..<n {
      var sum = 0.0
      for s in seriesValues {
        let v = (s[i] ?? 0.0)
        if v > 0.0 {
          sum = sum + v
        }
      }
      if sum > max {
        max = sum
      }
    }
    return Domain(min: 0.0, max: max == 0.0 ? 1.0 : max)
  }

public func layoutGroupedBars(_ seriesValues: [[Double]], _ plot: PyreonChartRect, _ yDomain: Domain, _ gapRatio: Double) -> [StackSegment] {
    var out: [StackSegment] = []
    let k = seriesValues.count
    if k == 0 {
      return out
    }
    var n = 0
    for s in seriesValues {
      if s.count > n {
        n = s.count
      }
    }
    if n == 0 {
      return out
    }
    let ratio = gapRatio < 0.0 ? 0.0 : gapRatio > 0.9 ? 0.9 : gapRatio
    let band = plot.w / Double(n)
    let groupW = band * (1.0 - ratio)
    let barW = groupW / Double(k)
    let zero = yDomain.min < 0.0 && yDomain.max > 0.0 ? 0.0 : yDomain.min
    let zeroY = scaleLinear(yDomain, plot.y + plot.h, plot.y, zero)
    for i in 0..<n {
      let gx = plot.x + band * Double(i) + (band - groupW) / 2.0
      for s in 0..<k {
        let raw = (seriesValues[s][i] ?? 0.0)
        let v = isFiniteNumber(raw) ? raw : zero
        let vy = scaleLinear(yDomain, plot.y + plot.h, plot.y, v)
        out.append(StackSegment(rect: PyreonChartRect(x: gx + barW * Double(s), y: vy < zeroY ? vy : zeroY, w: barW, h: abs(zeroY - vy)), seriesIndex: s, datumIndex: i, value: v))
      }
    }
    return out
  }

public func layoutScatter(_ xs: [Double], _ ys: [Double], _ plot: PyreonChartRect, _ xDomain: Domain, _ yDomain: Domain) -> [PyreonChartPt] {
    let n = min(xs.count, ys.count)
    var out: [PyreonChartPt] = []
    for i in 0..<n {
      out.append(PyreonChartPt(x: scaleLinear(xDomain, plot.x, plot.x + plot.w, xs[i]), y: scaleLinear(yDomain, plot.y + plot.h, plot.y, ys[i])))
    }
    return out
  }

public func normalizeStack(_ seriesValues: [[Double]]) -> [[Double]] {
    var n = 0
    for s in seriesValues {
      if s.count > n {
        n = s.count
      }
    }
    var totals: [Double] = []
    for i in 0..<n {
      var sum = 0.0
      for s in seriesValues {
        let v = i < s.count ? s[i] : 0.0
        if v > 0.0 {
          sum = sum + v
        }
      }
      totals.append(sum)
    }
    var out: [[Double]] = []
    for s in seriesValues {
      var row: [Double] = []
      for i in 0..<s.count {
        let v = s[i]
        let total = totals[i]
        row.append(total > 0.0 ? Double(v) / Double(total) : isFiniteNumber(v) ? 0.0 : v)
      }
      out.append(row)
    }
    return out
  }

public func layoutWaterfall(_ values: [Double], _ plot: PyreonChartRect, _ yDomain: Domain, _ gapRatio: Double) -> [WaterfallStep] {
    var out: [WaterfallStep] = []
    let n = values.count
    if n == 0 {
      return out
    }
    let ratio = gapRatio < 0.0 ? 0.0 : gapRatio > 0.9 ? 0.9 : gapRatio
    let band = plot.w / Double(n)
    let bw = band * (1.0 - ratio)
    var acc = 0.0
    for i in 0..<n {
      let v = values[i]
      if !isFiniteNumber(v) {
        continue
      }
      let start = acc
      let end = acc + v
      let y0 = scaleLinear(yDomain, plot.y + plot.h, plot.y, start)
      let y1 = scaleLinear(yDomain, plot.y + plot.h, plot.y, end)
      out.append(WaterfallStep(rect: PyreonChartRect(x: plot.x + band * Double(i) + (band - bw) / 2.0, y: y0 < y1 ? y0 : y1, w: bw, h: Double(abs(y1 - y0))), datumIndex: i, value: v, start: start, end: end))
      acc = end
    }
    return out
  }

public func waterfallExtent(_ values: [Double]) -> Domain {
    var acc = 0.0
    var lo = 0.0
    var hi = 0.0
    for v in values {
      if !isFiniteNumber(v) {
        continue
      }
      acc = acc + v
      if acc < lo {
        lo = acc
      }
      if acc > hi {
        hi = acc
      }
    }
    return Domain(min: lo, max: hi == lo ? lo + 1.0 : hi)
  }

public func symbolPoints(_ cell: PyreonChartRect, _ symbol: String) -> [PyreonChartPt] {
    if symbol == "circle" {
      let r = (cell.w < cell.h ? cell.w : cell.h) / 2.0
      let cx = cell.x + cell.w / 2.0
      let cy = cell.y + cell.h / 2.0
      var pts: [PyreonChartPt] = []
      for i in 0..<POLYGON_CIRCLE_SIDES {
        let a = (Double.pi * 2.0 * Double(i)) / Double(POLYGON_CIRCLE_SIDES)
        pts.append(PyreonChartPt(x: cx + cos(Double(a)) * r, y: cy + sin(Double(a)) * r))
      }
      return pts
    }
    if symbol == "diamond" {
      return [PyreonChartPt(x: cell.x + cell.w / 2.0, y: cell.y), PyreonChartPt(x: cell.x + cell.w, y: cell.y + cell.h / 2.0), PyreonChartPt(x: cell.x + cell.w / 2.0, y: cell.y + cell.h), PyreonChartPt(x: cell.x, y: cell.y + cell.h / 2.0)]
    }
    if symbol == "triangle" {
      return [PyreonChartPt(x: cell.x + cell.w / 2.0, y: cell.y), PyreonChartPt(x: cell.x + cell.w, y: cell.y + cell.h), PyreonChartPt(x: cell.x, y: cell.y + cell.h)]
    }
    return [PyreonChartPt(x: cell.x, y: cell.y), PyreonChartPt(x: cell.x + cell.w, y: cell.y), PyreonChartPt(x: cell.x + cell.w, y: cell.y + cell.h), PyreonChartPt(x: cell.x, y: cell.y + cell.h)]
  }

public func rotatePoints(_ points: [PyreonChartPt], _ center: PyreonChartPt, _ degrees: Double) -> [PyreonChartPt] {
    if degrees == 0.0 {
      return points
    }
    let a = (degrees * Double.pi) / 180.0
    let c = cos(Double(a))
    let s = sin(Double(a))
    var out: [PyreonChartPt] = []
    for p in points {
      let dx = p.x - center.x
      let dy = p.y - center.y
      out.append(PyreonChartPt(x: center.x + dx * c - dy * s, y: center.y + dx * s + dy * c))
    }
    return out
  }

public func clipPolygonToRect(_ points: [PyreonChartPt], _ rect: PyreonChartRect) -> [PyreonChartPt] {
    var current = points
    let x0 = rect.x
    let x1 = rect.x + rect.w
    let y0 = rect.y
    let y1 = rect.y + rect.h
    for edge in 0..<4 {
      if current.count == 0 {
        return current
      }
      var next: [PyreonChartPt] = []
      for i in 0..<current.count {
        let p = current[i]
        let q = current[(i + 1) % current.count]
        let pIn = insideEdge(p, edge, x0, x1, y0, y1)
        let qIn = insideEdge(q, edge, x0, x1, y0, y1)
        if pIn && qIn {
          next.append(q)
        } else {
          if pIn && !qIn {
            next.append(intersectEdge(p, q, edge, x0, x1, y0, y1))
          } else {
            if !pIn && qIn {
              next.append(intersectEdge(p, q, edge, x0, x1, y0, y1))
              next.append(q)
            }
          }
        }
      }
      current = next
    }
    return current
  }

public func insideEdge(_ p: PyreonChartPt, _ edge: Int, _ x0: Double, _ x1: Double, _ y0: Double, _ y1: Double) -> Bool {
    if edge == 0 {
      return p.x >= x0
    }
    if edge == 1 {
      return p.x <= x1
    }
    if edge == 2 {
      return p.y >= y0
    }
    return p.y <= y1
  }

public func intersectEdge(_ p: PyreonChartPt, _ q: PyreonChartPt, _ edge: Int, _ x0: Double, _ x1: Double, _ y0: Double, _ y1: Double) -> PyreonChartPt {
    if edge == 0 || edge == 1 {
      let x = edge == 0 ? x0 : x1
      let t = q.x == p.x ? 0.0 : (x - p.x) / (q.x - p.x)
      return PyreonChartPt(x: x, y: p.y + (q.y - p.y) * t)
    }
    let y = edge == 2 ? y0 : y1
    let t = q.y == p.y ? 0.0 : (y - p.y) / (q.y - p.y)
    return PyreonChartPt(x: p.x + (q.x - p.x) * t, y: y)
  }

public func symbolCommands(_ cell: PyreonChartRect, _ b: PictorialBar, _ clipTo: PyreonChartRect?) -> [PyreonDrawCmd] {
    var out: [PyreonDrawCmd] = []
    let needsPolygon = b.symbol != "rect" || b.rotate != 0.0 || clipTo != nil
    let nudged = PyreonChartRect(x: cell.x + b.offsetX, y: cell.y + b.offsetY, w: cell.w, h: cell.h)
    if b.symbol == "circle" && b.rotate == 0.0 && clipTo == nil {
      let r = (nudged.w < nudged.h ? nudged.w : nudged.h) / 2.0
      out.append(PyreonDrawCmd(kind: "circle", fill: b.fill, center: PyreonChartPt(x: nudged.x + nudged.w / 2.0, y: nudged.y + nudged.h / 2.0), radius: r))
      return out
    }
    if !needsPolygon {
      out.append(PyreonDrawCmd(kind: "rect", rect: nudged, fill: b.fill))
      return out
    }
    var pts = symbolPoints(nudged, b.symbol)
    if b.rotate != 0.0 {
      pts = rotatePoints(pts, PyreonChartPt(x: nudged.x + nudged.w / 2.0, y: nudged.y + nudged.h / 2.0), b.rotate)
    }
    if let clipTo {
      pts = clipPolygonToRect(pts, clipTo)
    }
    if pts.count >= 3 {
      out.append(PyreonDrawCmd(kind: "polygon", fill: b.fill, points: pts))
    }
    return out
  }

public func pictorialCommands(_ b: PictorialBar) -> [PyreonDrawCmd] {
    var out: [PyreonDrawCmd] = []
    let bar = b.bar
    let barLength = b.horizontal ? bar.w : bar.h
    let unit = b.horizontal ? bar.h : bar.w
    let runLength = b.hasBounding && isFiniteNumber(b.boundingLength) ? b.boundingLength : barLength
    let clipTo = b.clip ? bar : nil
    var shift = 0.0
    if b.position == "end" {
      shift = barLength - runLength
    } else {
      if b.position == "center" {
        shift = (barLength - runLength) / 2.0
      }
    }
    let cellAt = { (from: Double, length: Double) in b.horizontal ? PyreonChartRect(x: bar.x + from, y: bar.y, w: length, h: unit) : PyreonChartRect(x: bar.x, y: bar.y + bar.h - from - length, w: unit, h: length) }
    if !b.`repeat` {
      let cell = cellAt(shift, runLength)
      if !b.clip && (shift < 0.0 || shift + runLength > barLength + 0.001) {
        for c in symbolCommands(cell, b, nil) {
          out.append(c)
        }
        return out
      }
      for c in symbolCommands(cell, b, clipTo) {
        out.append(c)
      }
      return out
    }
    let step = unit + b.margin
    if unit <= 0.0 || step <= 0.0 {
      return out
    }
    var from = shift
    for k in 0..<400 {
      let end = from + unit
      if from >= shift + runLength - 0.001 && !b.clip {
        break
      }
      if from >= shift + runLength - 0.001 {
        break
      }
      let overRun = end > shift + runLength + 0.001
      if overRun && !b.clip {
        break
      }
      let overBar = end > barLength + 0.001 || from < -0.001
      if overBar && !b.clip {
        break
      }
      let length = overRun ? shift + runLength - from : unit
      let cell = cellAt(from, unit)
      let clipRect = b.clip ? (overRun ? intersectRect(bar, cellAt(from, length)) : clipTo) : nil
      for c in symbolCommands(cell, b, clipRect) {
        out.append(c)
      }
      from = from + step
    }
    return out
  }

public func intersectRect(_ a: PyreonChartRect, _ c: PyreonChartRect) -> PyreonChartRect {
    let x0 = a.x > c.x ? a.x : c.x
    let y0 = a.y > c.y ? a.y : c.y
    let x1 = a.x + a.w < c.x + c.w ? a.x + a.w : c.x + c.w
    let y1 = a.y + a.h < c.y + c.h ? a.y + a.h : c.y + c.h
    return PyreonChartRect(x: x0, y: y0, w: x1 - x0 > 0.0 ? x1 - x0 : 0.0, h: y1 - y0 > 0.0 ? y1 - y0 : 0.0)
  }

public func arcSweep(_ startAngle: Double, _ endAngle: Double, _ clockwise: Bool) -> PyreonChartPt {
    let from = clockwise ? startAngle : endAngle
    var to = clockwise ? endAngle : startAngle
    if to < from {
      to = to + FULL_TURN * ceil(Double((from - to) / Double(FULL_TURN)))
    }
    if to - from > FULL_TURN {
      to = from + FULL_TURN
    }
    return PyreonChartPt(x: from, y: to)
  }

public func bezierPoints(_ control: [PyreonChartPt]) -> [PyreonChartPt] {
    var out: [PyreonChartPt] = []
    if control.count < 3 {
      return control
    }
    let cubic = control.count >= 4
    let p0 = control[0]
    let c1 = control[1]
    let c2 = cubic ? control[2] : control[1]
    let p1 = cubic ? control[3] : control[2]
    for i in 0...BEZIER_STEPS {
      let t = Double(i) / Double(BEZIER_STEPS)
      let u = 1.0 - t
      let x = u * u * u * p0.x + 3.0 * u * u * t * c1.x + 3.0 * u * t * t * c2.x + t * t * t * p1.x
      let y = u * u * u * p0.y + 3.0 * u * u * t * c1.y + 3.0 * u * t * t * c2.y + t * t * t * p1.y
      out.append(PyreonChartPt(x: x, y: y))
    }
    return out
  }

public func graphicElementCommands(_ e: GraphicElement) -> [PyreonDrawCmd] {
    var out: [PyreonDrawCmd] = []
    let at = { (p: PyreonChartPt) in (PyreonChartPt(x: e.x + p.x, y: e.y + p.y)) }
    let centre = PyreonChartPt(x: e.x + e.cx, y: e.y + e.cy)
    if e.kind == "text" {
      let align = e.align == "middle" ? "middle" : e.align == "end" ? "end" : "start"
      out.append(PyreonDrawCmd(kind: "text", fill: e.fill, text: e.text, at: PyreonChartPt(x: e.x, y: e.y), size: e.fontSize, align: align, baseline: "top"))
      return out
    }
    if e.kind == "rect" {
      out.append(PyreonDrawCmd(kind: "rect", rect: PyreonChartRect(x: e.x + e.cx, y: e.y + e.cy, w: e.w, h: e.h), fill: e.fill))
      return out
    }
    if e.kind == "circle" {
      out.append(PyreonDrawCmd(kind: "circle", fill: e.fill, center: centre, radius: e.r))
      return out
    }
    if e.kind == "line" {
      let zero = PyreonChartPt(x: 0.0, y: 0.0)
      out.append(PyreonDrawCmd(kind: "line", from: at(e.points.count > 0 ? e.points[0] : zero), to: at(e.points.count > 1 ? e.points[1] : zero), stroke: e.stroke, width: e.lineWidth))
      return out
    }
    if e.kind == "polygon" {
      let pts = e.points.map(at)
      if pts.count >= 2 {
        out.append(PyreonDrawCmd(kind: "polygon", fill: e.fill, points: pts))
      }
      return out
    }
    if e.kind == "polyline" {
      let pts = e.points.map(at)
      if pts.count >= 2 {
        out.append(PyreonDrawCmd(kind: "polyline", stroke: e.stroke, width: e.lineWidth, points: pts))
      }
      return out
    }
    if e.kind == "bezier" {
      let pts = bezierPoints(e.points).map(at)
      if pts.count >= 2 {
        out.append(PyreonDrawCmd(kind: "polyline", stroke: e.stroke, width: e.lineWidth, points: pts))
      }
      return out
    }
    if e.kind == "ring" {
      if e.r > 0.0 {
        out.append(PyreonDrawCmd(kind: "polygon", fill: e.fill, points: arcPolygon(centre, e.r, e.r0, 0.0, FULL_TURN)))
      }
      return out
    }
    if e.kind == "sector" {
      let sweep = arcSweep(e.startAngle, e.endAngle, e.clockwise)
      if e.r > 0.0 && sweep.y > sweep.x {
        out.append(PyreonDrawCmd(kind: "polygon", fill: e.fill, points: arcPolygon(centre, e.r, e.r0, sweep.x, sweep.y)))
      }
      return out
    }
    if e.kind == "arc" {
      let sweep = arcSweep(e.startAngle, e.endAngle, e.clockwise)
      if e.r > 0.0 && sweep.y > sweep.x {
        let fan = arcPolygon(centre, e.r, 0.0, sweep.x, sweep.y)
        var edge: [PyreonChartPt] = []
        for i in 0..<fan.count - 1 {
          edge.append(fan[i])
        }
        if edge.count >= 2 {
          out.append(PyreonDrawCmd(kind: "polyline", stroke: e.stroke, width: e.lineWidth, points: edge))
        }
      }
      return out
    }
    return out
  }

public func graphicDrawCommands(_ elements: [GraphicElement]) -> [PyreonDrawCmd] {
    var out: [PyreonDrawCmd] = []
    for e in elements {
      for c in graphicElementCommands(e) {
        out.append(c)
      }
    }
    return out
  }

public func labelLineSegments(_ line: String, _ rich: [RichStyle], _ color: String, _ size: Double) -> [LabelSegment] {
    var segments: [LabelSegment] = []
    var plain = ""
    var inTag = false
    var sawBar = false
    var tagName = ""
    var tagBody = ""
    for i in 0..<line.utf16.count {
      let ch = String(Array(line)[i])
      var handled = false
      if inTag {
        if ch == "|" && !sawBar {
          sawBar = true
          handled = true
        } else {
          if ch == "}" && sawBar {
            if plain != "" {
              segments.append(LabelSegment(text: plain, color: color, fontSize: size))
            }
            plain = ""
            var segColor = color
            var segSize = size
            for r in rich {
              if r.name == tagName {
                if r.color != "" {
                  segColor = r.color
                }
                if r.fontSize > 0.0 {
                  segSize = r.fontSize
                }
              }
            }
            segments.append(LabelSegment(text: tagBody, color: segColor, fontSize: segSize))
            inTag = false
            sawBar = false
            tagName = ""
            tagBody = ""
            handled = true
          } else {
            if ch != "{" && ch != "}" {
              if sawBar {
                tagBody = tagBody + ch
              } else {
                tagName = tagName + ch
              }
              handled = true
            } else {
              plain = plain + "{" + tagName + (sawBar ? "|" + tagBody : "")
              inTag = false
              sawBar = false
              tagName = ""
              tagBody = ""
            }
          }
        }
      }
      if !handled {
        if ch == "{" {
          inTag = true
        } else {
          plain = plain + ch
        }
      }
    }
    if inTag {
      plain = plain + "{" + tagName + (sawBar ? "|" + tagBody : "")
    }
    if plain != "" {
      segments.append(LabelSegment(text: plain, color: color, fontSize: size))
    }
    return segments
  }

public func labelLines(_ text: String, _ rich: [RichStyle], _ color: String, _ size: Double) -> [[LabelSegment]] {
    var lines: [[LabelSegment]] = []
    for line in text.components(separatedBy: "\n") {
      lines.append(labelLineSegments(line, rich, color, size))
    }
    return lines
  }

public func lineWidth(_ line: [LabelSegment], _ measure: (String, Double) -> Double) -> Double {
    var w = 0.0
    for seg in line {
      w = w + measure(seg.text, seg.fontSize)
    }
    return w
  }

public func lineHeight(_ line: [LabelSegment], _ size: Double) -> Double {
    var h = size
    for seg in line {
      if seg.fontSize > h {
        h = seg.fontSize
      }
    }
    return h
  }

public func labelCommands(_ text: String, _ rich: [RichStyle], _ at: PyreonChartPt, _ align: String, _ baseline: String, _ color: String, _ size: Double, _ measure: (String, Double) -> Double) -> [PyreonDrawCmd] {
    var out: [PyreonDrawCmd] = []
    let lines = labelLines(text, rich, color, size)
    let plain = lines.count == 1 && lines[0].count <= 1
    if plain {
      let only = lines[0].count == 1 ? lines[0][0] : LabelSegment(text: "", color: color, fontSize: size)
      out.append(PyreonDrawCmd(kind: "text", fill: only.color, text: only.text, at: at, size: only.fontSize, align: anchorX(align), baseline: anchorY(baseline)))
      return out
    }
    var total = 0.0
    for line in lines {
      total = total + lineHeight(line, size) * 1.25
    }
    var y = at.y
    if baseline == "middle" {
      y = at.y - total / 2.0
    } else {
      if baseline == "bottom" {
        y = at.y - total
      }
    }
    for line in lines {
      let h = lineHeight(line, size)
      let w = lineWidth(line, measure)
      var x = at.x
      if align == "middle" {
        x = at.x - Double(w) / 2.0
      } else {
        if align == "end" {
          x = at.x - w
        }
      }
      for seg in line {
        out.append(PyreonDrawCmd(kind: "text", fill: seg.color, text: seg.text, at: PyreonChartPt(x: x, y: y), size: seg.fontSize, align: "start", baseline: "top"))
        x = x + measure(seg.text, seg.fontSize)
      }
      y = y + h * 1.25
    }
    return out
  }

public func anchorX(_ align: String) -> String { align == "middle" ? "middle" : align == "end" ? "end" : "start" }

public func anchorY(_ baseline: String) -> String { baseline == "middle" ? "middle" : baseline == "bottom" ? "bottom" : "top" }

public func linePixels(_ flat: [Double], _ plot: PyreonChartRect, _ xDomain: Domain, _ yDomain: Domain) -> [PyreonChartPt] {
    var out: [PyreonChartPt] = []
    var k = 0
    while k + 1 < flat.count {
      out.append(PyreonChartPt(x: scaleLinear(xDomain, plot.x, plot.x + plot.w, flat[k]), y: scaleLinear(yDomain, plot.y + plot.h, plot.y, flat[k + 1])))
      k = k + 2
    }
    return out
  }

public func pointAlong(_ pts: [PyreonChartPt], _ dist: Double) -> PyreonChartPt {
    if pts.count == 0 {
      return PyreonChartPt(x: 0.0, y: 0.0)
    }
    var remaining = dist
    for i in 1..<pts.count {
      let a = pts[i - 1]
      let b = pts[i]
      let seg = sqrt(Double((b.x - a.x) * (b.x - a.x) + (b.y - a.y) * (b.y - a.y)))
      if remaining <= seg && seg > 0.0 {
        let f = remaining / Double(seg)
        return PyreonChartPt(x: a.x + (b.x - a.x) * f, y: a.y + (b.y - a.y) * f)
      }
      remaining = remaining - seg
    }
    return pts[pts.count - 1]
  }

public func subPath(_ pts: [PyreonChartPt], _ from: Double, _ to: Double) -> [PyreonChartPt] {
    var out: [PyreonChartPt] = []
    if pts.count < 2 || to <= from {
      return out
    }
    out.append(pointAlong(pts, from))
    var walked = 0.0
    for i in 1..<pts.count {
      let a = pts[i - 1]
      let b = pts[i]
      walked = walked + sqrt(Double((b.x - a.x) * (b.x - a.x) + (b.y - a.y) * (b.y - a.y)))
      if walked > from && walked < to {
        out.append(b)
      }
    }
    out.append(pointAlong(pts, to))
    return out
  }

public func pathLength(_ pts: [PyreonChartPt]) -> Double {
    var total = 0.0
    for i in 1..<pts.count {
      let a = pts[i - 1]
      let b = pts[i]
      total = total + sqrt(Double((b.x - a.x) * (b.x - a.x) + (b.y - a.y) * (b.y - a.y)))
    }
    return total
  }

public func linesCommands(_ s: LinesSeries, _ plot: PyreonChartRect, _ xDomain: Domain, _ yDomain: Domain, _ time: Double) -> [PyreonDrawCmd] {
    var out: [PyreonDrawCmd] = []
    for i in 0..<s.coords.count {
      let pts = linePixels(s.coords[i], plot, xDomain, yDomain)
      if pts.count < 2 {
        continue
      }
      let color = i < s.colors.count ? s.colors[i] : "#334155"
      let width = i < s.widths.count ? s.widths[i] : 1.5
      out.append(PyreonDrawCmd(kind: "polyline", stroke: color, width: width, points: pts))
    }
    if !s.effect {
      return out
    }
    let period = s.period > 0.0 ? s.period : 4.0
    let cycles = time / period
    let phase = cycles - floor(Double(cycles))
    let trail = s.trailLength < 0.0 ? 0.0 : s.trailLength > 1.0 ? 1.0 : s.trailLength
    for i in 0..<s.coords.count {
      let pts = linePixels(s.coords[i], plot, xDomain, yDomain)
      if pts.count < 2 {
        continue
      }
      let total = pathLength(pts)
      if !(total > 0.0) {
        continue
      }
      let color = s.effectColor != "" ? s.effectColor : i < s.colors.count ? s.colors[i] : "#334155"
      let width = i < s.widths.count ? s.widths[i] : 1.5
      let head = phase * total
      let tail = head - trail * total > 0.0 ? head - trail * total : 0.0
      if trail > 0.0 && head > tail {
        out.append(PyreonDrawCmd(kind: "polyline", stroke: withAlpha(color, 0.85), width: width + 1.0, points: subPath(pts, tail, head)))
      }
      out.append(PyreonDrawCmd(kind: "circle", fill: color, center: pointAlong(pts, head), radius: s.symbolSize / 2.0))
    }
    return out
  }

public func themeCorners(_ radius: Double, _ positive: Bool, _ horizontal: Bool) -> [Double]? {
    if radius <= 0.0 {
      return nil
    }
    if horizontal {
      return positive ? [0.0, radius, radius, 0.0] : [radius, 0.0, 0.0, radius]
    }
    return positive ? [radius, radius, 0.0, 0.0] : [0.0, 0.0, radius, radius]
  }

public func labelTextAt(_ s: Series, _ index: Int, _ fallback: String) -> String {
    let texts = (s.labelTexts ?? [])
    if index < 0 || index >= texts.count {
      return fallback
    }
    let own = (texts[index] ?? "")
    return own == "" ? fallback : own
  }

public func seriesLabelCmds(_ s: Series, _ index: Int, _ fallback: String, _ at: PyreonChartPt, _ align: String, _ baseline: String, _ t: ChartTheme, _ measure: (String, Double) -> Double) -> [PyreonDrawCmd] {
    let color = (s.labelColor ?? "")
    let size = (s.labelSize ?? 0.0)
    return labelCommands(labelTextAt(s, index, fallback), (s.labelRich ?? []), at, align, baseline, color == "" ? t.label : color, size > 0.0 ? size : t.fontSize, measure)
  }

public func emphasisLevel(_ spec: ChartSpec, _ index: Int) -> Int {
    let e = (spec.emphasis ?? Emphasis(highlight: -1, selected: []))
    for sel in e.selected {
      if sel == index {
        return 2
      }
    }
    return e.highlight == index ? 1 : 0
  }

public func brushLikeAnchors(_ spec: ChartSpec, _ s: Series, _ sIdx: Int, _ plot: PyreonChartRect, _ yDomain: Domain, _ l: PlotLayout, _ place: ([Double]) -> [PyreonChartPt]) -> [PyreonChartPt] {
    var out: [PyreonChartPt] = []
    if s.kind == "bars" || s.kind == "waterfall" {
      for r in barsForIn(spec, sIdx, plot) {
        out.append(PyreonChartPt(x: r.x + Double(r.w) / 2.0, y: r.w < 0.0 ? -1000000.0 : r.y))
      }
      return out
    }
    if s.kind == "stacked" || s.kind == "grouped" {
      var kf = 0.0
      for i in 0..<sIdx {
        kf = kf + 1.0
      }
      for i in 0..<s.values.count {
        let at = markerAnchor(spec, kf, i, plot, yDomain)
        out.append(at.count > 0 ? at[0] : PyreonChartPt(x: -1000000.0, y: -1000000.0))
      }
      return out
    }
    return place(s.values)
  }

public func applySeriesSelection(_ spec: ChartSpec, _ selected: [Int]) -> ChartSpec {
    var series: [Series] = []
    var k = 0
    for s in spec.series {
      var on = false
      for i in selected {
        if i == k {
          on = true
        }
      }
      series.append(on ? { var c = s; c.seriesSelected = true; return c }() : s)
      k = k + 1
    }
    return { var c = spec; c.series = series; return c }()
  }

public func seriesEmphasisLevel(_ spec: ChartSpec, _ s: Series, _ index: Int) -> Int {
    if s.seriesSelected == true {
      return 2
    }
    let level = emphasisLevel(spec, index)
    return level == 1 && s.emphasisDisabled == true ? 0 : level
  }

public func stateWidth(_ spec: ChartSpec, _ s: Series) -> Double {
    let e = (spec.emphasis ?? Emphasis(highlight: -1, selected: []))
    if e.highlight >= 0 && s.emphasisDisabled != true {
      return (s.emphasisWidth ?? s.width)
    }
    if blurActive(spec) {
      return (s.blurWidth ?? s.width)
    }
    return s.width
  }

public func stateAreaOpacity(_ spec: ChartSpec, _ s: Series) -> Double {
    let e = (spec.emphasis ?? Emphasis(highlight: -1, selected: []))
    if e.highlight >= 0 && s.emphasisDisabled != true {
      return (s.emphasisAreaOpacity ?? -1.0)
    }
    if blurActive(spec) {
      return (s.blurAreaOpacity ?? -1.0)
    }
    return -1.0
  }

public func stateLabelShown(_ spec: ChartSpec, _ s: Series, _ index: Int) -> Bool {
    let level = seriesEmphasisLevel(spec, s, index)
    if level == 2 {
      return s.selectLabel == true
    }
    return level == 1 && s.emphasisLabel == true
  }

public func blurActive(_ spec: ChartSpec) -> Bool {
    let e = (spec.emphasis ?? Emphasis(highlight: -1, selected: []))
    if e.highlight < 0 {
      return false
    }
    for s in spec.series {
      if s.focus == "self" || s.focus == "series" {
        return true
      }
    }
    return false
  }

public func stateFill(_ spec: ChartSpec, _ s: Series, _ index: Int, _ seriesFill: String) -> String {
    let own = (s.itemColors ?? [])
    let fill = index >= 0 && index < own.count && own[index] != "" ? own[index] : seriesFill
    let level = seriesEmphasisLevel(spec, s, index)
    let selectColor = (s.selectColor ?? "")
    let emphasisColor = (s.emphasisColor ?? "")
    if level == 2 && selectColor != "" {
      return selectColor
    }
    if level == 1 && emphasisColor != "" {
      return emphasisColor
    }
    if level == 0 && blurActive(spec) {
      return withAlpha(fill, (s.blurOpacity ?? 0.1))
    }
    let brushed = (s.inBrush ?? [])
    let brushAlpha = (s.brushOpacity ?? -1.0)
    if brushAlpha >= 0.0 {
      var inside = false
      for b in brushed {
        if b == index {
          inside = true
        }
      }
      if !inside {
        return withAlpha(fill, brushAlpha)
      }
    }
    return fill
  }

public func emphasisOutline(_ r: PyreonChartRect, _ level: Int, _ stroke: String) -> PyreonDrawCmd { PyreonDrawCmd(kind: "polyline", stroke: stroke, width: level == 2 ? 2.5 : 1.5, points: [PyreonChartPt(x: r.x, y: r.y), PyreonChartPt(x: r.x + r.w, y: r.y), PyreonChartPt(x: r.x + r.w, y: r.y + r.h), PyreonChartPt(x: r.x, y: r.y + r.h), PyreonChartPt(x: r.x, y: r.y)]) }

public func resolveYDomain(_ spec: ChartSpec) -> Domain {
    let d = (spec.yDomain ?? pinDomain(spec, leftAxisSeries(spec)))
    return spec.yInverse == true ? Domain(min: d.min, max: d.max, inverse: true) : d
  }

public func resolveY2Domain(_ spec: ChartSpec) -> Domain { (spec.y2Domain ?? deriveOver(rightAxisSeries(spec), spec.yZero == true, (spec.ySplit ?? 0.0))) }

public func logBounds(_ spec: ChartSpec) -> Domain {
    let pinned = (spec.yDomain ?? Domain(min: 0.0, max: 0.0))
    if spec.yDomain != nil && pinned.min > 0.0 && pinned.max > pinned.min {
      return pinned
    }
    var lo = 0.0
    var hi = 0.0
    for s in leftAxisSeries(spec) {
      for v in s.values {
        if !(v > 0.0) {
          continue
        }
        if lo == 0.0 || v < lo {
          lo = v
        }
        if v > hi {
          hi = v
        }
      }
    }
    if lo == 0.0 {
      return Domain(min: 1.0, max: 10.0)
    }
    let floor = pow(Double(10.0), Double(floor(Double(log10(Double(lo))))))
    var ceil = pow(Double(10.0), Double(ceil(Double(log10(Double(hi))))))
    if ceil <= floor {
      ceil = floor * 10.0
    }
    return Domain(min: floor, max: ceil)
  }

public func geometrySpec(_ raw: ChartSpec) -> ChartSpec {
    let spec = invertCategories(raw)
    let isLog = spec.yScale == "log"
    let norm = spec.stackNormalize == true
    if !isLog && !norm {
      return spec
    }
    let lb = isLog ? logBounds(spec) : Domain(min: 1.0, max: 10.0)
    let viewMax = isLog ? log10(Double(Double(lb.max) / Double(lb.min))) : 1.0
    let stacked = norm ? normalizeStack(spec.series.filter({ s in s.kind == "stacked" }).map({ s in s.values })) : []
    var si = 0
    var series: [Series] = []
    for s in spec.series {
      if norm && s.kind == "stacked" {
        series.append({ var c = s; c.values = si < stacked.count ? stacked[si] : s.values; return c }())
        si = si + 1
      } else {
        if isLog && !seriesOnRightAxis(s, spec) && !onExtraAxis(s, spec) {
          var values: [Double] = []
          for v in s.values {
            values.append(v > 0.0 ? log10(Double(Double(v) / Double(lb.min))) : (0.0 / 0.0))
          }
          var lows: [Double] = []
          var highs: [Double] = []
          for v in (s.errLow ?? []) {
            lows.append(v > 0.0 ? log10(Double(Double(v) / Double(lb.min))) : (0.0 / 0.0))
          }
          for v in (s.errHigh ?? []) {
            highs.append(v > 0.0 ? log10(Double(Double(v) / Double(lb.min))) : (0.0 / 0.0))
          }
          series.append({ var c = s; c.values = values; c.errLow = s.errLow == nil ? nil : lows; c.errHigh = s.errHigh == nil ? nil : highs; return c }())
        } else {
          series.append(s)
        }
      }
    }
    var notes: [Annotation] = []
    for a in (spec.annotations ?? []) {
      if !isLog {
        notes.append(a)
        continue
      }
      let ay = (a.y ?? 0.0)
      let yF = (a.yFrom ?? 0.0)
      let yT = (a.yTo ?? 0.0)
      notes.append({ var c = a; c.y = a.y != nil && ay > 0.0 ? log10(Double(Double(ay) / Double(lb.min))) : nil; c.yFrom = a.yFrom != nil && yF > 0.0 ? log10(Double(Double(yF) / Double(lb.min))) : nil; c.yTo = a.yTo != nil && yT > 0.0 ? log10(Double(Double(yT) / Double(lb.min))) : nil; return c }())
    }
    let yDomain = isLog ? Domain(min: 0.0, max: viewMax) : Domain(min: 0.0, max: 1.0)
    return { var c = spec; c.series = series; c.yDomain = yDomain; c.annotations = spec.annotations == nil ? nil : notes; c.yScale = "linear"; c.stackNormalize = false; return c }()
  }

public func invertedDomain(_ d: Domain, _ inverse: Bool) -> Domain { inverse ? Domain(min: d.min, max: d.max, inverse: true) : d }

public func categoriesInverted(_ spec: ChartSpec) -> Bool { spec.xInverse == true && spec.horizontal != true && ((spec.xValues ?? [])).count == 0 }

public func categorySlots(_ spec: ChartSpec) -> Int {
    let m = seriesMaxLength(spec.series)
    return spec.categories.count > m ? spec.categories.count : m
  }

public func categoryIndex(_ spec: ChartSpec, _ index: Int) -> Int {
    if !categoriesInverted(spec) || index < 0 {
      return index
    }
    return categorySlots(spec) - 1 - index
  }

public func reversedDoubles(_ a: [Double]?, _ n: Int) -> [Double]? {
    let src = (a ?? [])
    var out: [Double] = []
    for i in 0..<n {
      let j = n - 1 - i
      out.append(j < src.count ? src[j] : 0.0 / 0.0)
    }
    return a == nil ? nil : out
  }

public func reversedStrings(_ a: [String]?, _ n: Int) -> [String]? {
    let src = (a ?? [])
    var out: [String] = []
    for i in 0..<n {
      let j = n - 1 - i
      out.append(j < src.count ? src[j] : "")
    }
    return a == nil ? nil : out
  }

public func invertCategories(_ spec: ChartSpec) -> ChartSpec {
    if !categoriesInverted(spec) {
      return spec
    }
    let n = categorySlots(spec)
    let last = Double(n) - 1.0
    var series: [Series] = []
    for s in spec.series {
      var extras: [SeriesExtra] = []
      for e in (s.extras ?? []) {
        extras.append(SeriesExtra(label: e.label, numbers: reversedDoubles(e.numbers, n), texts: reversedStrings(e.texts, n)))
      }
      series.append({ var c = s; c.values = (reversedDoubles(s.values, n) ?? []); c.rValues = reversedDoubles(s.rValues, n); c.radii = reversedDoubles(s.radii, n); c.labelTexts = reversedStrings(s.labelTexts, n); c.itemColors = reversedStrings(s.itemColors, n); c.errLow = reversedDoubles(s.errLow, n); c.errHigh = reversedDoubles(s.errHigh, n); c.values2 = reversedDoubles(s.values2, n); c.extras = s.extras == nil ? nil : extras; return c }())
    }
    var notes: [Annotation] = []
    for a in (spec.annotations ?? []) {
      let ax = (a.x ?? 0.0)
      let xf = (a.xFrom ?? 0.0)
      let xt = (a.xTo ?? 0.0)
      let x1 = (a.x1 ?? 0.0)
      let x2 = (a.x2 ?? 0.0)
      notes.append({ var c = a; c.x = a.x == nil ? nil : last - ax; c.xFrom = a.xTo == nil ? nil : last - xt; c.xTo = a.xFrom == nil ? nil : last - xf; c.x1 = a.x1 == nil ? nil : last - x1; c.x2 = a.x2 == nil ? nil : last - x2; return c }())
    }
    var marks: [PointMarker] = []
    for m in (spec.markers ?? []) {
      let at = (m.atIndex ?? 0.0)
      marks.append({ var c = m; c.atIndex = m.atIndex == nil ? nil : last - at; return c }())
    }
    let em = spec.emphasis
    var selected: [Int] = []
    for k in (em?.selected ?? []) {
      selected.append(n - 1 - k)
    }
    let highlight = (em?.highlight ?? -1)
    return { var c = spec; c.series = series; c.categories = (reversedStrings(spec.categories, spec.categories.count == 0 ? 0 : n) ?? []); c.annotations = spec.annotations == nil ? nil : notes; c.markers = spec.markers == nil ? nil : marks; c.emphasis = em == nil ? nil : Emphasis(highlight: highlight < 0 ? highlight : n - 1 - highlight, selected: selected); return c }()
  }

public func seriesOnX2(_ s: Series, _ spec: ChartSpec) -> Bool { s.onX2 == true && spec.horizontal != true && ((s.xs ?? [])).count > 0 }

public func hasX2Axis(_ spec: ChartSpec) -> Bool {
    for s in spec.series {
      if seriesOnX2(s, spec) {
        return true
      }
    }
    return false
  }

public func resolveX2Domain(_ spec: ChartSpec) -> Domain {
    if spec.x2Domain != nil {
      return (spec.x2Domain ?? Domain(min: 0.0, max: 1.0))
    }
    var all: [Double] = []
    for s in spec.series {
      if seriesOnX2(s, spec) {
        for x in (s.xs ?? []) {
          all.append(x)
        }
      }
    }
    return all.count > 0 ? extent(all) : Domain(min: 0.0, max: 1.0)
  }

public func onExtraAxis(_ s: Series, _ spec: ChartSpec) -> Bool {
    let k = (s.axisExtra ?? -1.0)
    return spec.horizontal != true && k >= 0.0 && k < Double(((spec.extraYAxes ?? [])).count)
  }

public func extraAxisDomain(_ spec: ChartSpec, _ k: Double) -> Domain {
    var i = 0.0
    for a in (spec.extraYAxes ?? []) {
      if i == k {
        return (a.domain ?? deriveOver(spec.series.filter({ q in ((q.axisExtra ?? -1.0)) == k }), spec.yZero == true, (spec.ySplit ?? 0.0)))
      }
      i = i + 1.0
    }
    return Domain(min: 0.0, max: 1.0)
  }

public func resolvedExtraAxes(_ spec: ChartSpec) -> [ExtraYAxis] {
    var out: [ExtraYAxis] = []
    var i = 0.0
    for a in (spec.extraYAxes ?? []) {
      out.append(ExtraYAxis(side: a.side, domain: extraAxisDomain(spec, i), title: a.title, offset: a.offset))
      i = i + 1.0
    }
    return out
  }

public func seriesDomain(_ s: Series, _ spec: ChartSpec, _ yDomain: Domain, _ y2Domain: Domain) -> Domain {
    if onExtraAxis(s, spec) {
      return extraAxisDomain(spec, (s.axisExtra ?? 0.0))
    }
    return seriesOnRightAxis(s, spec) ? y2Domain : yDomain
  }

public func seriesOnRightAxis(_ s: Series, _ spec: ChartSpec) -> Bool {
    if spec.horizontal == true {
      return false
    }
    if s.axisExtra != nil {
      return false
    }
    if s.kind == "stacked" || s.kind == "grouped" || s.kind == "stackedArea" {
      return false
    }
    if s.axis != "right" {
      return false
    }
    var hasLeft = false
    for q in spec.series {
      let qRight = q.axis == "right" && q.kind != "stacked" && q.kind != "grouped" && q.kind != "stackedArea"
      if !qRight && q.axisExtra == nil {
        hasLeft = true
      }
    }
    return hasLeft
  }

public func hasRightAxis(_ spec: ChartSpec) -> Bool {
    for s in spec.series {
      if seriesOnRightAxis(s, spec) {
        return true
      }
    }
    return false
  }

public func leftAxisSeries(_ spec: ChartSpec) -> [Series] { spec.series.filter({ s in !seriesOnRightAxis(s, spec) && (s.axisExtra == nil || spec.horizontal == true) }) }

public func rightAxisSeries(_ spec: ChartSpec) -> [Series] { spec.series.filter({ s in seriesOnRightAxis(s, spec) }) }

public func pinDomain(_ spec: ChartSpec, _ series: [Series]) -> Domain {
    let fixMin = spec.yMin != nil || spec.yMinData == true
    let fixMax = spec.yMax != nil || spec.yMaxData == true
    let zero = spec.yZero == true && spec.yMinData != true && spec.yMaxData != true
    let raw = rawExtentOver(series, zero)
    let data = rawExtentOver(series, false)
    let lo = spec.yMinData == true ? data.min : (spec.yMin ?? raw.min)
    let hi = spec.yMaxData == true ? data.max : (spec.yMax ?? raw.max)
    let split = (spec.ySplit ?? 0.0)
    if split > 0.0 {
      return echartsNiceDomain(Domain(min: lo, max: hi), split, fixMin, fixMax)
    }
    if fixMin || fixMax {
      return niceDomain(Domain(min: lo, max: hi), 5.0)
    }
    return niceDomain(raw, 5.0)
  }

public func deriveOver(_ series: [Series], _ zero: Bool, _ split: Double) -> Domain {
    let raw = rawExtentOver(series, zero)
    return split > 0.0 ? echartsNiceDomain(raw, split, false, false) : niceDomain(raw, 5.0)
  }

public func rawExtentOver(_ series: [Series], _ zero: Bool) -> Domain {
    let stacked = series.filter({ s in s.kind == "stacked" || s.kind == "stackedArea" })
    if stacked.count > 0 {
      let e = stackedExtent(stacked.map({ s in s.values }))
      var others: [Double] = []
      for s in series {
        if s.kind != "stacked" && s.kind != "stackedArea" {
          for v in s.values {
            if isFiniteValue(v) {
              others.append(v)
            }
          }
        }
      }
      let max = others.count > 0 ? Double(max(e.max, extent(others).max)) : e.max
      return Domain(min: 0.0, max: max)
    }
    var all: [Double] = []
    var hasBars = false
    for s in series {
      if s.kind == "bars" || s.kind == "area" || s.kind == "grouped" || s.kind == "waterfall" || s.kind == "stackedArea" {
        hasBars = true
      }
      if s.kind == "waterfall" {
        let we = waterfallExtent(s.values)
        all.append(we.min)
        all.append(we.max)
        continue
      }
      for v in s.values {
        if isFiniteValue(v) {
          all.append(v)
        }
      }
      for v in (s.values2 ?? []) {
        if isFiniteValue(v) {
          all.append(v)
        }
      }
      for v in (s.errLow ?? []) {
        if isFiniteValue(v) {
          all.append(v)
        }
      }
      for v in (s.errHigh ?? []) {
        if isFiniteValue(v) {
          all.append(v)
        }
      }
    }
    let e = extent(all)
    return hasBars || (zero && all.count > 0) ? Domain(min: e.min > 0.0 ? 0.0 : e.min, max: e.max < 0.0 ? 0.0 : e.max) : e
  }

public func isFiniteValue(_ v: Double) -> Bool { isFiniteNumber(v) }

public func seriesMaxLength(_ series: [Series]) -> Int {
    var n = 0
    for s in series {
      if s.values.count > n {
        n = s.values.count
      }
    }
    return n
  }

public func layoutChart(_ raw: ChartSpec, _ measure: (String, Double) -> Double) -> PlotLayout {
    let spec = geometrySpec(raw)
    let n = seriesMaxLength(spec.series)
    let isLog = raw.yScale == "log"
    let lb = isLog ? logBounds(raw) : Domain(min: 1.0, max: 10.0)
    let cfg = LayoutConfig(width: spec.width, height: spec.height, xDomain: ((spec.xValues ?? [])).count > 0 ? invertedDomain(extent((spec.xValues ?? [])), spec.xInverse == true && spec.horizontal != true) : Domain(min: 0.0, max: n > 1 ? Double(n - 1) : 1.0), yDomain: resolveYDomain(spec), categories: spec.categories, edgeCategories: edgeCategoryPoints(spec), insetLeft: spec.gridLeft, insetTop: spec.gridTop, insetRight: spec.gridRight, insetBottom: spec.gridBottom, fontSize: spec.theme.fontSize, xTickCount: 5.0, yTickCount: 5.0, showXAxis: spec.showXAxis, showYAxis: spec.showYAxis, yFormat: (spec.yFormat ?? (raw.stackNormalize == true ? percent(0) : nil)), xFormat: spec.xFormat, xTime: spec.xTime == true, y2Domain: hasRightAxis(spec) ? resolveY2Domain(spec) : nil, y2Format: spec.y2Format, horizontal: spec.horizontal == true, xTitle: spec.xTitle, yTitle: spec.yTitle, y2Title: spec.y2Title, yLog: isLog, yLogMin: lb.min, yLogMax: lb.max, yTime: spec.yTime == true, xLabels: spec.xLabels, xTop: spec.xTop, yRight: spec.yRight, extraYAxes: resolvedExtraAxes(spec), x2Labels: spec.x2Labels, x2Title: spec.x2Title, x2Domain: hasX2Axis(spec) ? resolveX2Domain(spec) : nil, xOffset: spec.xOffset, yOffset: spec.yOffset, y2Offset: spec.y2Offset)
    return computeLayout(cfg, measure)
  }

public func validDrawOrder(_ order: [Int], _ n: Int) -> [Int] {
    if order.count != n {
      return []
    }
    var seen: [Bool] = []
    for i in 0..<n {
      seen.append(false)
    }
    for i in 0..<order.count {
      let k = order[i]
      if k < 0 || k >= n || seen[k] {
        return []
      }
      seen[k] = true
    }
    return order
  }

public func edgeCategoryPoints(_ spec: ChartSpec) -> Bool {
    if spec.boundaryGap != false {
      return false
    }
    for s in spec.series {
      if s.kind == "bars" || s.kind == "stacked" || s.kind == "grouped" || s.kind == "waterfall" {
        return false
      }
    }
    return true
  }

public func categoryXPixel(_ spec: ChartSpec, _ xDomain: Domain, _ plot: PyreonChartRect, _ v: Double) -> Double {
    let n = seriesMaxLength(spec.series)
    if ((spec.xValues ?? [])).count > 0 || n == 0 || edgeCategoryPoints(spec) {
      return scaleLinear(xDomain, plot.x, plot.x + plot.w, v)
    }
    return plot.x + (plot.w / countToDouble(n)) * (v + 0.5)
  }

public func categorySpanPixels(_ spec: ChartSpec, _ xDomain: Domain, _ plot: PyreonChartRect, _ from: Double, _ to: Double) -> PyreonChartPt {
    let n = seriesMaxLength(spec.series)
    if ((spec.xValues ?? [])).count > 0 || n == 0 || edgeCategoryPoints(spec) {
      return PyreonChartPt(x: scaleLinear(xDomain, plot.x, plot.x + plot.w, from), y: scaleLinear(xDomain, plot.x, plot.x + plot.w, to))
    }
    let lo = from < to ? from : to
    let hi = from < to ? to : from
    let band = plot.w / countToDouble(n)
    return PyreonChartPt(x: plot.x + band * lo, y: plot.x + band * (hi + 1.0))
  }

public func categoryPoints(_ spec: ChartSpec, _ values: [Double], _ plot: PyreonChartRect, _ dom: Domain) -> [PyreonChartPt] { edgeCategoryPoints(spec) ? layoutSeriesPointsEdge(values, plot, dom) : layoutSeriesPoints(values, plot, dom) }

public func barPx(_ raw: BarLength?, _ ref: Double, _ fallback: Double) -> Double {
    let has = raw != nil
    let l = (raw ?? NO_LENGTH)
    if !has {
      return fallback
    }
    return l.percent ? (l.value / 100.0) * ref : l.value
  }

public func barColumns(_ spec: ChartSpec, _ band: Double) -> [PyreonChartPt] {
    var out: [PyreonChartPt] = []
    if spec.barLayout != true {
      return out
    }
    var ids: [String] = []
    var widths: [Double] = []
    var maxes: [Double] = []
    var mins: [Double] = []
    for k in 0..<spec.series.count {
      let s = spec.series[k]
      if s.kind != "bars" && s.kind != "stacked" && s.kind != "grouped" {
        continue
      }
      let id = (s.barStack ?? (s.kind == "stacked" ? "__stack" : "series" + String(k)))
      var at = -1
      for q in 0..<ids.count {
        if ids[q] == id {
          at = q
        }
      }
      if at < 0 {
        ids.append(id)
        widths.append(0.0)
        maxes.append(0.0)
        mins.append(0.0)
        at = ids.count - 1
      }
      if s.barWidth != nil && widths[at] == 0.0 {
        widths[at] = barPx(s.barWidth, band, 0.0)
      }
      if s.barMaxWidth != nil {
        maxes[at] = barPx(s.barMaxWidth, band, 0.0)
      }
      mins[at] = barPx(s.barMinWidth, band, 1.0)
    }
    let cols = countToDouble(ids.count)
    let gapLength = (spec.barGap ?? NO_LENGTH)
    let gapPct = spec.barGap == nil ? 0.1 : gapLength.value / 100.0
    let catGap = spec.barCategoryGap == nil ? (max(35.0 - cols * 4.0, 15.0) / 100.0) * band : barPx(spec.barCategoryGap, band, 0.0)
    var remained = band
    var autoCount = cols
    for q in 0..<ids.count {
      if widths[q] > 0.0 {
        remained = remained - Double(min(remained, widths[q]))
      }
    }
    let auto = max(0.0, (remained - catGap) / (autoCount + (autoCount - 1.0) * gapPct))
    var finals: [Double] = []
    for q in 0..<ids.count {
      var w = widths[q]
      if w == 0.0 {
        var f = auto
        if maxes[q] > 0.0 && maxes[q] < f {
          f = min(maxes[q], remained)
        }
        if mins[q] > f {
          f = mins[q]
        }
        if f != auto {
          w = f
          remained = remained - (f + gapPct * f)
          autoCount = autoCount - 1.0
        }
      } else {
        if maxes[q] > 0.0 {
          w = min(w, maxes[q])
        }
        if mins[q] > 0.0 {
          w = max(w, mins[q])
        }
        remained = remained - (w + gapPct * w)
        autoCount = autoCount - 1.0
      }
      finals.append(w)
    }
    let auto2 = max(0.0, (remained - catGap) / (autoCount + (autoCount - 1.0) * gapPct))
    var sum = 0.0
    for q in 0..<finals.count {
      if finals[q] == 0.0 {
        finals[q] = auto2
      }
      sum = sum + finals[q] * (1.0 + gapPct)
    }
    let total = finals.count > 0 ? sum - finals[finals.count - 1] * gapPct : sum
    var offsets: [Double] = []
    var off = -total / 2.0
    for q in 0..<finals.count {
      offsets.append(off)
      off = off + finals[q] * (1.0 + gapPct)
    }
    for k in 0..<spec.series.count {
      let s = spec.series[k]
      if s.kind != "bars" && s.kind != "stacked" && s.kind != "grouped" {
        out.append(PyreonChartPt(x: 0.0, y: -1.0))
        continue
      }
      let id = (s.barStack ?? (s.kind == "stacked" ? "__stack" : "series" + String(k)))
      var at = 0
      for q in 0..<ids.count {
        if ids[q] == id {
          at = q
        }
      }
      out.append(PyreonChartPt(x: offsets[at], y: finals[at]))
    }
    return out
  }

public func inColumn(_ spec: ChartSpec, _ cols: [PyreonChartPt], _ k: Int, _ r: PyreonChartRect, _ i: Int, _ n: Int, _ plot: PyreonChartRect) -> PyreonChartRect {
    let c = cols[k]
    if c == nil || c.y < 0.0 || n == 0 {
      return r
    }
    let band = plot.w / countToDouble(n)
    return PyreonChartRect(x: plot.x + band * countToDouble(i) + band / 2.0 + c.x, y: r.y, w: c.y, h: r.h)
  }

public func bandOf(_ plot: PyreonChartRect, _ n: Int) -> Double { n == 0 ? 0.0 : plot.w / countToDouble(n) }

public func barsLaid(_ spec: ChartSpec, _ k: Int, _ plot: PyreonChartRect, _ dom: Domain) -> [PyreonChartRect] {
    let s = spec.series[k]
    let rects = layoutBars(s.values, plot, dom, 0.25)
    let cols = barColumns(spec, bandOf(plot, rects.count))
    var out: [PyreonChartRect] = []
    for i in 0..<rects.count {
      out.append(inColumn(spec, cols, k, rects[i], i, rects.count, plot))
    }
    return out
  }

public func indicesOf(_ spec: ChartSpec, _ kind: String) -> [Int] {
    var out: [Int] = []
    for k in 0..<spec.series.count {
      if spec.series[k].kind == kind {
        out.append(k)
      }
    }
    return out
  }

public func setLaid(_ spec: ChartSpec, _ kind: String, _ plot: PyreonChartRect, _ dom: Domain) -> [StackSegment] {
    let idx = indicesOf(spec, kind)
    let values = idx.map({ k in spec.series[k].values })
    var n = 0
    for v in values {
      if v.count > n {
        n = v.count
      }
    }
    let cols = barColumns(spec, bandOf(plot, n))
    let segs = kind == "stacked" ? layoutStackedBars(values, plot, dom, 0.25) : layoutGroupedBars(values, plot, dom, 0.25)
    var out: [StackSegment] = []
    for seg in segs {
      out.append(StackSegment(rect: inColumn(spec, cols, idx[seg.seriesIndex], seg.rect, seg.datumIndex, n, plot), seriesIndex: seg.seriesIndex, datumIndex: seg.datumIndex, value: seg.value))
    }
    return out
  }

public func renderChart(_ spec: ChartSpec, _ measure: (String, Double) -> Double) -> [PyreonDrawCmd] { renderChartIn(spec, measure, layoutChart(spec, measure)) }

public func renderChartIn(_ raw: ChartSpec, _ measure: (String, Double) -> Double, _ l: PlotLayout) -> [PyreonDrawCmd] {
    let spec = geometrySpec(raw)
    let printedView = invertCategories(raw)
    let printed = { (k: Int, i: Int) in
      let sv = printedView.series[k].values
      return i < sv.count ? sv[i] : 0.0 / 0.0
    }
    let yDomain = resolveYDomain(spec)
    let useY2 = hasRightAxis(spec)
    let y2Domain = useY2 ? resolveY2Domain(spec) : yDomain
    let plot = l.plot
    let t = spec.theme
    var out: [PyreonDrawCmd] = []
    let rawProgress = (spec.progress ?? 1.0)
    let progress = rawProgress < 0.0 ? 0.0 : rawProgress > 1.0 ? 1.0 : rawProgress
    let growRect = { (r: PyreonChartRect, dom: Domain) in
      if progress >= 1.0 {
        return r
      }
      let zeroY = scaleLinear(dom, plot.y + plot.h, plot.y, dom.min < 0.0 && dom.max > 0.0 ? 0.0 : dom.min)
      let h = r.h * progress
      let top = r.y + r.h <= zeroY + 0.5 ? zeroY - h : zeroY
      return PyreonChartRect(x: r.x, y: top, w: r.w, h: h)
    }
    let growRectH = { (r: PyreonChartRect) in
      if progress >= 1.0 {
        return r
      }
      let zeroX = scaleLinear(yDomain, plot.x, plot.x + plot.w, yDomain.min < 0.0 && yDomain.max > 0.0 ? 0.0 : yDomain.min)
      let w = r.w * progress
      let left = r.x >= zeroX - 0.5 ? zeroX : zeroX - w
      return PyreonChartRect(x: left, y: r.y, w: w, h: r.h)
    }
    let reveal = { (pts: [PyreonChartPt]) in
      if progress >= 1.0 || pts.count < 2 {
        return pts
      }
      let span = pts.count - 1
      let cut = Double(span) * progress
      let whole = floor(Double(cut))
      var outPts: [PyreonChartPt] = []
      for i in 0...Int(ceil(Double(whole))) {
        outPts.append(pts[i])
      }
      let frac = cut - whole
      if frac > 0.0 && whole + Double(1) < Double(pts.count) {
        let a = pts[Int(whole)]
        let b = pts[Int(whole + Double(1))]
        outPts.append(PyreonChartPt(x: a.x + (b.x - a.x) * frac, y: a.y + (b.y - a.y) * frac))
      }
      return outPts
    }
    if spec.showGrid {
      if spec.horizontal == true {
        for tick in l.xTicks {
          out.append(PyreonDrawCmd(kind: "line", from: PyreonChartPt(x: tick.pos, y: plot.y), to: PyreonChartPt(x: tick.pos, y: plot.y + plot.h), stroke: t.grid, width: 1.0))
        }
      } else {
        for tick in l.yTicks {
          out.append(PyreonDrawCmd(kind: "line", from: PyreonChartPt(x: plot.x, y: tick.pos), to: PyreonChartPt(x: plot.x + plot.w, y: tick.pos), stroke: t.grid, width: 1.0))
        }
      }
    }
    let yRight = spec.yRight == true && !useY2 && spec.horizontal != true
    let yOff = (spec.yOffset ?? 0.0)
    let y2Off = (spec.y2Offset ?? 0.0)
    let xOff = (spec.xOffset ?? 0.0)
    let yAxisX = yRight ? plot.x + plot.w + yOff : plot.x - yOff
    if spec.showYAxis {
      out.append(PyreonDrawCmd(kind: "line", from: PyreonChartPt(x: yAxisX, y: plot.y), to: PyreonChartPt(x: yAxisX, y: plot.y + plot.h), stroke: t.axis, width: 1.0))
    }
    let xTop = spec.xTop == true && spec.horizontal != true
    let xAxisY = xTop ? plot.y - xOff : plot.y + plot.h + xOff
    if spec.showXAxis {
      out.append(PyreonDrawCmd(kind: "line", from: PyreonChartPt(x: plot.x, y: xAxisY), to: PyreonChartPt(x: plot.x + plot.w, y: xAxisY), stroke: t.axis, width: 1.0))
    }
    if spec.showYAxis && spec.horizontal != true {
      for a in (spec.extraYAxes ?? []) {
        let ax = a.side == "left" ? plot.x - ((a.offset ?? 0.0)) : plot.x + plot.w + ((a.offset ?? 0.0))
        out.append(PyreonDrawCmd(kind: "line", from: PyreonChartPt(x: ax, y: plot.y), to: PyreonChartPt(x: ax, y: plot.y + plot.h), stroke: t.axis, width: 1.0))
      }
    }
    if spec.showYAxis && useY2 {
      out.append(PyreonDrawCmd(kind: "line", from: PyreonChartPt(x: plot.x + plot.w + y2Off, y: plot.y), to: PyreonChartPt(x: plot.x + plot.w + y2Off, y: plot.y + plot.h), stroke: t.axis, width: 1.0))
    }
    let notes = (spec.annotations ?? [])
    for a in notes {
      let yFrom = (a.yFrom ?? 0.0)
      let yTo = (a.yTo ?? 0.0)
      if a.yFrom != nil && a.yTo != nil {
        let y1 = scaleLinear(yDomain, plot.y + plot.h, plot.y, yFrom)
        let y2 = scaleLinear(yDomain, plot.y + plot.h, plot.y, yTo)
        let top = y1 < y2 ? y1 : y2
        out.append(PyreonDrawCmd(kind: "rect", rect: PyreonChartRect(x: plot.x, y: top, w: plot.w, h: Double(abs(y2 - y1))), fill: withAlpha((a.color ?? t.axis), 0.12)))
        if a.label != nil {
          out.append(PyreonDrawCmd(kind: "text", fill: (a.color ?? t.label), text: a.label, at: PyreonChartPt(x: plot.x + plot.w - 4.0, y: top + 4.0), size: t.fontSize, align: "end", baseline: "top"))
        }
      }
      let xFrom = (a.xFrom ?? 0.0)
      let xTo = (a.xTo ?? 0.0)
      if a.xFrom != nil && a.xTo != nil {
        let span = categorySpanPixels(spec, l.xDomainUsed, plot, xFrom, xTo)
        let x1 = span.x
        let x2 = span.y
        let left = x1 < x2 ? x1 : x2
        out.append(PyreonDrawCmd(kind: "rect", rect: PyreonChartRect(x: left, y: plot.y, w: Double(abs(x2 - x1)), h: plot.h), fill: withAlpha((a.color ?? t.axis), 0.12)))
        if a.label != nil {
          out.append(PyreonDrawCmd(kind: "text", fill: (a.color ?? t.label), text: a.label, at: PyreonChartPt(x: left + 4.0, y: plot.y + 4.0), size: t.fontSize, align: "start", baseline: "top"))
        }
      }
    }
    for a in notes {
      let ay = (a.y ?? 0.0)
      if a.y != nil {
        let yPos = scaleLinear(yDomain, plot.y + plot.h, plot.y, ay)
        out.append(PyreonDrawCmd(kind: "line", from: PyreonChartPt(x: plot.x, y: yPos), to: PyreonChartPt(x: plot.x + plot.w, y: yPos), stroke: (a.color ?? t.axis), width: 1.0, dash: [4.0, 4.0]))
        let yLabel = (a.label ?? "")
        if a.label != nil {
          out.append(PyreonDrawCmd(kind: "text", fill: (a.color ?? t.label), text: yLabel, at: PyreonChartPt(x: plot.x + plot.w, y: yPos - 4.0), size: t.fontSize, align: "end", baseline: "bottom"))
        }
      }
      let ax = (a.x ?? 0.0)
      if a.x != nil {
        let xPos = categoryXPixel(spec, l.xDomainUsed, plot, ax)
        out.append(PyreonDrawCmd(kind: "line", from: PyreonChartPt(x: xPos, y: plot.y), to: PyreonChartPt(x: xPos, y: plot.y + plot.h), stroke: (a.color ?? t.axis), width: 1.0, dash: [4.0, 4.0]))
        let xLabel = (a.label ?? "")
        if a.label != nil {
          out.append(PyreonDrawCmd(kind: "text", fill: (a.color ?? t.label), text: xLabel, at: PyreonChartPt(x: xPos + 4.0, y: plot.y), size: t.fontSize, align: "start", baseline: "top"))
        }
      }
      let sx1 = (a.x1 ?? 0.0)
      let sy1 = (a.y1 ?? 0.0)
      let sx2 = (a.x2 ?? 0.0)
      let sy2 = (a.y2 ?? 0.0)
      if a.x1 != nil && a.y1 != nil && a.x2 != nil && a.y2 != nil {
        let p1 = PyreonChartPt(x: categoryXPixel(spec, l.xDomainUsed, plot, sx1), y: scaleLinear(yDomain, plot.y + plot.h, plot.y, sy1))
        let p2 = PyreonChartPt(x: categoryXPixel(spec, l.xDomainUsed, plot, sx2), y: scaleLinear(yDomain, plot.y + plot.h, plot.y, sy2))
        out.append(PyreonDrawCmd(kind: "line", from: p1, to: p2, stroke: (a.color ?? t.axis), width: 1.0, dash: [4.0, 4.0]))
        let segLabel = (a.label ?? "")
        if a.label != nil {
          out.append(PyreonDrawCmd(kind: "text", fill: (a.color ?? t.label), text: segLabel, at: PyreonChartPt(x: p2.x, y: p2.y - 4.0), size: t.fontSize, align: "middle", baseline: "bottom"))
        }
      }
    }
    let emph = (spec.emphasis ?? Emphasis(highlight: -1, selected: []))
    if emph.highlight >= 0 && spec.horizontal != true {
      let xsE = (spec.xValues ?? [])
      let hi = emph.highlight
      if xsE.count > emph.highlight {
        let cx = scaleLinear(l.xDomainUsed, plot.x, plot.x + plot.w, xsE[emph.highlight])
        out.append(PyreonDrawCmd(kind: "rect", rect: PyreonChartRect(x: cx - 6.0, y: plot.y, w: 12.0, h: plot.h), fill: withAlpha(t.axis, 0.14)))
      } else {
        if spec.categories.count > emph.highlight {
          let nb = spec.categories.count
          let bandW = plot.w / Double(nb)
          out.append(PyreonDrawCmd(kind: "rect", rect: PyreonChartRect(x: plot.x + bandW * countToDouble(hi), y: plot.y, w: bandW, h: plot.h), fill: withAlpha(t.axis, 0.14)))
        }
      }
    }
    let stackedSeries = spec.series.filter({ s in s.kind == "stacked" })
    if stackedSeries.count > 0 {
      let stackSegs = spec.horizontal == true ? layoutStackedBarsH(stackedSeries.map({ s in s.values }), plot, yDomain, 0.25) : setLaid(spec, "stacked", plot, yDomain)
      let fmtS = (spec.yFormat ?? plain)
      for seg in stackSegs {
        let rS = growRect(seg.rect, yDomain)
        let gS = seriesGradient(stackedSeries[seg.seriesIndex].gradient, plot)
        out.append(rectCmd(rS, stateFill(spec, stackedSeries[seg.seriesIndex], seg.datumIndex, stackedSeries[seg.seriesIndex].color), stackedSeries[seg.seriesIndex].corners, gS.stops.count == 0 ? nil : gS, stackedSeries[seg.seriesIndex].pattern))
        let lvlS = seriesEmphasisLevel(spec, stackedSeries[seg.seriesIndex], seg.datumIndex)
        if lvlS > 0 {
          out.append(emphasisOutline(rS, lvlS, t.label))
        }
        if stackedSeries[seg.seriesIndex].showValues == true && progress >= 1.0 {
          for c in seriesLabelCmds(stackedSeries[seg.seriesIndex], seg.datumIndex, fmtS(seg.value), PyreonChartPt(x: rS.x + Double(rS.w) / 2.0, y: rS.y + Double(rS.h) / 2.0), "middle", "middle", t, measure) {
            out.append(c)
          }
        }
      }
    }
    let groupedSeries = spec.series.filter({ s in s.kind == "grouped" })
    if groupedSeries.count > 0 {
      let groupSegs = spec.horizontal == true ? layoutGroupedBarsH(groupedSeries.map({ s in s.values }), plot, yDomain, 0.25) : setLaid(spec, "grouped", plot, yDomain)
      let fmtG = (spec.yFormat ?? plain)
      for seg in groupSegs {
        let rG = growRect(seg.rect, yDomain)
        let gG = seriesGradient(groupedSeries[seg.seriesIndex].gradient, plot)
        out.append(rectCmd(rG, stateFill(spec, groupedSeries[seg.seriesIndex], seg.datumIndex, groupedSeries[seg.seriesIndex].color), groupedSeries[seg.seriesIndex].corners, gG.stops.count == 0 ? nil : gG, groupedSeries[seg.seriesIndex].pattern))
        let lvlG = seriesEmphasisLevel(spec, groupedSeries[seg.seriesIndex], seg.datumIndex)
        if lvlG > 0 {
          out.append(emphasisOutline(rG, lvlG, t.label))
        }
        if groupedSeries[seg.seriesIndex].showValues == true && progress >= 1.0 {
          for c in seriesLabelCmds(groupedSeries[seg.seriesIndex], seg.datumIndex, fmtG(seg.value), PyreonChartPt(x: rG.x + Double(rG.w) / 2.0, y: seg.value < 0.0 ? rG.y + rG.h + 4.0 : rG.y - 4.0), "middle", seg.value < 0.0 ? "top" : "bottom", t, measure) {
            out.append(c)
          }
        }
      }
    }
    let areaStack = spec.horizontal == true ? [] : spec.series.filter({ s in s.kind == "stackedArea" })
    if areaStack.count > 0 {
      let tops = stackCumulative(areaStack.map({ s in s.values }))
      for k in 0..<areaStack.count {
        let sA = areaStack[k]
        let top = tops[k]
        let below = k == 0 ? [] : tops[k - 1]
        var upper: [PyreonChartPt] = []
        var lower: [PyreonChartPt] = []
        for i in 0..<top.count {
          let xAt = edgeCategoryPoints(spec) && top.count > 1 ? plot.x + (plot.w / countToDouble(top.count - 1)) * countToDouble(i) : plot.x + (plot.w / max(1.0, countToDouble(top.count))) * (countToDouble(i) + 0.5)
          upper.append(PyreonChartPt(x: xAt, y: scaleLinear(yDomain, plot.y + plot.h, plot.y, top[i])))
          lower.append(PyreonChartPt(x: xAt, y: scaleLinear(yDomain, plot.y + plot.h, plot.y, k == 0 ? yDomain.min : below[i])))
        }
        if upper.count > 1 {
          var poly: [PyreonChartPt] = []
          for p in upper {
            poly.append(p)
          }
          for i in stride(from: lower.count - 1, through: 0, by: -1) {
            poly.append(lower[i])
          }
          let gA = seriesGradient(sA.gradient, plot)
          out.append(polygonCmd(poly, sA.color, gA.stops.count == 0 ? nil : gA, sA.pattern))
          if sA.showValues == true && progress >= 1.0 {
            let fmtA = (spec.yFormat ?? plain)
            for i in 0..<upper.count {
              let v = i < sA.values.count ? sA.values[i] : 0.0 / 0.0
              if !isFiniteValue(v) {
                continue
              }
              for c in seriesLabelCmds(sA, i, fmtA(v), PyreonChartPt(x: upper[i].x, y: Double((upper[i].y + lower[i].y)) / 2.0), "middle", "middle", t, measure) {
                out.append(c)
              }
            }
          }
        }
      }
    }
    let drawOrder = validDrawOrder((spec.drawOrder ?? []), spec.series.count)
    for oIdx in 0..<spec.series.count {
      let sIdx = drawOrder.count == 0 ? oIdx : drawOrder[oIdx]
      let s = spec.series[sIdx]
      if s.kind == "stacked" || s.kind == "grouped" || s.kind == "stackedArea" {
        continue
      }
      let xs = (spec.xValues ?? [])
      let sDomain = seriesDomain(s, spec, yDomain, y2Domain)
      let onX2 = seriesOnX2(s, spec)
      let sXs = onX2 ? (s.xs ?? []) : xs
      let sXDomain = onX2 ? resolveX2Domain(spec) : l.xDomainUsed
      let place = { (values: [Double]) in sXs.count > 0 ? layoutSeriesPointsAt(values, sXs, plot, sDomain, sXDomain) : categoryPoints(spec, values, plot, sDomain) }
      let curveFn = (s.curve ?? ({ q in q }))
      let sGradAll = seriesGradient(s.gradient, plot)
      let sGrad = sGradAll.stops.count == 0 ? nil : sGradAll
      let shape = { (pts: [PyreonChartPt]) in curveFn(pts) }
      if spec.horizontal == true {
        if s.kind != "bars" {
          continue
        }
        let rects = layoutBarsH(s.values, plot, yDomain, 0.25)
        for ri in 0..<rects.count {
          let r = rects[ri]
          let grown = growRectH(r)
          let fillH = stateFill(spec, s, ri, s.color)
          if s.symbol == nil {
            out.append(rectCmd(grown, fillH, (s.corners ?? themeCorners(spec.theme.radius, ((s.values[ri] ?? 0.0)) >= 0.0, true)), sGrad, s.pattern))
          } else {
            for c in pictorialCommands(pictorialBar(s, grown, true, (s.values[ri] ?? 0.0), fillH)) {
              out.append(c)
            }
          }
        }
        for i in 0..<rects.count {
          let lvl = seriesEmphasisLevel(spec, s, i)
          if lvl > 0 {
            out.append(emphasisOutline(growRectH(rects[i]), lvl, t.label))
          }
        }
        if s.showValues == true && progress >= 1.0 {
          let fmt = (spec.yFormat ?? plain)
          for i in 0..<rects.count {
            let r = rects[i]
            let v = printed(sIdx, i)
            if !isFiniteValue(v) {
              continue
            }
            for c in seriesLabelCmds(s, i, fmt(v), PyreonChartPt(x: v < 0.0 ? r.x - 4.0 : r.x + r.w + 4.0, y: r.y + Double(r.h) / 2.0), v < 0.0 ? "end" : "start", "middle", t, measure) {
              out.append(c)
            }
          }
        }
        continue
      }
      if s.kind == "bars" {
        let rects = barsLaid(spec, sIdx, plot, sDomain)
        for ri in 0..<rects.count {
          let r = rects[ri]
          let grown = growRect(r, sDomain)
          let fillV = stateFill(spec, s, ri, s.color)
          if s.symbol == nil {
            out.append(rectCmd(grown, fillV, (s.corners ?? themeCorners(spec.theme.radius, ((s.values[ri] ?? 0.0)) >= 0.0, false)), sGrad, s.pattern))
          } else {
            for c in pictorialCommands(pictorialBar(s, grown, false, (s.values[ri] ?? 0.0), fillV)) {
              out.append(c)
            }
          }
        }
        for i in 0..<rects.count {
          let lvl = seriesEmphasisLevel(spec, s, i)
          if lvl > 0 {
            out.append(emphasisOutline(growRect(rects[i], sDomain), lvl, t.label))
          }
        }
        if s.showValues == true && progress >= 1.0 {
          let fmt = (spec.yFormat ?? plain)
          for i in 0..<rects.count {
            let r = rects[i]
            let v = printed(sIdx, i)
            if !isFiniteValue(v) {
              continue
            }
            for c in seriesLabelCmds(s, i, fmt(v), PyreonChartPt(x: r.x + Double(r.w) / 2.0, y: v < 0.0 ? r.y + r.h + 4.0 : r.y - 4.0), "middle", v < 0.0 ? "top" : "bottom", t, measure) {
              out.append(c)
            }
          }
        }
      } else {
        if s.kind == "waterfall" {
          let steps = layoutWaterfall(s.values, plot, sDomain, 0.25)
          for si in 0..<steps.count {
            let st = steps[si]
            let fill = stateFill(spec, s, st.datumIndex, st.value < 0.0 ? (s.negativeColor ?? withAlpha(s.color, 0.55)) : s.color)
            let startY = scaleLinear(sDomain, plot.y + plot.h, plot.y, st.start)
            let grownH = st.rect.h * progress
            let grown = progress >= 1.0 ? st.rect : PyreonChartRect(x: st.rect.x, y: st.value >= 0.0 ? startY - grownH : startY, w: st.rect.w, h: grownH)
            out.append(rectCmd(grown, fill, s.corners, sGrad, s.pattern))
            let lvlW = seriesEmphasisLevel(spec, s, st.datumIndex)
            if lvlW > 0 {
              out.append(emphasisOutline(grown, lvlW, t.label))
            }
            if si + 1 < steps.count && progress >= 1.0 {
              let next = steps[si + 1]
              let level = scaleLinear(sDomain, plot.y + plot.h, plot.y, st.end)
              out.append(PyreonDrawCmd(kind: "line", from: PyreonChartPt(x: st.rect.x + st.rect.w, y: level), to: PyreonChartPt(x: next.rect.x, y: level), stroke: t.axis, width: 1.0, dash: [2.0, 2.0]))
            }
            if s.showValues == true && progress >= 1.0 {
              let fmt = (spec.yFormat ?? plain)
              let v = printed(sIdx, st.datumIndex)
              for c in seriesLabelCmds(s, st.datumIndex, fmt(v), PyreonChartPt(x: st.rect.x + Double(st.rect.w) / 2.0, y: v < 0.0 ? st.rect.y + st.rect.h + 4.0 : st.rect.y - 4.0), "middle", v < 0.0 ? "top" : "bottom", t, measure) {
                out.append(c)
              }
            }
          }
        } else {
          if s.kind == "line" {
            for run in splitRuns(s.values, place) {
              let pts = reveal(shape(run))
              if pts.count > 1 {
                out.append(PyreonDrawCmd(kind: "polyline", stroke: s.color, width: stateWidth(spec, s), dash: s.dash, points: pts))
              }
            }
            let lineSymbol = (s.symbol ?? "circle")
            if s.symbol != nil && progress >= 1.0 {
              let dots = place(s.values)
              for i in 0..<dots.count {
                if !isFiniteValue(s.values[i]) {
                  continue
                }
                let d = dots[i]
                out.append(symbolCommand(PyreonChartRect(x: d.x - s.radius, y: d.y - s.radius, w: s.radius * 2.0, h: s.radius * 2.0), lineSymbol, s.color))
              }
            }
          } else {
            if s.kind == "band" {
              let lows = (s.values2 ?? [])
              var paired: [Double] = []
              for i in 0..<s.values.count {
                let lo = i < lows.count ? lows[i] : 0.0 / 0.0
                paired.append(isFiniteValue(s.values[i]) && isFiniteValue(lo) ? s.values[i] : 0.0 / 0.0)
              }
              for run in splitRuns(paired, place) {
                var upper = reveal(shape(run))
                if upper.count < 2 {
                  continue
                }
                var loRun: [Double] = []
                for i in 0..<paired.count {
                  loRun.append(isFiniteValue(paired[i]) ? (i < lows.count ? lows[i] : 0.0 / 0.0) : 0.0 / 0.0)
                }
                let lowerRuns = splitRuns(loRun, place)
                var lower = lowerRuns.count > 0 ? reveal(shape(lowerRuns[0])) : []
                var poly: [PyreonChartPt] = []
                for p in upper {
                  poly.append(p)
                }
                for i in stride(from: lower.count - 1, through: 0, by: -1) {
                  poly.append(lower[i])
                }
                if poly.count > 2 {
                  out.append(polygonCmd(poly, s.color, sGrad, s.pattern))
                }
              }
            } else {
              if s.kind == "area" {
                for run in splitRuns(s.values, place) {
                  let pts = reveal(shape(run))
                  if pts.count > 1 {
                    var poly: [PyreonChartPt] = []
                    for p in pts {
                      poly.append(p)
                    }
                    let baseY = scaleLinear(sDomain, plot.y + plot.h, plot.y, sDomain.min)
                    poly.append(PyreonChartPt(x: pts[pts.count - 1].x, y: baseY))
                    poly.append(PyreonChartPt(x: pts[0].x, y: baseY))
                    let areaAlpha = stateAreaOpacity(spec, s)
                    out.append(polygonCmd(poly, areaAlpha < 0.0 ? s.color : withAlpha(s.color, areaAlpha), sGrad, s.pattern))
                  }
                }
              } else {
                let pts = place(s.values)
                let radii = (s.radii ?? [])
                for i in 0..<pts.count {
                  if !isFiniteValue(s.values[i]) {
                    continue
                  }
                  let fullR = radii.count > 0 ? (radii[i] ?? s.radius) : s.radius
                  if s.effect == true {
                    out.append(PyreonDrawCmd(kind: "circle", fill: withAlpha(s.color, 0.12), center: pts[i], radius: fullR * 2.6 * progress))
                    out.append(PyreonDrawCmd(kind: "circle", fill: withAlpha(s.color, 0.25), center: pts[i], radius: fullR * 1.7 * progress))
                  }
                  let lvlP = seriesEmphasisLevel(spec, s, i)
                  if lvlP > 0 {
                    out.append(PyreonDrawCmd(kind: "circle", fill: withAlpha(t.label, 0.35), center: pts[i], radius: fullR * progress + (lvlP == 2 ? 4.0 : 3.0)))
                  }
                  let scaled = lvlP == 1 ? fullR * ((s.emphasisScale ?? 1.0)) : fullR
                  let r = scaled * progress
                  let pointSymbol = (s.symbol ?? "circle")
                  let fillP = stateFill(spec, s, i, s.color)
                  if pointSymbol == "circle" {
                    out.append(PyreonDrawCmd(kind: "circle", fill: fillP, center: pts[i], radius: r))
                  } else {
                    out.append(symbolCommand(PyreonChartRect(x: pts[i].x - r, y: pts[i].y - r, w: r * 2.0, h: r * 2.0), pointSymbol, fillP))
                  }
                }
              }
            }
          }
        }
      }
      if s.showValues == true && progress >= 1.0 && (s.kind == "line" || s.kind == "area" || s.kind == "points" || s.kind == "band") {
        let fmtP = (spec.yFormat ?? plain)
        let labelPts = place(s.values)
        for i in 0..<labelPts.count {
          let v = printed(sIdx, i)
          if !isFiniteValue(v) {
            continue
          }
          for c in seriesLabelCmds(s, i, fmtP(v), PyreonChartPt(x: labelPts[i].x, y: labelPts[i].y - (s.radius + 5.0)), "middle", "bottom", t, measure) {
            out.append(c)
          }
        }
      }
      if (s.emphasisLabel == true || s.selectLabel == true) && progress >= 1.0 {
        let fmtS = (spec.yFormat ?? plain)
        let anchors = brushLikeAnchors(spec, s, sIdx, plot, yDomain, l, place)
        for i in 0..<anchors.count {
          if !stateLabelShown(spec, s, i) {
            continue
          }
          let v = printed(sIdx, i)
          if !isFiniteValue(v) {
            continue
          }
          let at = anchors[i]
          for c in seriesLabelCmds(s, i, fmtS(v), PyreonChartPt(x: at.x, y: at.y - 6.0), "middle", "bottom", t, measure) {
            out.append(c)
          }
        }
      }
      let eLow = (s.errLow ?? [])
      let eHigh = (s.errHigh ?? [])
      if eLow.count > 0 && eHigh.count > 0 && progress >= 1.0 && s.kind != "waterfall" {
        var centres: [Double] = []
        if s.kind == "bars" {
          for r in barsLaid(spec, sIdx, plot, sDomain) {
            centres.append(r.x + Double(r.w) / 2.0)
          }
        } else {
          for p in place(s.values) {
            centres.append(p.x)
          }
        }
        let cap = 4.0
        for i in 0..<centres.count {
          let lo = i < eLow.count ? eLow[i] : 0.0 / 0.0
          let hi = i < eHigh.count ? eHigh[i] : 0.0 / 0.0
          if !isFiniteValue(lo) || !isFiniteValue(hi) {
            continue
          }
          let cx = centres[i]
          let yLo = scaleLinear(sDomain, plot.y + plot.h, plot.y, lo)
          let yHi = scaleLinear(sDomain, plot.y + plot.h, plot.y, hi)
          out.append(PyreonDrawCmd(kind: "line", from: PyreonChartPt(x: cx, y: yLo), to: PyreonChartPt(x: cx, y: yHi), stroke: t.text, width: 1.0))
          out.append(PyreonDrawCmd(kind: "line", from: PyreonChartPt(x: cx - cap, y: yLo), to: PyreonChartPt(x: cx + cap, y: yLo), stroke: t.text, width: 1.0))
          out.append(PyreonDrawCmd(kind: "line", from: PyreonChartPt(x: cx - cap, y: yHi), to: PyreonChartPt(x: cx + cap, y: yHi), stroke: t.text, width: 1.0))
        }
      }
    }
    for ls in (spec.lines ?? []) {
      for c in linesCommands(ls, plot, l.xDomainUsed, yDomain, (spec.effectTime ?? 0.0)) {
        out.append(c)
      }
    }
    let markers = (spec.markers ?? [])
    for m in markers {
      let rawSeriesIndex = (m.seriesIndex ?? 0.0)
      let s = spec.series[Int(floor(Double(rawSeriesIndex)))]
      if s == nil {
        continue
      }
      let n = s.values.count
      if n == 0 {
        continue
      }
      var idx = -1
      if m.at == "max" {
        idx = 0
        for i in 1..<n {
          if s.values[i] > s.values[idx] {
            idx = i
          }
        }
      } else {
        if m.at == "min" {
          idx = 0
          for i in 1..<n {
            if s.values[i] < s.values[idx] {
              idx = i
            }
          }
        } else {
          if m.at == "average" {
            var sum = 0.0
            for i in 0..<n {
              sum = sum + s.values[i]
            }
            let mean = Double(sum) / Double(n)
            idx = 0
            for i in 1..<n {
              if abs(s.values[i] - mean) < abs(s.values[idx] - mean) {
                idx = i
              }
            }
          } else {
            let rawAt = (m.atIndex ?? -1.0)
            if m.atIndex != nil {
              var jf = 0.0
              for j in 0..<n {
                if jf <= rawAt {
                  idx = j
                }
                jf = jf + 1.0
              }
              if idx < 0 {
                idx = 0
              }
            }
          }
        }
      }
      if idx < 0 {
        continue
      }
      let mDomain = seriesDomain(s, spec, yDomain, y2Domain)
      let xsM = (spec.xValues ?? [])
      let segMarker = markerAnchor(spec, rawSeriesIndex, idx, plot, yDomain)
      let p = segMarker.count > 0 ? segMarker[0] : spec.horizontal == true ? layoutSeriesPointsH(s.values, plot, mDomain)[idx] : xsM.count > 0 ? layoutSeriesPointsAt(s.values, seriesOnX2(s, spec) ? (s.xs ?? []) : xsM, plot, mDomain, seriesOnX2(s, spec) ? resolveX2Domain(spec) : l.xDomainUsed)[idx] : categoryPoints(spec, s.values, plot, mDomain)[idx]
      if p == nil {
        continue
      }
      let mColor = (m.color ?? s.color)
      out.append(PyreonDrawCmd(kind: "circle", fill: mColor, center: p, radius: ((m.radius ?? 4.0)) * progress))
      let mLabel = (m.label ?? "")
      if m.label != nil && progress >= 1.0 {
        out.append(PyreonDrawCmd(kind: "text", fill: mColor, text: mLabel, at: PyreonChartPt(x: p.x, y: p.y - ((m.radius ?? 4.0)) - 4.0), size: t.fontSize, align: "middle", baseline: "bottom"))
      }
    }
    for ti in 0..<l.yTicks.count {
      let tick = l.yTicks[ti]
      if l.yLabelEvery > 1 && ti % l.yLabelEvery != 0 {
        continue
      }
      out.append(PyreonDrawCmd(kind: "text", fill: t.label, text: tick.label, at: PyreonChartPt(x: yRight ? yAxisX + 6.0 : yAxisX - 6.0, y: tick.pos), size: t.fontSize, align: yRight ? "start" : "end", baseline: "middle"))
    }
    for tick in l.y2Ticks {
      out.append(PyreonDrawCmd(kind: "text", fill: t.label, text: tick.label, at: PyreonChartPt(x: plot.x + plot.w + y2Off + 6.0, y: tick.pos), size: t.fontSize, align: "start", baseline: "middle"))
    }
    let x2 = (spec.x2Labels ?? [])
    if (x2.count > 0 || l.x2Ticks.count > 0) && spec.showXAxis && spec.horizontal != true {
      let edgeY = xTop ? plot.y + plot.h : plot.y
      out.append(PyreonDrawCmd(kind: "line", from: PyreonChartPt(x: plot.x, y: edgeY), to: PyreonChartPt(x: plot.x + plot.w, y: edgeY), stroke: t.axis, width: 1.0))
      for tk in l.x2Ticks {
        out.append(PyreonDrawCmd(kind: "text", fill: t.label, text: tk.label, at: PyreonChartPt(x: tk.pos, y: xTop ? edgeY + 6.0 : edgeY - 6.0), size: t.fontSize, align: "middle", baseline: xTop ? "top" : "bottom"))
      }
      let inv = categoriesInverted(spec)
      for ti in 0..<l.xTicks.count {
        let tick = l.xTicks[ti]
        let j = inv ? x2.count - 1 - ti : ti
        if j < 0 || j >= x2.count {
          continue
        }
        out.append(PyreonDrawCmd(kind: "text", fill: t.label, text: x2[j], at: PyreonChartPt(x: tick.pos, y: xTop ? edgeY + 6.0 : edgeY - 6.0), size: t.fontSize, align: "middle", baseline: xTop ? "top" : "bottom"))
      }
      let x2Title = (spec.x2Title ?? "")
      if x2Title != "" {
        out.append(PyreonDrawCmd(kind: "text", fill: t.label, text: x2Title, at: PyreonChartPt(x: plot.x + plot.w / 2.0, y: xTop ? spec.height - 2.0 : 2.0), size: t.fontSize, align: "middle", baseline: xTop ? "bottom" : "top"))
      }
    }
    var extraIndex = 0.0
    for a in (spec.extraYAxes ?? []) {
      let left = a.side == "left"
      let ax = left ? plot.x - ((a.offset ?? 0.0)) : plot.x + plot.w + ((a.offset ?? 0.0))
      var widest = 0.0
      for tk in l.extraTicks {
        if tk.axis != extraIndex {
          continue
        }
        out.append(PyreonDrawCmd(kind: "text", fill: t.label, text: tk.label, at: PyreonChartPt(x: left ? ax - 6.0 : ax + 6.0, y: tk.pos), size: t.fontSize, align: left ? "end" : "start", baseline: "middle"))
        let w = measure(tk.label, t.fontSize)
        if w > widest {
          widest = w
        }
      }
      let title = (a.title ?? "")
      if title != "" && spec.showYAxis {
        let tx = left ? ax - 6.0 - widest - t.fontSize * 0.9 : ax + 6.0 + widest + t.fontSize * 0.9
        out.append(PyreonDrawCmd(kind: "text", fill: t.label, text: title, at: PyreonChartPt(x: tx, y: plot.y + plot.h / 2.0), size: t.fontSize, align: "middle", baseline: "middle", rotate: left ? -90.0 : 90.0))
      }
      extraIndex = extraIndex + 1.0
    }
    for ti in 0..<l.xTicks.count {
      let tick = l.xTicks[ti]
      if l.xLabelEvery > 1 && ti % l.xLabelEvery != 0 {
        continue
      }
      if l.xLabelRotate != 0.0 {
        out.append(PyreonDrawCmd(kind: "text", fill: t.label, text: tick.label, at: PyreonChartPt(x: tick.pos, y: xTop ? xAxisY - 6.0 : xAxisY + 6.0), size: t.fontSize, align: "end", baseline: "middle", rotate: xTop ? -l.xLabelRotate : l.xLabelRotate))
      } else {
        out.append(PyreonDrawCmd(kind: "text", fill: t.label, text: tick.label, at: PyreonChartPt(x: tick.pos, y: xTop ? xAxisY - 6.0 : xAxisY + 6.0), size: t.fontSize, align: "middle", baseline: xTop ? "bottom" : "top"))
      }
    }
    let xTitle = (spec.xTitle ?? "")
    if xTitle != "" && spec.showXAxis {
      out.append(PyreonDrawCmd(kind: "text", fill: t.label, text: xTitle, at: PyreonChartPt(x: plot.x + plot.w / 2.0, y: xTop ? 2.0 : spec.height - 2.0), size: t.fontSize, align: "middle", baseline: xTop ? "top" : "bottom"))
    }
    let yTitle = (spec.yTitle ?? "")
    if yTitle != "" && spec.showYAxis {
      out.append(PyreonDrawCmd(kind: "text", fill: t.label, text: yTitle, at: PyreonChartPt(x: yRight ? spec.width - t.fontSize * 0.9 : t.fontSize * 0.9, y: plot.y + plot.h / 2.0), size: t.fontSize, align: "middle", baseline: "middle", rotate: yRight ? 90.0 : -90.0))
    }
    let y2Title = (spec.y2Title ?? "")
    if y2Title != "" && useY2 && spec.showYAxis {
      out.append(PyreonDrawCmd(kind: "text", fill: t.label, text: y2Title, at: PyreonChartPt(x: spec.width - t.fontSize * 0.9, y: plot.y + plot.h / 2.0), size: t.fontSize, align: "middle", baseline: "middle", rotate: 90.0))
    }
    return out
  }

public func splitRuns(_ values: [Double], _ place: ([Double]) -> [PyreonChartPt]) -> [[PyreonChartPt]] {
    var runs: [[PyreonChartPt]] = []
    var hasGap = false
    for v in values {
      if !isFiniteValue(v) {
        hasGap = true
      }
    }
    if !hasGap {
      runs.append(place(values))
      return runs
    }
    var filled: [Double] = []
    for v in values {
      filled.append(isFiniteValue(v) ? v : 0.0)
    }
    let pts = place(filled)
    var runStart = -1
    for i in 0..<pts.count {
      if isFiniteValue(values[i]) {
        if runStart < 0 {
          runStart = i
        }
      } else {
        if runStart >= 0 {
          var run: [PyreonChartPt] = []
          for j in runStart..<i {
            run.append(pts[j])
          }
          runs.append(run)
          runStart = -1
        }
      }
    }
    if runStart >= 0 {
      var run: [PyreonChartPt] = []
      for j in runStart..<pts.count {
        run.append(pts[j])
      }
      runs.append(run)
    }
    return runs
  }

public func symbolCommand(_ cell: PyreonChartRect, _ symbol: String, _ fill: String) -> PyreonDrawCmd {
    if symbol == "circle" {
      let r = (cell.w < cell.h ? cell.w : cell.h) / 2.0
      return PyreonDrawCmd(kind: "circle", fill: fill, center: PyreonChartPt(x: cell.x + cell.w / 2.0, y: cell.y + cell.h / 2.0), radius: r)
    }
    if symbol == "diamond" {
      return PyreonDrawCmd(kind: "polygon", fill: fill, points: [PyreonChartPt(x: cell.x + cell.w / 2.0, y: cell.y), PyreonChartPt(x: cell.x + cell.w, y: cell.y + cell.h / 2.0), PyreonChartPt(x: cell.x + cell.w / 2.0, y: cell.y + cell.h), PyreonChartPt(x: cell.x, y: cell.y + cell.h / 2.0)])
    }
    if symbol == "triangle" {
      return PyreonDrawCmd(kind: "polygon", fill: fill, points: [PyreonChartPt(x: cell.x + cell.w / 2.0, y: cell.y), PyreonChartPt(x: cell.x + cell.w, y: cell.y + cell.h), PyreonChartPt(x: cell.x, y: cell.y + cell.h)])
    }
    return PyreonDrawCmd(kind: "rect", rect: cell, fill: fill)
  }

public func pictorialBar(_ s: Series, _ bar: PyreonChartRect, _ horizontal: Bool, _ value: Double, _ fill: String) -> PictorialBar {
    let offset = (s.symbolOffset ?? [])
    let barLength = horizontal ? bar.w : bar.h
    let hasBounding = s.symbolBoundingData != nil && value != 0.0
    let bound = (s.symbolBoundingData ?? 0.0)
    let boundingLength = hasBounding ? (barLength * Double(abs(bound))) / Double(abs(value)) : 0.0
    return PictorialBar(bar: bar, horizontal: horizontal, symbol: (s.symbol ?? "rect"), `repeat`: s.symbolRepeat == true, fill: fill, margin: (s.symbolMargin ?? 0.0), offsetX: offset.count > 0 ? offset[0] : 0.0, offsetY: offset.count > 1 ? offset[1] : 0.0, position: (s.symbolPosition ?? "start"), rotate: (s.symbolRotate ?? 0.0), clip: s.symbolClip == true, hasBounding: hasBounding, boundingLength: boundingLength)
  }

public func barsFor(_ spec: ChartSpec, _ index: Int, _ measure: (String, Double) -> Double) -> [PyreonChartRect] { barsForIn(spec, index, layoutChart(spec, measure).plot) }

public func barsForIn(_ raw: ChartSpec, _ index: Int, _ plot: PyreonChartRect) -> [PyreonChartRect] {
    let spec = geometrySpec(raw)
    let s = spec.series[index]
    if s == nil {
      return []
    }
    if (s.kind == "stacked" || s.kind == "grouped") && spec.horizontal != true {
      let idx = indicesOf(spec, s.kind)
      var local = -1
      for q in 0..<idx.count {
        if idx[q] == index {
          local = q
        }
      }
      var rects: [PyreonChartRect] = []
      for i in 0..<s.values.count {
        rects.append(PyreonChartRect(x: 0.0, y: 0.0, w: -1.0, h: -1.0))
      }
      for seg in setLaid(spec, s.kind, plot, resolveYDomain(spec)) {
        if seg.seriesIndex == local && seg.datumIndex < rects.count {
          rects[seg.datumIndex] = seg.rect
        }
      }
      return rects
    }
    if s.kind != "bars" && s.kind != "waterfall" {
      return []
    }
    let dom = seriesDomain(s, spec, resolveYDomain(spec), resolveY2Domain(spec))
    if s.kind == "waterfall" {
      var rects: [PyreonChartRect] = []
      for i in 0..<s.values.count {
        rects.append(PyreonChartRect(x: 0.0, y: 0.0, w: -1.0, h: -1.0))
      }
      for st in layoutWaterfall(s.values, plot, dom, 0.25) {
        rects[st.datumIndex] = st.rect
      }
      return rects
    }
    return barsLaid(spec, index, plot, dom)
  }

public func stackedHitAt(_ spec: ChartSpec, _ measure: (String, Double) -> Double, _ px: Double, _ py: Double) -> Int { stackedHitIn(spec, layoutChart(spec, measure).plot, px, py) }

public func markerAnchor(_ spec: ChartSpec, _ seriesIdx: Double, _ idx: Int, _ plot: PyreonChartRect, _ yDomain: Domain) -> [PyreonChartPt] {
    var out: [PyreonChartPt] = []
    var kind = ""
    var f = 0.0
    for q in spec.series {
      if f == seriesIdx {
        kind = q.kind
      }
      f = f + 1.0
    }
    if kind != "stacked" && kind != "grouped" {
      return out
    }
    var which = -1
    var seen = 0
    var g = 0.0
    for q in spec.series {
      if q.kind == kind {
        if g == seriesIdx {
          which = seen
        }
        seen = seen + 1
      }
      g = g + 1.0
    }
    if which < 0 {
      return out
    }
    let members = spec.series.filter({ q in q.kind == kind })
    let values = members.map({ q in q.values })
    let flipped = spec.horizontal == true
    let segs = kind == "stacked" ? flipped ? layoutStackedBarsH(values, plot, yDomain, 0.25) : setLaid(spec, "stacked", plot, yDomain) : flipped ? layoutGroupedBarsH(values, plot, yDomain, 0.25) : setLaid(spec, "grouped", plot, yDomain)
    for seg in segs {
      if seg.seriesIndex != which {
        continue
      }
      if seg.datumIndex != idx {
        continue
      }
      if flipped {
        out.append(PyreonChartPt(x: seg.rect.x + seg.rect.w, y: seg.rect.y + Double(seg.rect.h) / 2.0))
      } else {
        out.append(PyreonChartPt(x: seg.rect.x + Double(seg.rect.w) / 2.0, y: seg.rect.y))
      }
    }
    return out
  }

public func stackedHitIn(_ raw: ChartSpec, _ plot: PyreonChartRect, _ px: Double, _ py: Double) -> Int {
    let spec = geometrySpec(raw)
    let yDomain = resolveYDomain(spec)
    let flipped = raw.horizontal == true
    for kind in ["stacked", "grouped"] {
      let series = spec.series.filter({ s in s.kind == kind })
      if series.count == 0 {
        continue
      }
      let values = series.map({ s in s.values })
      let segs = kind == "stacked" ? flipped ? layoutStackedBarsH(values, plot, yDomain, 0.25) : setLaid(spec, "stacked", plot, yDomain) : flipped ? layoutGroupedBarsH(values, plot, yDomain, 0.25) : setLaid(spec, "grouped", plot, yDomain)
      for seg in segs {
        let r = seg.rect
        if px >= r.x && px <= r.x + r.w && py >= r.y && py <= r.y + r.h {
          return categoryIndex(raw, seg.datumIndex)
        }
      }
    }
    return -1
  }

public func retype(_ s: Series, _ kind: String, _ stack: String) -> Series {
    var k = s.kind
    if kind == "line" {
      if k == "bars" || k == "grouped" {
        k = "line"
      } else {
        if k == "stacked" {
          k = "stackedArea"
        }
      }
    } else {
      if kind == "bar" {
        if k == "line" || k == "area" {
          k = "bars"
        } else {
          if k == "stackedArea" {
            k = "stacked"
          }
        }
      }
    }
    if stack == "stack" {
      if k == "bars" || k == "grouped" {
        k = "stacked"
      } else {
        if k == "line" || k == "area" {
          k = "stackedArea"
        }
      }
    } else {
      if stack == "tiled" {
        if k == "stacked" {
          k = "bars"
        } else {
          if k == "stackedArea" {
            k = "line"
          }
        }
      }
    }
    return { var c = s; c.kind = k; return c }()
  }

public func applyMagicType(_ spec: ChartSpec, _ kind: String, _ stack: String) -> ChartSpec {
    if kind == "" && stack == "" {
      return spec
    }
    var series: [Series] = []
    var bars = 0.0
    for s in spec.series {
      let r = retype(s, kind, stack)
      if r.kind == "bars" {
        bars = bars + 1.0
      }
      series.append(r)
    }
    var out: [Series] = []
    for s in series {
      out.append(bars > 1.0 && s.kind == "bars" ? { var c = s; c.kind = "grouped"; return c }() : s)
    }
    return { var c = spec; c.series = out; return c }()
  }

public func ohlcExtent(_ candles: [Ohlc]) -> Domain {
    if candles.count == 0 {
      return Domain(min: 0.0, max: 1.0)
    }
    var lo = candles[0].low
    var hi = candles[0].high
    for c in candles {
      if c.low < lo {
        lo = c.low
      }
      if c.high > hi {
        hi = c.high
      }
    }
    if hi <= lo {
      return Domain(min: lo - 1.0, max: lo + 1.0)
    }
    return Domain(min: lo, max: hi)
  }

public func renderCandles(_ candles: [Ohlc], _ plot: PyreonChartRect, _ domain: Domain, _ options: CandleOptions? = nil) -> [PyreonDrawCmd] {
    let up = (options?.upColor ?? "#15803d")
    let down = (options?.downColor ?? "#b42318")
    let rawRatio = (options?.widthRatio ?? 0.6)
    let ratio = rawRatio < 0.05 ? 0.05 : rawRatio > 0.9 ? 0.9 : rawRatio
    var out: [PyreonDrawCmd] = []
    let n = candles.count
    if n == 0 {
      return out
    }
    var nF = 0.0
    for i in 0..<n {
      nF = nF + 1.0
    }
    let band = plot.w / nF
    let bw = band * ratio
    let y0 = plot.y + plot.h
    var iF = 0.0
    for i in 0..<n {
      let c = candles[i]
      let cx = plot.x + band * iF + band / 2.0
      let color = c.close >= c.`open` ? up : down
      out.append(PyreonDrawCmd(kind: "line", from: PyreonChartPt(x: cx, y: scaleLinear(domain, y0, plot.y, c.high)), to: PyreonChartPt(x: cx, y: scaleLinear(domain, y0, plot.y, c.low)), stroke: color, width: 1.0))
      let yo = scaleLinear(domain, y0, plot.y, c.`open`)
      let yc = scaleLinear(domain, y0, plot.y, c.close)
      let top = yo < yc ? yo : yc
      let rawH = yc - yo
      let h = rawH < 0.0 ? -rawH : rawH
      out.append(PyreonDrawCmd(kind: "rect", rect: PyreonChartRect(x: cx - bw / 2.0, y: top, w: bw, h: h < 1.0 ? 1.0 : h), fill: color))
      iF = iF + 1.0
    }
    return out
  }

public func hitCandle(_ count: Int, _ plot: PyreonChartRect, _ px: Double, _ py: Double) -> Int {
    if count <= 0 {
      return -1
    }
    if px < plot.x || px > plot.x + plot.w {
      return -1
    }
    if py < plot.y || py > plot.y + plot.h {
      return -1
    }
    let band = plot.w / Double(count)
    let target = (px - plot.x) / band
    var i = 0
    var jf = 0.0
    for j in 0..<count {
      if jf <= target {
        i = j
      }
      jf = jf + 1.0
    }
    return i
  }

public func buildHeatGrid(_ cols: [String], _ rows: [String], _ colOf: [Double], _ rowOf: [Double], _ values: [Double]) -> HeatGrid {
    let n1 = colOf.count < rowOf.count ? colOf.count : rowOf.count
    let n = n1 < values.count ? n1 : values.count
    var cellCol: [Double] = []
    var cellRow: [Double] = []
    var cellVal: [Double] = []
    for i in 0..<n {
      let c = colOf[i]
      let r = rowOf[i]
      if c < 0.0 || r < 0.0 {
        continue
      }
      var found = -1
      for k in 0..<cellCol.count {
        if found < 0 && cellCol[k] == c && cellRow[k] == r {
          found = k
        }
      }
      if found < 0 {
        cellCol.append(c)
        cellRow.append(r)
        cellVal.append(values[i])
      } else {
        cellVal[found] = cellVal[found] + values[i]
      }
    }
    var cells: [HeatCell] = []
    var minV = 0.0
    var maxV = 0.0
    for k in 0..<cellCol.count {
      cells.append(HeatCell(col: cellCol[k], row: cellRow[k], value: cellVal[k]))
      if k == 0 {
        minV = cellVal[k]
        maxV = cellVal[k]
      } else {
        if cellVal[k] < minV {
          minV = cellVal[k]
        }
        if cellVal[k] > maxV {
          maxV = cellVal[k]
        }
      }
    }
    return HeatGrid(cols: cols, rows: rows, cells: cells, min: minV, max: maxV)
  }

public func heatHexDigit(_ c: Double) -> Double {
    if c >= 48.0 && c <= 57.0 {
      return c - 48.0
    }
    if c >= 97.0 && c <= 102.0 {
      return c - 87.0
    }
    if c >= 65.0 && c <= 70.0 {
      return c - 55.0
    }
    return 0.0
  }

public func heatChannel(_ hex: String, _ at: Int) -> Double {
    if hex.utf16.count < at + 2 {
      return 0.0
    }
    return heatHexDigit(Double(Array(hex.utf16)[Int(at)])) * 16.0 + heatHexDigit(Double(Array(hex.utf16)[Int(at + 1)]))
  }

public func heatHashOffset(_ hex: String) -> Int {
    if hex.utf16.count > 0 && Double(Array(hex.utf16)[Int(0)]) == 35.0 {
      return 1
    }
    return 0
  }

public func rampColor(_ stops: [String], _ t: Double) -> String {
    let n = stops.count
    if n == 0 {
      return "rgb(0, 0, 0)"
    }
    if n == 1 || t <= 0.0 {
      let s0 = stops[0]
      let o0 = heatHashOffset(s0)
      return "rgb(\(((Double(heatChannel(s0, o0))) + 0.5).rounded(.down)), \(((Double(heatChannel(s0, o0 + 2))) + 0.5).rounded(.down)), \(((Double(heatChannel(s0, o0 + 4))) + 0.5).rounded(.down)))"
    }
    let clamped = t >= 1.0 ? 1.0 : t
    var spanF = 0.0
    for i in 1..<n {
      spanF = spanF + 1.0
    }
    let pos = clamped * spanF
    let rawIdx = floor(Double(pos))
    let idx = rawIdx > spanF - 1.0 ? spanF - 1.0 : rawIdx
    let frac = pos - idx
    var a = stops[0]
    var b = stops[1]
    var iF = 0.0
    let last = n - 1
    for i in 0..<last {
      if iF == idx {
        a = stops[i]
        b = stops[i + 1]
      }
      iF = iF + 1.0
    }
    let oa = heatHashOffset(a)
    let ob = heatHashOffset(b)
    let r = heatChannel(a, oa) + (heatChannel(b, ob) - heatChannel(a, oa)) * frac
    let g = heatChannel(a, oa + 2) + (heatChannel(b, ob + 2) - heatChannel(a, oa + 2)) * frac
    let bl = heatChannel(a, oa + 4) + (heatChannel(b, ob + 4) - heatChannel(a, oa + 4)) * frac
    return "rgb(\(((Double(r)) + 0.5).rounded(.down)), \(((Double(g)) + 0.5).rounded(.down)), \(((Double(bl)) + 0.5).rounded(.down)))"
  }

public func visualOutside(_ v: Double, _ inRange: Domain?, _ outBands: [Double]?) -> Bool {
    let lo = (inRange?.min ?? v)
    let hi = (inRange?.max ?? v)
    if v < lo || v > hi {
      return true
    }
    let bands = (outBands ?? [])
    var i = 0
    while i + 1 < bands.count {
      if v >= bands[i] && v <= bands[i + 1] {
        return true
      }
      i = i + 2
    }
    return false
  }

public func renderHeat(_ options: HeatmapOptions) -> [PyreonDrawCmd] {
    let grid = options.grid
    let plot = options.plot
    let stops = (options.stops ?? HEAT_RAMP)
    let gap = (options.gap ?? 1.0)
    let rawP = (options.progress ?? 1.0)
    let progress = rawP < 0.0 ? 0.0 : rawP > 1.0 ? 1.0 : rawP
    var out: [PyreonDrawCmd] = []
    let nc = grid.cols.count
    let nr = grid.rows.count
    if nc == 0 || nr == 0 {
      return out
    }
    var ncF = 0.0
    for i in 0..<nc {
      ncF = ncF + 1.0
    }
    var nrF = 0.0
    for i in 0..<nr {
      nrF = nrF + 1.0
    }
    let cw = plot.w / ncF
    let ch = plot.h / nrF
    let lo = (options.domain?.min ?? grid.min)
    let span = ((options.domain?.max ?? grid.max)) - lo
    let outColor = (options.outColor ?? "#cccccc")
    for cell in grid.cells {
      if cell.col >= ncF || cell.row >= nrF {
        continue
      }
      let rawT = span <= 0.0 ? 1.0 : (cell.value - lo) / span
      let t = rawT < 0.0 ? 0.0 : rawT > 1.0 ? 1.0 : rawT
      let fullW = cw - gap
      let fullH = ch - gap
      let w = fullW * progress
      let h = fullH * progress
      let x = plot.x + cell.col * cw + gap / 2.0 + Double((fullW - w)) / 2.0
      let y = plot.y + cell.row * ch + gap / 2.0 + Double((fullH - h)) / 2.0
      out.append(PyreonDrawCmd(kind: "rect", rect: PyreonChartRect(x: x, y: y, w: w, h: h), fill: visualOutside(cell.value, options.inRange, options.outBands) ? outColor : rampColor(stops, t)))
    }
    return out
  }

public func hitHeatCell(_ grid: HeatGrid, _ plot: PyreonChartRect, _ gap: Double, _ px: Double, _ py: Double) -> Int {
    let nc = grid.cols.count
    let nr = grid.rows.count
    if nc == 0 || nr == 0 {
      return -1
    }
    if px < plot.x || px > plot.x + plot.w || py < plot.y || py > plot.y + plot.h {
      return -1
    }
    var ncF = 0.0
    for i in 0..<nc {
      ncF = ncF + 1.0
    }
    var nrF = 0.0
    for i in 0..<nr {
      nrF = nrF + 1.0
    }
    let cw = plot.w / ncF
    let ch = plot.h / nrF
    let rawCol = floor(Double((px - plot.x) / cw))
    let col = rawCol > ncF - 1.0 ? ncF - 1.0 : rawCol
    let rawRow = floor(Double((py - plot.y) / ch))
    let row = rawRow > nrF - 1.0 ? nrF - 1.0 : rawRow
    let inX = px - (plot.x + col * cw)
    let inY = py - (plot.y + row * ch)
    if inX < gap / 2.0 || inX > cw - gap / 2.0 {
      return -1
    }
    if inY < gap / 2.0 || inY > ch - gap / 2.0 {
      return -1
    }
    var hit = -1
    for i in 0..<grid.cells.count {
      let c = grid.cells[i]
      if hit < 0 && c.col == col && c.row == row {
        hit = i
      }
    }
    return hit
  }

public func labelWidth(_ s: VisualStrip) -> Double { s.fontSize * 3.2 }

public func pieceTextWidth(_ s: VisualStrip, _ label: String) -> Double { Double(label.utf16.count) * s.fontSize * 0.55 }

public func span(_ d: Domain) -> Double { d.max - d.min }

public func barOrigin(_ s: VisualStrip, _ at: PyreonChartPt) -> PyreonChartPt {
    if s.vertical {
      return PyreonChartPt(x: at.x, y: at.y + s.fontSize + STRIP_GAP)
    }
    return PyreonChartPt(x: at.x + labelWidth(s) + STRIP_GAP, y: at.y)
  }

public func visualStripSize(_ s: VisualStrip) -> PyreonChartPt {
    if s.piecewise {
      if s.vertical {
        var widest = 0.0
        for p in s.pieces {
          if pieceTextWidth(s, p.label) > widest {
            widest = pieceTextWidth(s, p.label)
          }
        }
        var n = 0.0
        for _p in s.pieces {
          n = n + 1.0
        }
        return PyreonChartPt(x: s.itemSize + STRIP_GAP + widest, y: n <= 0 ? 0.0 : n * (s.itemSize + STRIP_GAP) - STRIP_GAP)
      }
      var w = 0.0
      for p in s.pieces {
        w = w + s.itemSize + STRIP_GAP + pieceTextWidth(s, p.label) + STRIP_GAP * 2.0
      }
      return PyreonChartPt(x: w <= 0.0 ? 0.0 : w - STRIP_GAP * 2.0, y: s.itemSize)
    }
    let handleSpace = s.calculable ? STRIP_HANDLE + STRIP_GAP + labelWidth(s) : 0.0
    if s.vertical {
      var w = s.itemSize + handleSpace
      return PyreonChartPt(x: w > labelWidth(s) ? w : labelWidth(s), y: s.fontSize * 2.0 + STRIP_GAP * 2.0 + s.itemLength)
    }
    return PyreonChartPt(x: labelWidth(s) * 2.0 + STRIP_GAP * 2.0 + s.itemLength, y: s.itemSize + (s.calculable ? STRIP_HANDLE + STRIP_GAP + s.fontSize + 2.0 : 0.0))
  }

public func fraction(_ s: VisualStrip, _ v: Double) -> Double {
    let sp = span(s.domain)
    if !(sp > 0.0) {
      return 1.0
    }
    let t = (v - s.domain.min) / sp
    return t < 0.0 ? 0.0 : t > 1.0 ? 1.0 : t
  }

public func valuePoint(_ s: VisualStrip, _ at: PyreonChartPt, _ v: Double) -> PyreonChartPt {
    let o = barOrigin(s, at)
    let t = fraction(s, v)
    if s.vertical {
      return PyreonChartPt(x: o.x + s.itemSize, y: o.y + (1.0 - t) * s.itemLength)
    }
    return PyreonChartPt(x: o.x + t * s.itemLength, y: o.y + s.itemSize)
  }

public func pieceContains(_ p: VisualPiece, _ v: Double) -> Bool {
    if p.min != nil && v < ((p.min ?? v)) {
      return false
    }
    if p.max != nil && v > ((p.max ?? v)) {
      return false
    }
    return true
  }

public func visualInRange(_ s: VisualStrip, _ v: Double, _ range: Domain, _ selected: [Bool]) -> Bool {
    if s.piecewise {
      var inAny = false
      for i in 0..<s.pieces.count {
        if !pieceContains(s.pieces[i], v) {
          continue
        }
        inAny = true
        if i >= selected.count || selected[i] {
          return true
        }
      }
      return !inAny
    }
    return v >= range.min && v <= range.max
  }

public func visualColorFor(_ s: VisualStrip, _ v: Double, _ range: Domain, _ selected: [Bool]) -> String {
    if !visualInRange(s, v, range, selected) {
      return s.outColor
    }
    if s.piecewise {
      for p in s.pieces {
        if pieceContains(p, v) {
          return p.color
        }
      }
    }
    return rampColor(s.stops, fraction(s, v))
  }

public func renderVisualStrip(_ s: VisualStrip, _ at: PyreonChartPt, _ range: Domain, _ selected: [Bool]) -> [PyreonDrawCmd] {
    var out: [PyreonDrawCmd] = []
    let fs = s.fontSize
    if s.piecewise {
      var x = at.x
      var y = at.y
      for i in 0..<s.pieces.count {
        let p = s.pieces[i]
        let on = i >= selected.count || selected[i]
        out.append(PyreonDrawCmd(kind: "rect", rect: PyreonChartRect(x: x, y: y, w: s.itemSize, h: s.itemSize), fill: on ? p.color : s.outColor))
        out.append(PyreonDrawCmd(kind: "text", fill: on ? s.labelColor : s.outColor, text: p.label, at: PyreonChartPt(x: x + s.itemSize + STRIP_GAP, y: y + s.itemSize / 2.0), size: fs, align: "start", baseline: "middle"))
        if s.vertical {
          y = y + s.itemSize + STRIP_GAP
        } else {
          x = x + s.itemSize + STRIP_GAP + pieceTextWidth(s, p.label) + STRIP_GAP * 2.0
        }
      }
      return out
    }
    let o = barOrigin(s, at)
    let high = s.highText == "" ? plain(s.domain.max) : s.highText
    let low = s.lowText == "" ? plain(s.domain.min) : s.lowText
    var i = 0.0
    while i < STRIP_COUNT {
      let t = s.vertical ? 1.0 - (i + 0.5) / Double(STRIP_COUNT) : (i + 0.5) / Double(STRIP_COUNT)
      let v = s.domain.min + t * span(s.domain)
      let fill = s.calculable && (v < range.min || v > range.max) ? s.outColor : rampColor(s.stops, t)
      if s.vertical {
        out.append(PyreonDrawCmd(kind: "rect", rect: PyreonChartRect(x: o.x, y: o.y + (s.itemLength * i) / Double(STRIP_COUNT), w: s.itemSize, h: s.itemLength / Double(STRIP_COUNT) + 0.5), fill: fill))
      } else {
        out.append(PyreonDrawCmd(kind: "rect", rect: PyreonChartRect(x: o.x + (s.itemLength * i) / Double(STRIP_COUNT), y: o.y, w: s.itemLength / Double(STRIP_COUNT) + 0.5, h: s.itemSize), fill: fill))
      }
      i = i + 1.0
    }
    if s.vertical {
      out.append(PyreonDrawCmd(kind: "text", fill: s.labelColor, text: high, at: PyreonChartPt(x: o.x + s.itemSize / 2.0, y: at.y), size: fs, align: "middle", baseline: "top"))
      out.append(PyreonDrawCmd(kind: "text", fill: s.labelColor, text: low, at: PyreonChartPt(x: o.x + s.itemSize / 2.0, y: o.y + s.itemLength + STRIP_GAP), size: fs, align: "middle", baseline: "top"))
    } else {
      out.append(PyreonDrawCmd(kind: "text", fill: s.labelColor, text: low, at: PyreonChartPt(x: o.x - STRIP_GAP, y: o.y + s.itemSize / 2.0), size: fs, align: "end", baseline: "middle"))
      out.append(PyreonDrawCmd(kind: "text", fill: s.labelColor, text: high, at: PyreonChartPt(x: o.x + s.itemLength + STRIP_GAP, y: o.y + s.itemSize / 2.0), size: fs, align: "start", baseline: "middle"))
    }
    if !s.calculable {
      return out
    }
    let ends = [range.min, range.max]
    for e in 0..<2 {
      let v = ends[e]
      let p = valuePoint(s, at, v)
      let color = rampColor(s.stops, fraction(s, v))
      if s.vertical {
        out.append(PyreonDrawCmd(kind: "polygon", fill: color, points: [PyreonChartPt(x: p.x, y: p.y), PyreonChartPt(x: p.x + STRIP_HANDLE, y: p.y - Double(STRIP_HANDLE) / 2.0), PyreonChartPt(x: p.x + STRIP_HANDLE, y: p.y + Double(STRIP_HANDLE) / 2.0)]))
        out.append(PyreonDrawCmd(kind: "text", fill: s.labelColor, text: plain(v), at: PyreonChartPt(x: p.x + STRIP_HANDLE + STRIP_GAP, y: p.y), size: fs, align: "start", baseline: "middle"))
      } else {
        out.append(PyreonDrawCmd(kind: "polygon", fill: color, points: [PyreonChartPt(x: p.x, y: p.y), PyreonChartPt(x: p.x - Double(STRIP_HANDLE) / 2.0, y: p.y + STRIP_HANDLE), PyreonChartPt(x: p.x + Double(STRIP_HANDLE) / 2.0, y: p.y + STRIP_HANDLE)]))
        out.append(PyreonDrawCmd(kind: "text", fill: s.labelColor, text: plain(v), at: PyreonChartPt(x: p.x, y: p.y + STRIP_HANDLE + STRIP_GAP), size: fs, align: "middle", baseline: "top"))
      }
    }
    return out
  }

public func visualStripHandleAt(_ s: VisualStrip, _ at: PyreonChartPt, _ range: Domain, _ px: Double, _ py: Double) -> Double {
    if s.piecewise || !s.calculable {
      return -1.0
    }
    let reach = STRIP_HANDLE + 4.0
    var best = -1.0
    var bestD = reach * 1.5
    var e = 0.0
    while e < 2.0 {
      let p = valuePoint(s, at, e == 0.0 ? range.min : range.max)
      let cx = s.vertical ? p.x + Double(STRIP_HANDLE) / 2.0 : p.x
      let cy = s.vertical ? p.y : p.y + Double(STRIP_HANDLE) / 2.0
      let d = abs(px - cx) + abs(py - cy)
      if d <= bestD {
        bestD = d
        best = e
      }
      e = e + 1.0
    }
    return best
  }

public func visualStripValueAt(_ s: VisualStrip, _ at: PyreonChartPt, _ px: Double, _ py: Double) -> Double {
    let o = barOrigin(s, at)
    let raw = s.vertical ? 1.0 - (py - o.y) / (s.itemLength > 0.0 ? s.itemLength : 1.0) : (px - o.x) / (s.itemLength > 0.0 ? s.itemLength : 1.0)
    let t = raw < 0.0 ? 0.0 : raw > 1.0 ? 1.0 : raw
    return s.domain.min + t * span(s.domain)
  }

public func visualStripDrag(_ s: VisualStrip, _ range: Domain, _ handle: Double, _ value: Double) -> Domain {
    if handle == 0.0 {
      return Domain(min: value < range.max ? value : range.max, max: range.max)
    }
    return Domain(min: range.min, max: value > range.min ? value : range.min)
  }

public func visualStripPieceAt(_ s: VisualStrip, _ at: PyreonChartPt, _ px: Double, _ py: Double) -> Double {
    if !s.piecewise {
      return -1.0
    }
    var x = at.x
    var y = at.y
    var i = 0.0
    for piece in s.pieces {
      let w = s.itemSize + STRIP_GAP + pieceTextWidth(s, piece.label)
      if px >= x && px <= x + w && py >= y && py <= y + s.itemSize {
        return i
      }
      i = i + 1.0
      if s.vertical {
        y = y + s.itemSize + STRIP_GAP
      } else {
        x = x + w + STRIP_GAP * 2.0
      }
    }
    return -1.0
  }

public func visualStripToggle(_ s: VisualStrip, _ selected: [Bool], _ index: Double) -> [Bool] {
    var out: [Bool] = []
    var i = 0.0
    for _p in s.pieces {
      let on = i >= Double(selected.count) || selected[Int(i)]
      out.append(i == index ? !on : on)
      i = i + 1.0
    }
    return out
  }

public func visualOutBands(_ s: VisualStrip, _ selected: [Bool]) -> [Double] {
    var out: [Double] = []
    if !s.piecewise {
      return out
    }
    let reach = (s.domain.max - s.domain.min) * 1000.0 + 1000000.0
    var i = 0.0
    for p in s.pieces {
      let on = i >= Double(selected.count) || selected[Int(i)]
      if !on {
        out.append((p.min ?? s.domain.min - reach))
        out.append((p.max ?? s.domain.max + reach))
      }
      i = i + 1.0
    }
    return out
  }

public func visualStripPlace(_ s: VisualStrip, _ w: Double, _ h: Double) -> VisualStripPlacement {
    let size = visualStripSize(s)
    let margin = 8.0
    if s.vertical {
      let chartW = w - size.x - margin
      return VisualStripPlacement(at: PyreonChartPt(x: w - size.x, y: h - size.y > 0.0 ? h - size.y : 0.0), chartW: chartW > 0.0 ? chartW : 0.0, chartH: h)
    }
    let chartH = h - size.y - margin
    return VisualStripPlacement(at: PyreonChartPt(x: 0.0, y: h - size.y), chartW: w, chartH: chartH > 0.0 ? chartH : 0.0)
  }

public func axisSpan(_ s: TimelineStrip, _ box: PyreonChartRect) -> TimelineAxis {
    var left = box.x + PAD
    if s.showPlay {
      left = left + BTN + BTN_GAP
    }
    if s.showPrev {
      left = left + BTN + BTN_GAP
    }
    var right = box.x + box.w - PAD
    if s.showNext {
      right = right - BTN - BTN_GAP
    }
    return TimelineAxis(x0: left, x1: right > left ? right : left, cy: box.y + box.h * 0.4)
  }

public func stepCount(_ s: TimelineStrip) -> Double {
    var n = 0.0
    for _l in s.labels {
      n = n + 1.0
    }
    return n
  }

public func checkpointX(_ s: TimelineStrip, _ box: PyreonChartRect, _ i: Double) -> Double {
    let a = axisSpan(s, box)
    let n = stepCount(s)
    return n <= 1.0 ? (a.x0 + a.x1) / 2.0 : a.x0 + ((a.x1 - a.x0) * i) / (n - 1.0)
  }

public func playCenter(_ s: TimelineStrip, _ box: PyreonChartRect) -> Double { box.x + PAD + Double(BTN) / 2.0 }

public func prevCenter(_ s: TimelineStrip, _ box: PyreonChartRect) -> Double { box.x + PAD + (s.showPlay ? BTN + BTN_GAP : 0.0) + Double(BTN) / 2.0 }

public func nextCenter(_ _s: TimelineStrip, _ box: PyreonChartRect) -> Double { box.x + box.w - PAD - Double(BTN) / 2.0 }

public func renderTimeline(_ s: TimelineStrip, _ box: PyreonChartRect, _ current: Double, _ playing: Bool) -> [PyreonDrawCmd] {
    var out: [PyreonDrawCmd] = []
    let n = stepCount(s)
    if n <= 0.0 {
      return out
    }
    let a = axisSpan(s, box)
    let cy = a.cy
    out.append(PyreonDrawCmd(kind: "line", from: PyreonChartPt(x: a.x0, y: cy), to: PyreonChartPt(x: a.x1, y: cy), stroke: s.line, width: 1.0))
    var i = 0.0
    for label in s.labels {
      let x = checkpointX(s, box, i)
      let on = i == current
      out.append(PyreonDrawCmd(kind: "circle", fill: s.accent, center: PyreonChartPt(x: x, y: cy), radius: on ? 5.0 : 3.5))
      if !on {
        out.append(PyreonDrawCmd(kind: "circle", fill: "#ffffff", center: PyreonChartPt(x: x, y: cy), radius: 2.5))
      }
      out.append(PyreonDrawCmd(kind: "text", fill: on ? s.accent : s.label, text: label, at: PyreonChartPt(x: x, y: cy + 8.0), size: s.fontSize, align: "middle", baseline: "top"))
      i = i + 1.0
    }
    let h = Double(BTN) / 2.0
    if s.showPlay {
      let px = playCenter(s, box)
      if playing {
        out.append(PyreonDrawCmd(kind: "rect", rect: PyreonChartRect(x: px - h * 0.7, y: cy - h * 0.7, w: h * 0.5, h: h * 1.4), fill: s.accent))
        out.append(PyreonDrawCmd(kind: "rect", rect: PyreonChartRect(x: px + h * 0.2, y: cy - h * 0.7, w: h * 0.5, h: h * 1.4), fill: s.accent))
      } else {
        out.append(PyreonDrawCmd(kind: "polygon", fill: s.accent, points: [PyreonChartPt(x: px - h * 0.6, y: cy - h * 0.75), PyreonChartPt(x: px + h * 0.8, y: cy), PyreonChartPt(x: px - h * 0.6, y: cy + h * 0.75)]))
      }
    }
    if s.showPrev {
      let px = prevCenter(s, box)
      out.append(PyreonDrawCmd(kind: "polygon", fill: s.line, points: [PyreonChartPt(x: px + h * 0.6, y: cy - h * 0.7), PyreonChartPt(x: px - h * 0.6, y: cy), PyreonChartPt(x: px + h * 0.6, y: cy + h * 0.7)]))
    }
    if s.showNext {
      let px = nextCenter(s, box)
      out.append(PyreonDrawCmd(kind: "polygon", fill: s.line, points: [PyreonChartPt(x: px - h * 0.6, y: cy - h * 0.7), PyreonChartPt(x: px + h * 0.6, y: cy), PyreonChartPt(x: px - h * 0.6, y: cy + h * 0.7)]))
    }
    return out
  }

public func timelineHit(_ s: TimelineStrip, _ box: PyreonChartRect, _ px: Double, _ py: Double) -> TimelineHit {
    let none = TimelineHit(kind: 0.0, index: -1.0)
    if py < box.y || py > box.y + box.h || stepCount(s) <= 0.0 {
      return none
    }
    let cy = axisSpan(s, box).cy
    let reach = Double(BTN) / 2.0 + 4.0
    let near = { (cx: Double) in (px - cx < 0.0 ? cx - px : px - cx) <= reach && (py - cy < 0.0 ? cy - py : py - cy) <= reach + 6.0 }
    if s.showPlay && near(playCenter(s, box)) {
      return TimelineHit(kind: 2.0, index: -1.0)
    }
    if s.showPrev && near(prevCenter(s, box)) {
      return TimelineHit(kind: 3.0, index: -1.0)
    }
    if s.showNext && near(nextCenter(s, box)) {
      return TimelineHit(kind: 4.0, index: -1.0)
    }
    var best = -1.0
    var bestD = 14.0
    var i = 0.0
    for _l in s.labels {
      let d = px - checkpointX(s, box, i)
      let ad = d < 0.0 ? 0.0 - d : d
      if ad <= bestD {
        bestD = ad
        best = i
      }
      i = i + 1.0
    }
    return best < 0.0 ? none : TimelineHit(kind: 1.0, index: best)
  }

public func timelineAdvance(_ s: TimelineStrip, _ current: Double, _ dir: Double, _ wrap: Bool) -> Double {
    let n = stepCount(s)
    if n <= 0.0 {
      return -1.0
    }
    let next = current + dir
    if next >= 0.0 && next < n {
      return next
    }
    if !wrap {
      return -1.0
    }
    return next < 0.0 ? n - 1.0 : 0.0
  }

public func timelineTick(_ s: TimelineStrip, _ current: Double) -> Double { timelineAdvance(s, current, s.rewind ? -1.0 : 1.0, s.loop) }

public func layoutFunnel(_ stages: [FunnelStage], _ plot: PyreonChartRect, _ options: FunnelOptions? = nil) -> [FunnelStageGeometry] {
    var out: [FunnelStageGeometry] = []
    let n = stages.count
    if n == 0 {
      return out
    }
    let gap = (options?.gap ?? 2.0)
    let rawMin = (options?.minWidthRatio ?? 0.0)
    let minRatio = rawMin < 0.0 ? 0.0 : rawMin > 1.0 ? 1.0 : rawMin
    let sort = (options?.sort ?? "descending")
    let align = (options?.align ?? "center")
    var order: [Int] = []
    var nf = 0.0
    for i in 0..<n {
      order.append(i)
      nf = nf + 1.0
    }
    if sort != "none" {
      for i in 1..<n {
        let cur = order[i]
        var j = i - 1
        while j >= 0 {
          let a = stages[order[j]].value
          let b = stages[cur].value
          let swap = sort == "descending" ? a < b : a > b
          if !swap {
            break
          }
          order[j + 1] = order[j]
          j = j - 1
        }
        order[j + 1] = cur
      }
    }
    var maxV = 0.0
    for s in stages {
      if s.value > maxV {
        maxV = s.value
      }
    }
    let stageH = (plot.h - gap * (nf - 1.0)) / nf
    var kf = 0.0
    for k in 0..<n {
      let idx = order[k]
      let next = k + 1 < n ? order[k + 1] : -1
      let topRatio = maxV <= 0.0 ? 1.0 : stages[idx].value / maxV
      let topW = plot.w * (topRatio < minRatio ? minRatio : topRatio)
      let nextRatio = next >= 0 ? (maxV <= 0.0 ? 1.0 : stages[next].value / maxV) : minRatio
      let bottomW = plot.w * (nextRatio < minRatio ? minRatio : nextRatio)
      let top = plot.y + kf * (stageH + gap)
      let cx = align == "left" ? plot.x + Double(topW) / 2.0 : align == "right" ? plot.x + plot.w - Double(topW) / 2.0 : plot.x + plot.w / 2.0
      out.append(FunnelStageGeometry(index: idx, top: top, bottom: top + stageH, topWidth: topW, bottomWidth: bottomW, centerX: cx))
      kf = kf + 1.0
    }
    return out
  }

public func renderFunnel(_ stages: [FunnelStage], _ plot: PyreonChartRect, _ options: FunnelOptions? = nil) -> [PyreonDrawCmd] {
    var out: [PyreonDrawCmd] = []
    let geo = layoutFunnel(stages, plot, options)
    let rawP = (options?.progress ?? 1.0)
    let progress = rawP < 0.0 ? 0.0 : rawP > 1.0 ? 1.0 : rawP
    let showLabels = (options?.showLabels ?? true)
    let labelColor = (options?.labelColor ?? "#ffffff")
    let fontSize = (options?.fontSize ?? 11.0)
    let align = (options?.align ?? "center")
    for g in geo {
      let s = stages[g.index]
      let tw = g.topWidth * progress
      let bw = g.bottomWidth * progress
      let cxTop = align == "left" ? plot.x + Double(tw) / 2.0 : g.centerX
      let cxBottom = align == "left" ? plot.x + Double(bw) / 2.0 : align == "right" ? plot.x + plot.w - Double(bw) / 2.0 : g.centerX
      out.append(PyreonDrawCmd(kind: "polygon", fill: s.color, points: [PyreonChartPt(x: cxTop - Double(tw) / 2.0, y: g.top), PyreonChartPt(x: cxTop + Double(tw) / 2.0, y: g.top), PyreonChartPt(x: cxBottom + Double(bw) / 2.0, y: g.bottom), PyreonChartPt(x: cxBottom - Double(bw) / 2.0, y: g.bottom)]))
      if showLabels && progress >= 1.0 {
        out.append(PyreonDrawCmd(kind: "text", fill: labelColor, text: s.label, at: PyreonChartPt(x: cxTop, y: Double((g.top + g.bottom)) / 2.0), size: fontSize, align: "middle", baseline: "middle"))
      }
    }
    return out
  }

public func hitFunnel(_ stages: [FunnelStage], _ plot: PyreonChartRect, _ px: Double, _ py: Double, _ options: FunnelOptions? = nil) -> Int {
    for g in layoutFunnel(stages, plot, options) {
      if py < g.top || py > g.bottom {
        continue
      }
      let t = g.bottom <= g.top ? 0.0 : (py - g.top) / Double((g.bottom - g.top))
      let w = g.topWidth + (g.bottomWidth - g.topWidth) * t
      if px >= g.centerX - Double(w) / 2.0 && px <= g.centerX + Double(w) / 2.0 {
        return g.index
      }
    }
    return -1
  }

public func nodeValue(_ node: TreeNode) -> Double {
    if node.value != nil {
      return (node.value ?? 0.0)
    }
    var sum = 0.0
    var stack: [TreeNode] = []
    var sp = 0
    for c in (node.children ?? []) {
      if sp < stack.count {
        stack[sp] = c
      } else {
        stack.append(c)
      }
      sp = sp + 1
    }
    while sp > 0 {
      sp = sp - 1
      let cur = stack[sp]
      let own = cur.value
      if own != nil {
        sum = sum + ((own ?? 0.0))
      } else {
        for c in (cur.children ?? []) {
          if sp < stack.count {
            stack[sp] = c
          } else {
            stack.append(c)
          }
          sp = sp + 1
        }
      }
    }
    return sum
  }

public func worstRatio(_ row: [Double], _ side: Double, _ areaScale: Double) -> Double {
    if row.count == 0 || side <= 0.0 {
      return -1.0
    }
    var sum = 0.0
    var maxA = 0.0
    var minA = -1.0
    for v in row {
      let a = v * areaScale
      sum = sum + a
      if a > maxA {
        maxA = a
      }
      if minA < 0.0 || a < minA {
        minA = a
      }
    }
    if sum <= 0.0 || minA <= 0.0 {
      return -1.0
    }
    let s2 = side * side
    let r1 = (s2 * maxA) / (sum * sum)
    let r2 = (sum * sum) / (s2 * minA)
    return r1 > r2 ? r1 : r2
  }

public func squarify(_ values: [Double], _ rect: PyreonChartRect) -> [PyreonChartRect] {
    var out: [PyreonChartRect] = []
    var total = 0.0
    for v in values {
      total = total + v
    }
    for i in 0..<values.count {
      out.append(PyreonChartRect(x: rect.x, y: rect.y, w: 0.0, h: 0.0))
    }
    if values.count == 0 || total <= 0.0 || rect.w <= 0.0 || rect.h <= 0.0 {
      return out
    }
    let areaScale = (rect.w * rect.h) / total
    var x = rect.x
    var y = rect.y
    var w = rect.w
    var h = rect.h
    var i = 0
    while i < values.count {
      var row: [Double] = []
      var rowIdx: [Int] = []
      var grow = true
      while grow && i < values.count {
        let v = values[i]
        let side = w >= h ? h : w
        if row.count > 0 {
          let before = worstRatio(row, side, areaScale)
          var candidate: [Double] = []
          for r in row {
            candidate.append(r)
          }
          candidate.append(v)
          let after = worstRatio(candidate, side, areaScale)
          if before >= 0.0 && after > before {
            grow = false
          }
        }
        if grow {
          row.append(v)
          rowIdx.append(i)
          i = i + 1
        }
      }
      var rowSum = 0.0
      for v in row {
        rowSum = rowSum + v * areaScale
      }
      let vertical = w >= h
      let side = vertical ? h : w
      let thick = side <= 0.0 ? 0.0 : Double(rowSum) / Double(side)
      var offset = 0.0
      for k in 0..<row.count {
        let a = row[k] * areaScale
        let len = thick <= 0.0 ? 0.0 : Double(a) / Double(thick)
        let target = rowIdx[k]
        if vertical {
          out[target] = PyreonChartRect(x: x, y: y + offset, w: thick, h: len)
        } else {
          out[target] = PyreonChartRect(x: x + offset, y: y, w: len, h: thick)
        }
        offset = offset + len
      }
      if vertical {
        x = x + thick
        w = w - thick
      } else {
        y = y + thick
        h = h - thick
      }
    }
    return out
  }

public func orderByValue(_ children: [TreeNode]) -> [Int] {
    var order: [Int] = []
    var vals: [Double] = []
    for i in 0..<children.count {
      order.append(i)
      vals.append(nodeValue(children[i]))
    }
    for i in 1..<order.count {
      let cur = order[i]
      let cv = vals[cur]
      var j = i - 1
      while j >= 0 {
        if vals[order[j]] >= cv {
          break
        }
        order[j + 1] = order[j]
        j = j - 1
      }
      order[j + 1] = cur
    }
    return order
  }

public func layoutTreemap(_ nodes: [TreeNode], _ rect: PyreonChartRect, _ options: TreemapOptions? = nil) -> [TreemapCell] {
    let palette = (options?.palette ?? DEFAULT_PALETTE)
    var cells: [TreemapCell] = []
    let padding = (options?.padding ?? 2.0)
    let maxDepth = (options?.maxDepth ?? 64.0)
    var stack: [TreemapFrame] = []
    stack.append(TreemapFrame(children: nodes, area: rect, depth: 0, path: [], inherited: "", hasInherited: false))
    var sp = 1
    while sp > 0 {
      sp = sp - 1
      let frame = stack[sp]
      var depthF = 0.0
      for d in 0..<frame.depth {
        depthF = depthF + 1.0
      }
      if depthF >= maxDepth || frame.children.count == 0 {
        continue
      }
      let order = orderByValue(frame.children)
      var values: [Double] = []
      for i in order {
        let v = nodeValue(frame.children[i])
        values.append(v < 0.0 ? 0.0 : v)
      }
      let rects = squarify(values, frame.area)
      var pushed: [TreemapFrame] = []
      for k in 0..<order.count {
        let idx = order[k]
        let node = frame.children[idx]
        let r = rects[k]
        let color = (node.color ?? (frame.hasInherited ? frame.inherited : paletteAt(palette, idx)))
        let kids = (node.children ?? [])
        var cellPath: [Int] = []
        for p in frame.path {
          cellPath.append(p)
        }
        cellPath.append(idx)
        cells.append(TreemapCell(name: node.name, value: values[k], rect: r, depth: frame.depth, path: cellPath, color: color, leaf: kids.count == 0))
        if kids.count > 0 {
          let innerW = r.w - padding * 2.0
          let innerH = r.h - padding * 2.0
          pushed.append(TreemapFrame(children: kids, area: PyreonChartRect(x: r.x + padding, y: r.y + padding, w: innerW < 0.0 ? 0.0 : innerW, h: innerH < 0.0 ? 0.0 : innerH), depth: frame.depth + 1, path: cellPath, inherited: color, hasInherited: true))
        }
      }
      var pk = pushed.count - 1
      while pk >= 0 {
        if sp < stack.count {
          stack[sp] = pushed[pk]
        } else {
          stack.append(pushed[pk])
        }
        sp = sp + 1
        pk = pk - 1
      }
    }
    return cells
  }

public func hexPair(_ hex: String, _ at: Int) -> Double {
    if hex.utf16.count < at + 2 {
      return 0.0
    }
    return hexDigit(Double(Array(hex.utf16)[Int(at)])) * 16.0 + hexDigit(Double(Array(hex.utf16)[Int(at + 1)]))
  }

public func tintHex(_ hex: String, _ t: Double) -> String {
    if hex.utf16.count < 7 {
      return hex
    }
    let r = ((Double(hexPair(hex, 1) + (255.0 - hexPair(hex, 1)) * t)) + 0.5).rounded(.down)
    let g = ((Double(hexPair(hex, 3) + (255.0 - hexPair(hex, 3)) * t)) + 0.5).rounded(.down)
    let b = ((Double(hexPair(hex, 5) + (255.0 - hexPair(hex, 5)) * t)) + 0.5).rounded(.down)
    return "rgb(\(r), \(g), \(b))"
  }

public func approxTextWidth(_ text: String, _ fontSize: Double) -> Double {
    var units = 0.0
    for i in 0..<text.utf16.count {
      let c = Double(Array(text.utf16)[Int(i)])
      if c >= 48.0 && c <= 57.0 {
        units = units + 0.9
      } else {
        if c == 46.0 || c == 44.0 || c == 32.0 {
          units = units + 0.45
        } else {
          units = units + 1.0
        }
      }
    }
    return units * fontSize * 0.52
  }

public func renderTreemap(_ cells: [TreemapCell], _ options: TreemapOptions? = nil, _ measure: ((String, Double) -> Double)? = nil) -> [PyreonDrawCmd] {
    var out: [PyreonDrawCmd] = []
    let rawP = (options?.progress ?? 1.0)
    let progress = rawP < 0.0 ? 0.0 : rawP > 1.0 ? 1.0 : rawP
    let showLabels = (options?.showLabels ?? true)
    let fontSize = (options?.fontSize ?? 11.0)
    let labelColor = (options?.labelColor ?? "#ffffff")
    let m = (measure ?? approxTextWidth)
    for c in cells {
      let w = c.rect.w * progress
      let h = c.rect.h * progress
      let x = c.rect.x + Double((c.rect.w - w)) / 2.0
      let y = c.rect.y + Double((c.rect.h - h)) / 2.0
      var depthF = 0.0
      for d in 0..<c.depth {
        depthF = depthF + 1.0
      }
      let tintT = 0.35 + depthF * 0.15
      out.append(PyreonDrawCmd(kind: "rect", rect: PyreonChartRect(x: x, y: y, w: w, h: h), fill: c.leaf ? c.color : tintHex(c.color, tintT > 0.6 ? 0.6 : tintT)))
      if showLabels && progress >= 1.0 && c.leaf {
        let tw = m(c.name, fontSize)
        if tw + 8.0 <= c.rect.w && fontSize + 6.0 <= c.rect.h {
          out.append(PyreonDrawCmd(kind: "text", fill: labelColor, text: c.name, at: PyreonChartPt(x: c.rect.x + 4.0, y: c.rect.y + 4.0), size: fontSize, align: "start", baseline: "top"))
        }
      }
    }
    return out
  }

public func hitTreemapIndex(_ cells: [TreemapCell], _ px: Double, _ py: Double) -> Int {
    var bestIdx = -1
    var bestDepth = -1
    for i in 0..<cells.count {
      let c = cells[i]
      let r = c.rect
      if px < r.x || px > r.x + r.w || py < r.y || py > r.y + r.h {
        continue
      }
      if c.depth > bestDepth {
        bestDepth = c.depth
        bestIdx = i
      }
    }
    return bestIdx
  }

public func hitTreemap(_ cells: [TreemapCell], _ px: Double, _ py: Double) -> TreemapCell? {
    let i = hitTreemapIndex(cells, px, py)
    return i < 0 ? nil : cells[i]
  }

public func treeDepth(_ nodes: [TreeNode]) -> Int {
    var deepest = 0
    var stack: [TreeNode] = []
    var depths: [Int] = []
    var sp = 0
    for n in nodes {
      stack.append(n)
      depths.append(1)
      sp = sp + 1
    }
    while sp > 0 {
      sp = sp - 1
      let cur = stack[sp]
      let d = depths[sp]
      if d > deepest {
        deepest = d
      }
      for c in (cur.children ?? []) {
        if sp < stack.count {
          stack[sp] = c
          depths[sp] = d + 1
        } else {
          stack.append(c)
          depths.append(d + 1)
        }
        sp = sp + 1
      }
    }
    return deepest
  }

public func layoutSunburst(_ nodes: [TreeNode], _ innerR: Double, _ outerR: Double, _ options: SunburstOptions? = nil) -> [SunburstArc] {
    let palette = (options?.palette ?? DEFAULT_PALETTE)
    var arcs: [SunburstArc] = []
    let rawLevels = treeDepth(nodes)
    let maxDepth = (options?.maxDepth ?? 64.0)
    var levelsF = 0.0
    for i in 0..<rawLevels {
      levelsF = levelsF + 1.0
    }
    if levelsF > maxDepth {
      levelsF = maxDepth
    }
    if levelsF <= 0.0 {
      return arcs
    }
    let ringW = (outerR - innerR) / levelsF
    let pad = (options?.padAngle ?? 0.0)
    let sortMode = (options?.sort ?? "desc")
    let startAngle = (options?.startAngle ?? -Double.pi / 2.0)
    var stack: [SunburstFrame] = []
    stack.append(SunburstFrame(children: nodes, a0: startAngle, a1: startAngle + SUNBURST_TAU, depth: 0, path: [], inherited: "", hasInherited: false))
    var sp = 1
    while sp > 0 {
      sp = sp - 1
      let frame = stack[sp]
      var depthF = 0.0
      for d in 0..<frame.depth {
        depthF = depthF + 1.0
      }
      if depthF >= levelsF || frame.children.count == 0 {
        continue
      }
      var order: [Int] = []
      if sortMode == "desc" {
        for i in orderByValue(frame.children) {
          order.append(i)
        }
      } else {
        for i in 0..<frame.children.count {
          order.append(i)
        }
      }
      var total = 0.0
      var count = 0.0
      for i in order {
        let v = nodeValue(frame.children[i])
        total = total + (v < 0.0 ? 0.0 : v)
        count = count + 1.0
      }
      let usable = frame.a1 - frame.a0 - pad * (count - 1.0)
      var cursor = frame.a0
      var pushed: [SunburstFrame] = []
      for idx in order {
        let node = frame.children[idx]
        let raw = nodeValue(node)
        let v = raw < 0.0 ? 0.0 : raw
        let span = total <= 0.0 || usable <= 0.0 ? 0.0 : usable * (Double(v) / Double(total))
        let color = (node.color ?? (frame.hasInherited ? frame.inherited : paletteAt(palette, idx)))
        let kids = (node.children ?? [])
        var cellPath: [Int] = []
        for p in frame.path {
          cellPath.append(p)
        }
        cellPath.append(idx)
        let r0 = innerR + ringW * depthF
        arcs.append(SunburstArc(name: node.name, value: v, depth: frame.depth, path: cellPath, start: cursor, end: cursor + span, innerR: r0, outerR: r0 + ringW, color: color, leaf: kids.count == 0))
        if kids.count > 0 {
          pushed.append(SunburstFrame(children: kids, a0: cursor, a1: cursor + span, depth: frame.depth + 1, path: cellPath, inherited: color, hasInherited: true))
        }
        cursor = cursor + span + pad
      }
      var pk = pushed.count - 1
      while pk >= 0 {
        if sp < stack.count {
          stack[sp] = pushed[pk]
        } else {
          stack.append(pushed[pk])
        }
        sp = sp + 1
        pk = pk - 1
      }
    }
    return arcs
  }

public func renderSunburst(_ arcs: [SunburstArc], _ center: PyreonChartPt, _ options: SunburstOptions? = nil, _ measure: ((String, Double) -> Double)? = nil) -> [PyreonDrawCmd] {
    var out: [PyreonDrawCmd] = []
    let rawP = (options?.progress ?? 1.0)
    let progress = rawP < 0.0 ? 0.0 : rawP > 1.0 ? 1.0 : rawP
    let startAngle = (options?.startAngle ?? -Double.pi / 2.0)
    let limit = startAngle + SUNBURST_TAU * progress
    let showLabels = (options?.showLabels ?? true)
    let fontSize = (options?.fontSize ?? 11.0)
    let labelColor = (options?.labelColor ?? "#ffffff")
    let m = (measure ?? approxTextWidth)
    for a in arcs {
      if a.start >= limit || a.end <= a.start {
        continue
      }
      let end = a.end < limit ? a.end : limit
      var depthF = 0.0
      for d in 0..<a.depth {
        depthF = depthF + 1.0
      }
      let tintT = 0.2 + depthF * 0.15
      let fill = a.leaf ? a.color : tintHex(a.color, tintT > 0.5 ? 0.5 : tintT)
      out.append(PyreonDrawCmd(kind: "polygon", fill: fill, points: arcPolygon(center, a.outerR, a.innerR, a.start, end)))
      if showLabels && progress >= 1.0 {
        let midR = Double((a.innerR + a.outerR)) / 2.0
        let chord = midR * (a.end - a.start)
        let tw = m(a.name, fontSize)
        if chord >= tw + 4.0 && a.outerR - a.innerR >= fontSize + 4.0 {
          let mid = Double((a.start + a.end)) / 2.0
          out.append(PyreonDrawCmd(kind: "text", fill: labelColor, text: a.name, at: PyreonChartPt(x: center.x + cos(Double(mid)) * midR, y: center.y + sin(Double(mid)) * midR), size: fontSize, align: "middle", baseline: "middle"))
        }
      }
    }
    return out
  }

public func hitSunburstIndex(_ arcs: [SunburstArc], _ center: PyreonChartPt, _ px: Double, _ py: Double) -> Int {
    let dx = px - center.x
    let dy = py - center.y
    let dist = sqrt(Double(dx * dx + dy * dy))
    let ang = atan2(Double(dy), Double(dx))
    var bestIdx = -1
    var bestDepth = -1
    for i in 0..<arcs.count {
      let a = arcs[i]
      if dist < a.innerR || dist > a.outerR {
        continue
      }
      var t = ang
      while t < a.start {
        t = t + SUNBURST_TAU
      }
      while t >= a.start + SUNBURST_TAU {
        t = t - SUNBURST_TAU
      }
      if t > a.end {
        continue
      }
      if a.depth > bestDepth {
        bestDepth = a.depth
        bestIdx = i
      }
    }
    return bestIdx
  }

public func hitSunburst(_ arcs: [SunburstArc], _ center: PyreonChartPt, _ px: Double, _ py: Double) -> SunburstArc? {
    let i = hitSunburstIndex(arcs, center, px, py)
    return i < 0 ? nil : arcs[i]
  }

public func placeTreeNode(_ orient: String, _ box: PyreonChartRect, _ gutter: Double, _ levelsF: Double, _ slotsF: Double, _ depthF: Double, _ t: Double) -> Placed {
    let depthFrac = levelsF <= 1.0 ? 0.0 : depthF / (levelsF - 1.0)
    let slotFrac = slotsF <= 1.0 ? 0.5 : t / (slotsF - 1.0)
    if orient == "radial" {
      let cx = box.x + box.w / 2.0
      let cy = box.y + box.h / 2.0
      let side = box.w < box.h ? box.w : box.h
      let rawR = Double(side) / 2.0 - gutter
      let bigR = rawR < 0.0 ? 0.0 : rawR
      let ang = -Double.pi / 2.0 + (slotsF <= 0.0 ? 0.0 : (t / slotsF) * TREE_TAU)
      let r = bigR * depthFrac
      let dir = depthF == 0.0 ? PyreonChartPt(x: 1.0, y: 0.0) : PyreonChartPt(x: cos(Double(ang)), y: sin(Double(ang)))
      return Placed(at: PyreonChartPt(x: cx + cos(Double(ang)) * r, y: cy + sin(Double(ang)) * r), dir: dir)
    }
    let x0 = box.x + gutter / 2.0
    let y0 = box.y + gutter / 4.0
    let rawW = box.w - gutter
    let w = rawW < 0.0 ? 0.0 : rawW
    let rawH = box.h - gutter / 2.0
    let hgt = rawH < 0.0 ? 0.0 : rawH
    if orient == "LR" {
      return Placed(at: PyreonChartPt(x: x0 + w * depthFrac, y: y0 + hgt * slotFrac), dir: PyreonChartPt(x: 1.0, y: 0.0))
    }
    if orient == "RL" {
      return Placed(at: PyreonChartPt(x: x0 + w * (1.0 - depthFrac), y: y0 + hgt * slotFrac), dir: PyreonChartPt(x: -1.0, y: 0.0))
    }
    if orient == "TB" {
      return Placed(at: PyreonChartPt(x: x0 + w * slotFrac, y: y0 + hgt * depthFrac), dir: PyreonChartPt(x: 0.0, y: 1.0))
    }
    return Placed(at: PyreonChartPt(x: x0 + w * slotFrac, y: y0 + hgt * (1.0 - depthFrac)), dir: PyreonChartPt(x: 0.0, y: -1.0))
  }

public func layoutTree(_ roots: [TreeNode], _ box: PyreonChartRect, _ options: TreeOptions? = nil) -> TreeLayout {
    let palette = (options?.palette ?? DEFAULT_PALETTE)
    let orient = (options?.orient ?? "LR")
    let maxDepth = (options?.maxDepth ?? 64.0)
    let gutter = (options?.labelGutter ?? 60.0)
    var stack: [TreeFrame] = []
    var sp = 0
    var ri = roots.count - 1
    while ri >= 0 {
      let root = roots[ri]
      stack.append(TreeFrame(node: root, depth: 0, path: [ri], color: (root.color ?? paletteAt(palette, ri)), parent: -1))
      sp = sp + 1
      ri = ri - 1
    }
    var frames: [TreeFrame] = []
    var leafFlags: [Bool] = []
    var levelsF = 0.0
    while sp > 0 {
      sp = sp - 1
      let frame = stack[sp]
      var depthF = 0.0
      for d in 0..<frame.depth {
        depthF = depthF + 1.0
      }
      if depthF + 1.0 > levelsF {
        levelsF = depthF + 1.0
      }
      var kids: [TreeNode] = []
      if depthF + 1.0 < maxDepth {
        for k in (frame.node.children ?? []) {
          kids.append(k)
        }
      }
      let index = frames.count
      frames.append(frame)
      leafFlags.append(kids.count == 0)
      var ki = kids.count - 1
      while ki >= 0 {
        let kid = kids[ki]
        var childPath: [Int] = []
        for p in frame.path {
          childPath.append(p)
        }
        childPath.append(ki)
        let next = TreeFrame(node: kid, depth: frame.depth + 1, path: childPath, color: (kid.color ?? frame.color), parent: index)
        if sp < stack.count {
          stack[sp] = next
        } else {
          stack.append(next)
        }
        sp = sp + 1
        ki = ki - 1
      }
    }
    var lo: [Double] = []
    var hi: [Double] = []
    var nextSlot = 0.0
    for i in 0..<frames.count {
      if leafFlags[i] {
        lo.append(nextSlot)
        hi.append(nextSlot)
        nextSlot = nextSlot + 1.0
      } else {
        lo.append(-1.0)
        hi.append(-1.0)
      }
    }
    var bi = frames.count - 1
    while bi >= 0 {
      let parent = frames[bi].parent
      if parent >= 0 {
        if lo[parent] < 0.0 || lo[bi] < lo[parent] {
          lo[parent] = lo[bi]
        }
        if hi[parent] < 0.0 || hi[bi] > hi[parent] {
          hi[parent] = hi[bi]
        }
      }
      bi = bi - 1
    }
    let slotsF = nextSlot
    var nodes: [TreeLayoutNode] = []
    var links: [TreeLink] = []
    for i in 0..<frames.count {
      let f = frames[i]
      var depthF = 0.0
      for d in 0..<f.depth {
        depthF = depthF + 1.0
      }
      let t = (lo[i] + hi[i]) / 2.0
      let p = placeTreeNode(orient, box, gutter, levelsF, slotsF, depthF, t)
      nodes.append(TreeLayoutNode(name: f.node.name, value: f.node.value, at: p.at, depth: f.depth, path: f.path, color: f.color, leaf: leafFlags[i], dir: p.dir))
    }
    for i in 0..<frames.count {
      let f = frames[i]
      if f.parent < 0 {
        continue
      }
      links.append(TreeLink(from: nodes[f.parent].at, to: nodes[i].at, path: f.path, depth: f.depth))
    }
    return TreeLayout(nodes: nodes, links: links)
  }

public func linkPoints(_ link: TreeLink, _ orient: String, _ shape: String) -> [PyreonChartPt] {
    let a = link.from
    let b = link.to
    if orient == "radial" {
      return [a, b]
    }
    let horizontal = orient == "LR" || orient == "RL"
    if shape == "elbow" {
      if horizontal {
        return [a, PyreonChartPt(x: (a.x + b.x) / 2.0, y: a.y), PyreonChartPt(x: (a.x + b.x) / 2.0, y: b.y), b]
      }
      return [a, PyreonChartPt(x: a.x, y: (a.y + b.y) / 2.0), PyreonChartPt(x: b.x, y: (a.y + b.y) / 2.0), b]
    }
    var pts: [PyreonChartPt] = []
    var iF = 0.0
    for i in 0...12 {
      let t = iF / 12.0
      let e = t * t * (3.0 - 2.0 * t)
      if horizontal {
        pts.append(PyreonChartPt(x: a.x + (b.x - a.x) * t, y: a.y + (b.y - a.y) * e))
      } else {
        pts.append(PyreonChartPt(x: a.x + (b.x - a.x) * e, y: a.y + (b.y - a.y) * t))
      }
      iF = iF + 1.0
    }
    return pts
  }

public func renderTree(_ layout: TreeLayout, _ options: TreeOptions? = nil) -> [PyreonDrawCmd] {
    var out: [PyreonDrawCmd] = []
    let orient = (options?.orient ?? "LR")
    let shape = (options?.edgeShape ?? "curve")
    let rawP = (options?.progress ?? 1.0)
    let progress = rawP < 0.0 ? 0.0 : rawP > 1.0 ? 1.0 : rawP
    var levelsF = 0.0
    for n in layout.nodes {
      var depthF = 0.0
      for d in 0..<n.depth {
        depthF = depthF + 1.0
      }
      if depthF + 1.0 > levelsF {
        levelsF = depthF + 1.0
      }
    }
    var shownF = 0.0
    if progress >= 1.0 {
      shownF = levelsF
    } else {
      while shownF + 1.0 <= levelsF * progress {
        shownF = shownF + 1.0
      }
    }
    let size = (options?.symbolSize ?? 8.0)
    let linkColor = (options?.linkColor ?? "#94a3b8")
    let showLabels = (options?.showLabels ?? true)
    let fontSize = (options?.fontSize ?? 11.0)
    let labelColor = (options?.labelColor ?? "#334155")
    for l in layout.links {
      var depthF = 0.0
      for d in 0..<l.depth {
        depthF = depthF + 1.0
      }
      if depthF >= shownF {
        continue
      }
      out.append(PyreonDrawCmd(kind: "polyline", stroke: linkColor, width: 1.0, points: linkPoints(l, orient, shape)))
    }
    for n in layout.nodes {
      var depthF = 0.0
      for d in 0..<n.depth {
        depthF = depthF + 1.0
      }
      if depthF >= shownF {
        continue
      }
      out.append(PyreonDrawCmd(kind: "circle", fill: n.color, center: n.at, radius: size / 2.0))
      if !showLabels || progress < 1.0 {
        continue
      }
      let sx = n.leaf ? n.dir.x : -n.dir.x
      let sy = n.leaf ? n.dir.y : -n.dir.y
      let off = size / 2.0 + 4.0
      out.append(PyreonDrawCmd(kind: "text", fill: labelColor, text: n.name, at: PyreonChartPt(x: n.at.x + sx * off, y: n.at.y + sy * off), size: fontSize, align: sx > 0.3 ? "start" : sx < -0.3 ? "end" : "middle", baseline: sy > 0.3 ? "top" : sy < -0.3 ? "bottom" : "middle"))
    }
    return out
  }

public func hitTreeIndex(_ layout: TreeLayout, _ px: Double, _ py: Double, _ symbolSize: Double? = nil) -> Int {
    let r = ((symbolSize ?? 8.0)) / 2.0 + 4.0
    var bestIdx = -1
    var bestD = r * r
    for i in 0..<layout.nodes.count {
      let n = layout.nodes[i]
      let dx = px - n.at.x
      let dy = py - n.at.y
      let d = dx * dx + dy * dy
      if d <= bestD {
        bestIdx = i
        bestD = d
      }
    }
    return bestIdx
  }

public func hitTree(_ layout: TreeLayout, _ px: Double, _ py: Double, _ symbolSize: Double? = nil) -> TreeLayoutNode? {
    let i = hitTreeIndex(layout, px, py, symbolSize)
    return i < 0 ? nil : layout.nodes[i]
  }

public func riverValue(_ s: RiverSeries, _ i: Int) -> Double {
    if i >= s.values.count {
      return 0.0
    }
    let v = s.values[i]
    if !isFiniteNumber(v) {
      return 0.0
    }
    return v < 0.0 ? 0.0 : v
  }

public func layoutRiver(_ series: [RiverSeries], _ box: PyreonChartRect, _ options: RiverOptions? = nil) -> RiverLayout {
    let palette = (options?.palette ?? DEFAULT_PALETTE)
    let fontSize = (options?.fontSize ?? 11.0)
    let showAxis = options?.showAxis != false
    let rawH = box.h - (showAxis ? fontSize * 1.8 : 0.0)
    let plot = PyreonChartRect(x: box.x, y: box.y, w: box.w, h: rawH < 0.0 ? 0.0 : rawH)
    var n = 0
    for s in series {
      if s.values.count > n {
        n = s.values.count
      }
    }
    let cats = (options?.categories ?? [])
    if cats.count > n {
      n = cats.count
    }
    var nF = 0.0
    for i in 0..<n {
      nF = nF + 1.0
    }
    var xs: [Double] = []
    var iF = 0.0
    for i in 0..<n {
      xs.append(nF <= 1.0 ? plot.x + plot.w / 2.0 : plot.x + (plot.w * iF) / (nF - 1.0))
      iF = iF + 1.0
    }
    var totals: [Double] = []
    for i in 0..<n {
      var t = 0.0
      for s in series {
        t = t + riverValue(s, i)
      }
      totals.append(t)
    }
    let zeroBase = options?.baseline == "zero"
    var base: [Double] = []
    for t in totals {
      base.append(zeroBase ? 0.0 : Double(-t) / 2.0)
    }
    var lo = 0.0
    var hi = 1.0
    var seen = false
    for i in 0..<n {
      let b = base[i]
      var top = b + totals[i]
      if !seen || b < lo {
        lo = b
      }
      if !seen || top > hi {
        hi = top
      }
      seen = true
    }
    if hi <= lo {
      hi = lo + 1.0
    }
    var layers: [RiverLayer] = []
    var cursor: [Double] = []
    for b in base {
      cursor.append(b)
    }
    for si in 0..<series.count {
      let s = series[si]
      var top: [PyreonChartPt] = []
      var bottom: [PyreonChartPt] = []
      var widest = 0.0
      var widestAt = 0
      for i in 0..<n {
        let v = riverValue(s, i)
        let b = cursor[i]
        bottom.append(PyreonChartPt(x: xs[i], y: plot.y + plot.h - ((b - lo) / (hi - lo)) * plot.h))
        top.append(PyreonChartPt(x: xs[i], y: plot.y + plot.h - ((b + v - lo) / (hi - lo)) * plot.h))
        if v > widest {
          widest = v
          widestAt = i
        }
        cursor[i] = b + v
      }
      let hasPts = n > 0
      let midX = hasPts ? xs[widestAt] : plot.x
      let midY = hasPts ? Double(top[widestAt].y) / 2.0 + Double(bottom[widestAt].y) / 2.0 : plot.y
      let thickness = hasPts && widest > 0.0 ? bottom[widestAt].y - top[widestAt].y : 0.0
      layers.append(RiverLayer(series: si, name: s.name, color: (s.color ?? paletteAt(palette, si)), top: top, bottom: bottom, labelAt: PyreonChartPt(x: midX, y: midY), thickness: thickness))
    }
    var ticks: [RiverTick] = []
    if showAxis && n > 0 {
      var every = 1
      while every * 8 < n {
        every = every + 1
      }
      var ti = 0
      while ti < n {
        ticks.append(RiverTick(x: xs[ti], label: ti < cats.count ? cats[ti] : "\(ti + 1)"))
        ti = ti + every
      }
    }
    return RiverLayout(layers: layers, xs: xs, ticks: ticks, plot: plot)
  }

public func smoothPoints(_ pts: [PyreonChartPt]) -> [PyreonChartPt] {
    var out: [PyreonChartPt] = []
    if pts.count < 3 {
      for p in pts {
        out.append(p)
      }
      return out
    }
    out.append(pts[0])
    for i in 0..<pts.count - 1 {
      let p1 = pts[i]
      let p2 = pts[i + 1]
      let p0 = i > 0 ? pts[i - 1] : p1
      let p3 = i + 2 < pts.count ? pts[i + 2] : p2
      var kf = 1.0
      for k in 1...8 {
        let t = Double(kf) / 8.0
        let t2 = t * t
        let t3 = t2 * t
        let x = 0.5 * (2.0 * p1.x + Double((-p0.x + p2.x) * t) + (2.0 * p0.x - 5.0 * p1.x + 4.0 * p2.x - p3.x) * t2 + (Double(-p0.x) + 3.0 * p1.x - 3.0 * p2.x + p3.x) * t3)
        let y = 0.5 * (2.0 * p1.y + Double((-p0.y + p2.y) * t) + (2.0 * p0.y - 5.0 * p1.y + 4.0 * p2.y - p3.y) * t2 + (Double(-p0.y) + 3.0 * p1.y - 3.0 * p2.y + p3.y) * t3)
        out.append(PyreonChartPt(x: x, y: y))
        kf = kf + 1.0
      }
    }
    return out
  }

public func layerPolygon(_ layer: RiverLayer, _ curve: String, _ progress: Double) -> [PyreonChartPt] {
    var lenF = 0.0
    for i in 0..<layer.top.count {
      lenF = lenF + 1.0
    }
    var countF = 0.0
    if progress >= 1.0 {
      countF = lenF
    } else {
      while countF + 1.0 <= lenF * progress {
        countF = countF + 1.0
      }
      if countF < 2.0 {
        countF = 2.0
      }
    }
    var topCut: [PyreonChartPt] = []
    var bottomCut: [PyreonChartPt] = []
    var iF = 0.0
    for i in 0..<layer.top.count {
      if iF >= countF {
        break
      }
      topCut.append(layer.top[i])
      if i < layer.bottom.count {
        bottomCut.append(layer.bottom[i])
      }
      iF = iF + 1.0
    }
    let top = curve == "smooth" ? smoothPoints(topCut) : topCut
    let bottom = curve == "smooth" ? smoothPoints(bottomCut) : bottomCut
    var out: [PyreonChartPt] = []
    for p in top {
      out.append(p)
    }
    var bi = bottom.count - 1
    while bi >= 0 {
      out.append(bottom[bi])
      bi = bi - 1
    }
    return out
  }

public func renderRiver(_ layout: RiverLayout, _ options: RiverOptions? = nil, _ measure: ((String, Double) -> Double)? = nil) -> [PyreonDrawCmd] {
    var out: [PyreonDrawCmd] = []
    let curve = (options?.curve ?? "smooth")
    let rawP = (options?.progress ?? 1.0)
    let progress = rawP < 0.0 ? 0.0 : rawP > 1.0 ? 1.0 : rawP
    let fontSize = (options?.fontSize ?? 11.0)
    let labelColor = (options?.labelColor ?? "#ffffff")
    let axisColor = (options?.axisColor ?? "#94a3b8")
    let tickColor = (options?.tickColor ?? "#64748b")
    let m = (measure ?? approxTextWidth)
    if progress <= 0.0 || layout.xs.count < 2 {
      return out
    }
    for l in layout.layers {
      if l.thickness <= 0.0 {
        continue
      }
      out.append(PyreonDrawCmd(kind: "polygon", fill: l.color, points: layerPolygon(l, curve, progress)))
    }
    if progress < 1.0 {
      return out
    }
    if options?.showAxis != false && layout.ticks.count > 0 {
      let y = layout.plot.y + layout.plot.h
      out.append(PyreonDrawCmd(kind: "line", from: PyreonChartPt(x: layout.plot.x, y: y), to: PyreonChartPt(x: layout.plot.x + layout.plot.w, y: y), stroke: axisColor, width: 1.0))
      for t in layout.ticks {
        out.append(PyreonDrawCmd(kind: "text", fill: tickColor, text: t.label, at: PyreonChartPt(x: t.x, y: y + 4.0), size: fontSize, align: "middle", baseline: "top"))
      }
    }
    if options?.showLabels != false {
      for l in layout.layers {
        if l.thickness < fontSize + 2.0 {
          continue
        }
        if m(l.name, fontSize) > layout.plot.w / 3.0 {
          continue
        }
        out.append(PyreonDrawCmd(kind: "text", fill: labelColor, text: l.name, at: l.labelAt, size: fontSize, align: "middle", baseline: "middle"))
      }
    }
    return out
  }

public func riverPointInPolygon(_ pts: [PyreonChartPt], _ px: Double, _ py: Double) -> Bool {
    var inside = false
    var j = pts.count - 1
    for i in 0..<pts.count {
      let a = pts[i]
      let b = pts[j]
      let aAbove = a.y > py
      let bAbove = b.y > py
      if aAbove != bAbove && px < ((b.x - a.x) * (py - a.y)) / Double((b.y - a.y)) + a.x {
        inside = !inside
      }
      j = i
    }
    return inside
  }

public func hitRiverIndex(_ layout: RiverLayout, _ px: Double, _ py: Double, _ curve: String? = nil) -> Int {
    let shape = (curve ?? "smooth")
    var bestIdx = -1
    for i in stride(from: layout.layers.count - 1, through: 0, by: -1) {
      if bestIdx >= 0 {
        continue
      }
      let l = layout.layers[i]
      if l.thickness > 0.0 && riverPointInPolygon(layerPolygon(l, shape, 1.0), px, py) {
        bestIdx = i
      }
    }
    return bestIdx
  }

public func hitRiver(_ layout: RiverLayout, _ px: Double, _ py: Double, _ curve: String? = nil) -> RiverLayer? {
    let i = hitRiverIndex(layout, px, py, curve)
    return i < 0 ? nil : layout.layers[i]
  }

public func indexOfName(_ names: [String], _ name: String) -> Int {
    for i in 0..<names.count {
      if names[i] == name {
        return i
      }
    }
    return -1
  }

public func layoutChord(_ nodes: [ChordNode], _ links: [ChordLink], _ box: PyreonChartRect, _ options: ChordOptions? = nil, _ measure: ((String, Double) -> Double)? = nil) -> ChordLayout {
    let palette = (options?.palette ?? DEFAULT_PALETTE)
    let padAngle = (options?.padAngle ?? 0.04)
    let ringRatio = (options?.ringRatio ?? 0.08)
    let fontSize = (options?.fontSize ?? 11.0)
    let m = (measure ?? approxTextWidth)
    var names: [String] = []
    for n in nodes {
      names.append(n.name)
    }
    var totals: [Double] = []
    for i in 0..<names.count {
      totals.append(0.0)
    }
    var valid: [ChordLink] = []
    for l in links {
      let s = indexOfName(names, l.source)
      let t = indexOfName(names, l.target)
      if s < 0 || t < 0 {
        continue
      }
      if !isFiniteNumber(l.value) || l.value <= 0.0 {
        continue
      }
      valid.append(l)
      totals[s] = totals[s] + l.value
      totals[t] = totals[t] + l.value
    }
    var grand = 0.0
    for t in totals {
      grand = grand + t
    }
    var widest = 0.0
    if options?.showLabels != false {
      for n in names {
        let w = m(n, fontSize)
        if w > widest {
          widest = w
        }
      }
    }
    let outer = fitCircle(box)
    let radius = max(8.0, outer.radius - widest - 8.0)
    let circle = Circle(center: outer.center, radius: radius)
    let thickness = max(3.0, radius * ringRatio)
    var arcs: [ChordArc] = []
    var ribbons: [ChordRibbon] = []
    if grand <= 0.0 || names.count == 0 {
      return ChordLayout(arcs: arcs, ribbons: ribbons, circle: circle, thickness: thickness, box: box)
    }
    let gaps = padAngle * Double(names.count)
    let usable = max(0.0, CHORD_TAU - gaps)
    var angle = -Double.pi / 2.0
    var starts: [Double] = []
    var cursors: [Double] = []
    for i in 0..<names.count {
      let span = (totals[i] / grand) * usable
      let start = angle
      let end = angle + span
      let mid = Double((start + end)) / 2.0
      let labelR = radius + 6.0
      let at = pointOnCircle(circle.center, labelR, mid)
      let cosMid = cos(Double(mid))
      arcs.append(ChordArc(index: i, name: names[i], color: (nodes[i].color ?? paletteAt(palette, i)), start: start, end: end, total: totals[i], labelAt: at, labelAlign: cosMid >= 0.0 ? "start" : "end"))
      starts.append(start)
      cursors.append(start)
      angle = end + padAngle
    }
    for k in 0..<valid.count {
      let l = valid[k]
      let s = indexOfName(names, l.source)
      let t = indexOfName(names, l.target)
      let span = (Double(l.value) / grand) * usable
      let sStart = cursors[s]
      let sEnd = sStart + span
      cursors[s] = sEnd
      let tStart = cursors[t]
      let tEnd = tStart + span
      cursors[t] = tEnd
      ribbons.append(ChordRibbon(link: k, source: s, target: t, value: l.value, color: arcs[s].color, sourceStart: sStart, sourceEnd: sEnd, targetStart: tStart, targetEnd: tEnd))
    }
    return ChordLayout(arcs: arcs, ribbons: ribbons, circle: circle, thickness: thickness, box: box)
  }

public func ribbonPolygon(_ layout: ChordLayout, _ r: ChordRibbon, _ progress: Double) -> [PyreonChartPt] {
    let c = layout.circle.center
    let inner = max(0.0, layout.circle.radius - layout.thickness)
    let p = progress < 0.0 ? 0.0 : progress > 1.0 ? 1.0 : progress
    var pts: [PyreonChartPt] = []
    let sSweep = r.sourceEnd - r.sourceStart
    let sSteps = max(2, ceil(Double((abs(sSweep) / Double(CHORD_TAU)) * 64.0)))
    for i in 0...Int(ceil(Double(sSteps))) {
      pts.append(pointOnCircle(c, inner, r.sourceStart + (sSweep * Double(i)) / sSteps))
    }
    let a = pointOnCircle(c, inner, r.sourceEnd)
    let b = pointOnCircle(c, inner, r.targetStart)
    for q in quadPoints(a, c, b, p) {
      pts.append(q)
    }
    let tSweep = r.targetEnd - r.targetStart
    let tSteps = max(2, ceil(Double((abs(tSweep) / Double(CHORD_TAU)) * 64.0)))
    for i in 0...Int(ceil(Double(tSteps))) {
      pts.append(pointOnCircle(c, inner, r.targetStart + (tSweep * Double(i)) / tSteps))
    }
    let a2 = pointOnCircle(c, inner, r.targetEnd)
    let b2 = pointOnCircle(c, inner, r.sourceStart)
    for q in quadPoints(a2, c, b2, p) {
      pts.append(q)
    }
    return pts
  }

public func quadPoints(_ from: PyreonChartPt, _ control: PyreonChartPt, _ to: PyreonChartPt, _ progress: Double) -> [PyreonChartPt] {
    var out: [PyreonChartPt] = []
    let steps = 24
    let mx = (from.x + to.x) / 2.0
    let my = (from.y + to.y) / 2.0
    let cx = mx + (control.x - mx) * progress
    let cy = my + (control.y - my) * progress
    for i in 1...steps {
      let t = Double(i) / Double(steps)
      let u = 1.0 - t
      let x = u * u * from.x + 2.0 * u * t * cx + t * t * to.x
      let y = u * u * from.y + 2.0 * u * t * cy + t * t * to.y
      out.append(PyreonChartPt(x: x, y: y))
    }
    return out
  }

public func renderChord(_ layout: ChordLayout, _ options: ChordOptions? = nil, _ measure: ((String, Double) -> Double)? = nil) -> [PyreonDrawCmd] {
    var out: [PyreonDrawCmd] = []
    let rawP = (options?.progress ?? 1.0)
    let progress = rawP < 0.0 ? 0.0 : rawP > 1.0 ? 1.0 : rawP
    let opacity = (options?.linkOpacity ?? 0.62)
    let fontSize = (options?.fontSize ?? 11.0)
    let labelColor = (options?.labelColor ?? "#5a6b7a")
    let m = (measure ?? approxTextWidth)
    if progress <= 0.0 || layout.arcs.count == 0 {
      return out
    }
    for r in layout.ribbons {
      out.append(PyreonDrawCmd(kind: "polygon", fill: withAlpha(r.color, opacity), points: ribbonPolygon(layout, r, progress)))
    }
    let c = layout.circle.center
    let inner = max(0.0, layout.circle.radius - layout.thickness)
    for a in layout.arcs {
      out.append(PyreonDrawCmd(kind: "polygon", fill: a.color, points: arcPolygon(c, layout.circle.radius, inner, a.start, a.end)))
    }
    if options?.showLabels != false {
      for a in layout.arcs {
        if m(a.name, fontSize) > layout.box.w / 2.0 {
          continue
        }
        out.append(PyreonDrawCmd(kind: "text", fill: labelColor, text: a.name, at: a.labelAt, size: fontSize, align: a.labelAlign, baseline: "middle"))
      }
    }
    return out
  }

public func hitChordIndex(_ layout: ChordLayout, _ px: Double, _ py: Double) -> Int {
    let dx = px - layout.circle.center.x
    let dy = py - layout.circle.center.y
    let dist = sqrt(Double(dx * dx + dy * dy))
    let inner = max(0.0, layout.circle.radius - layout.thickness)
    if dist < inner || dist > layout.circle.radius {
      return -1
    }
    let raw = atan2(Double(dy), Double(dx))
    let wrapped = raw + CHORD_TAU
    for a in layout.arcs {
      if raw >= a.start && raw <= a.end {
        return a.index
      }
      if wrapped >= a.start && wrapped <= a.end {
        return a.index
      }
    }
    return -1
  }

public func polarFrac(_ v: Double, _ lo: Double, _ hi: Double) -> Double {
    let span = hi - lo
    let t = span <= 0.0 ? 0.0 : (v - lo) / span
    return t < 0.0 ? 0.0 : t > 1.0 ? 1.0 : t
  }

public func polarTicks(_ lo: Double, _ hi: Double) -> [Double] {
    var out: [Double] = []
    if hi <= lo {
      out.append(lo)
      return out
    }
    let raw = (hi - lo) / 3.0
    var mag = 1.0
    while mag * 10.0 <= raw {
      mag = mag * 10.0
    }
    while mag > raw {
      mag = mag / 10.0
    }
    let norm = raw / mag
    let step = (norm >= 5.0 ? 5.0 : norm >= 2.0 ? 2.0 : 1.0) * mag
    var v = 0.0
    while v < lo {
      v = v + step
    }
    while v - step >= lo {
      v = v - step
    }
    var `guard` = 0
    while v <= hi + 1e-9 && `guard` < 1000 {
      out.append(((Double(v * 1000000.0)) + 0.5).rounded(.down) / 1000000.0)
      v = v + step
      `guard` = `guard` + 1
    }
    return out
  }

public func polarColumnKey(_ s: PolarSeries, _ i: Int) -> String { (s.stack ?? "#\(i)") }

public func layoutPolar(_ axes: PolarAxes, _ series: [PolarSeries], _ box: PyreonChartRect, _ options: PolarOptions? = nil) -> PolarLayout {
    let palette = (options?.palette ?? DEFAULT_PALETTE)
    let categoryOn = (axes.categoryOn ?? "angle")
    let n = axes.categories.count
    var nF = 0.0
    for i in 0..<n {
      nF = nF + 1.0
    }
    let fontSize = (options?.fontSize ?? 11.0)
    let gutter = options?.showLabels == false ? 4.0 : fontSize * 3.0
    let center = PyreonChartPt(x: box.x + box.w / 2.0, y: box.y + box.h / 2.0)
    let side = box.w < box.h ? box.w : box.h
    let rawOuter = side / 2.0 - gutter
    let outerR = rawOuter < 0.0 ? 0.0 : rawOuter
    let rawRatio = (options?.innerRatio ?? 0.0)
    let ratio = rawRatio < 0.0 ? 0.0 : rawRatio > 0.95 ? 0.95 : rawRatio
    let innerR = outerR * ratio
    let start = (axes.startAngle ?? -Double.pi / 2.0)
    let dir = axes.clockwise == false ? -1.0 : 1.0
    let barGap = (options?.barGap ?? 0.2)
    var columns: [String] = []
    for si in 0..<series.count {
      let s = series[si]
      if s.kind != "bar" {
        continue
      }
      let key = polarColumnKey(s, si)
      var known = false
      for c in columns {
        if c == key {
          known = true
        }
      }
      if !known {
        columns.append(key)
      }
    }
    var columnsF = 0.0
    for i in 0..<columns.count {
      columnsF = columnsF + 1.0
    }
    var stackTop: [Double] = []
    for c in 0..<columns.count {
      for i in 0..<n {
        stackTop.append(0.0)
      }
    }
    var lo = 0.0
    var hi = 0.0
    for si in 0..<series.count {
      let s = series[si]
      var col = -1
      if s.kind == "bar" && s.stack != nil && categoryOn == "angle" {
        let key = polarColumnKey(s, si)
        for c in 0..<columns.count {
          if columns[c] == key {
            col = c
          }
        }
      }
      for i in 0..<n {
        if i >= s.values.count {
          continue
        }
        let v = s.values[i]
        if !isFiniteNumber(v) {
          continue
        }
        if col >= 0 {
          let at = col * n + i
          let top = stackTop[at] + v
          stackTop[at] = top
          if top > hi {
            hi = top
          }
          if top < lo {
            lo = top
          }
        } else {
          if v > hi {
            hi = v
          }
          if v < lo {
            lo = v
          }
        }
      }
    }
    let domainLo = (axes.valueDomain?.min ?? lo)
    let domainHi = (axes.valueDomain?.max ?? hi)
    var sectors: [PolarSector] = []
    var lines: [PolarLine] = []
    var categoryLabels: [PolarCategoryLabel] = []
    var running: [Double] = []
    for c in 0..<columns.count {
      for i in 0..<n {
        running.append(0.0)
      }
    }
    if categoryOn == "angle" {
      let slot = nF <= 0.0 ? 0.0 : Double(POLAR_TAU) / nF
      for si in 0..<series.count {
        let s = series[si]
        if s.kind != "bar" {
          continue
        }
        let key = polarColumnKey(s, si)
        var col = 0
        var colF = 0.0
        for c in 0..<columns.count {
          if columns[c] == key {
            col = c
            colF = 0.0
            for k in 0..<c {
              colF = colF + 1.0
            }
          }
        }
        let color = (s.color ?? paletteAt(palette, si))
        var iF = 0.0
        for i in 0..<n {
          if i < s.values.count {
            let v = s.values[i]
            if isFiniteNumber(v) {
              let inner = (slot * barGap) / 2.0
              let width = (slot - slot * barGap) / columnsF
              let a0 = start + dir * slot * iF + dir * (inner + width * colF)
              let a1 = a0 + dir * width
              let at = col * n + i
              let base = running[at]
              running[at] = base + v
              sectors.append(PolarSector(series: si, index: i, start: a0 < a1 ? a0 : a1, end: a0 < a1 ? a1 : a0, innerR: innerR + (outerR - innerR) * polarFrac(base, domainLo, domainHi), outerR: innerR + (outerR - innerR) * polarFrac(base + v, domainLo, domainHi), color: color, value: v))
            }
          }
          iF = iF + 1.0
        }
      }
      for si in 0..<series.count {
        let s = series[si]
        if s.kind != "line" && s.kind != "scatter" {
          continue
        }
        let color = (s.color ?? paletteAt(palette, si))
        var points: [PolarPoint] = []
        var iF = 0.0
        for i in 0..<n {
          if i < s.values.count {
            let v = s.values[i]
            if isFiniteNumber(v) {
              let r = innerR + (outerR - innerR) * polarFrac(v, domainLo, domainHi)
              points.append(PolarPoint(series: si, index: i, at: pointOnCircle(center, r, start + dir * slot * (iF + 0.5)), color: color, value: v))
            }
          }
          iF = iF + 1.0
        }
        lines.append(PolarLine(series: si, color: color, points: points, scatter: s.kind == "scatter", radius: (s.radius ?? (s.kind == "scatter" ? 4.0 : 2.5))))
      }
      var iF = 0.0
      for i in 0..<n {
        let a = start + dir * slot * (iF + 0.5)
        let at = pointOnCircle(center, outerR + fontSize * 0.6, a)
        let c = cos(Double(a))
        categoryLabels.append(PolarCategoryLabel(text: axes.categories[i], at: at, align: c > 0.3 ? "start" : c < -0.3 ? "end" : "middle"))
        iF = iF + 1.0
      }
    } else {
      let ring = nF <= 0.0 ? 0.0 : (outerR - innerR) / nF
      for si in 0..<series.count {
        let s = series[si]
        if s.kind != "bar" {
          continue
        }
        let key = polarColumnKey(s, si)
        var colF = 0.0
        for c in 0..<columns.count {
          if columns[c] == key {
            colF = 0.0
            for k in 0..<c {
              colF = colF + 1.0
            }
          }
        }
        let color = (s.color ?? paletteAt(palette, si))
        var iF = 0.0
        for i in 0..<n {
          if i < s.values.count {
            let v = s.values[i]
            if isFiniteNumber(v) {
              let r0 = innerR + ring * iF + (ring * barGap) / 2.0
              let width = (ring - ring * barGap) / columnsF
              let sweep = dir * POLAR_TAU * polarFrac(v, domainLo, domainHi)
              let a0 = start
              let a1 = start + sweep
              sectors.append(PolarSector(series: si, index: i, start: a0 < a1 ? a0 : a1, end: a0 < a1 ? a1 : a0, innerR: r0 + width * colF, outerR: r0 + width * (colF + 1.0), color: color, value: v))
            }
          }
          iF = iF + 1.0
        }
      }
      for si in 0..<series.count {
        let s = series[si]
        if s.kind != "line" && s.kind != "scatter" {
          continue
        }
        let color = (s.color ?? paletteAt(palette, si))
        var points: [PolarPoint] = []
        var iF = 0.0
        for i in 0..<n {
          if i < s.values.count {
            let v = s.values[i]
            if isFiniteNumber(v) {
              points.append(PolarPoint(series: si, index: i, at: pointOnCircle(center, innerR + ring * (iF + 0.5), start + dir * POLAR_TAU * polarFrac(v, domainLo, domainHi)), color: color, value: v))
            }
          }
          iF = iF + 1.0
        }
        lines.append(PolarLine(series: si, color: color, points: points, scatter: s.kind == "scatter", radius: (s.radius ?? (s.kind == "scatter" ? 4.0 : 2.5))))
      }
      var iF = 0.0
      for i in 0..<n {
        categoryLabels.append(PolarCategoryLabel(text: axes.categories[i], at: PyreonChartPt(x: center.x + 4.0, y: center.y - (innerR + ring * (iF + 0.5))), align: "start"))
        iF = iF + 1.0
      }
    }
    var ticks: [PolarTick] = []
    for v in polarTicks(domainLo, domainHi) {
      ticks.append(PolarTick(value: v, label: "\(v)"))
    }
    return PolarLayout(center: center, innerR: innerR, outerR: outerR, domain: Domain(min: domainLo, max: domainHi), categoryOn: categoryOn, sectors: sectors, lines: lines, categoryLabels: categoryLabels, ticks: ticks)
  }

public func ringPolyline(_ center: PyreonChartPt, _ r: Double) -> [PyreonChartPt] {
    let full = arcPolygon(center, r, 0.0, 0.0, POLAR_TAU)
    var out: [PyreonChartPt] = []
    for i in 0..<full.count {
      if i >= 65 {
        break
      }
      out.append(full[i])
    }
    return out
  }

public func renderPolar(_ layout: PolarLayout, _ options: PolarOptions? = nil) -> [PyreonDrawCmd] {
    var out: [PyreonDrawCmd] = []
    let rawP = (options?.progress ?? 1.0)
    let progress = rawP < 0.0 ? 0.0 : rawP > 1.0 ? 1.0 : rawP
    let gridColor = (options?.gridColor ?? "#e2e8f0")
    let labelColor = (options?.labelColor ?? "#64748b")
    let fontSize = (options?.fontSize ?? 11.0)
    let lineWidth = (options?.lineWidth ?? 2.0)
    let c = layout.center
    let lo = layout.domain.min
    let hi = layout.domain.max
    if options?.showGrid != false {
      if layout.categoryOn == "angle" {
        for t in layout.ticks {
          let r = layout.innerR + (layout.outerR - layout.innerR) * polarFrac(t.value, lo, hi)
          if r <= 0.0 {
            continue
          }
          out.append(PyreonDrawCmd(kind: "polyline", stroke: gridColor, width: 1.0, points: ringPolyline(c, r)))
        }
      } else {
        var kF = 0.0
        for k in 0..<8 {
          out.append(PyreonDrawCmd(kind: "line", from: c, to: pointOnCircle(c, layout.outerR, (Double(kF) / 8.0) * POLAR_TAU), stroke: gridColor, width: 1.0))
          kF = kF + 1.0
        }
        out.append(PyreonDrawCmd(kind: "polyline", stroke: gridColor, width: 1.0, points: ringPolyline(c, layout.outerR)))
      }
    }
    for s in layout.sectors {
      let outerR = layout.categoryOn == "angle" ? s.innerR + (s.outerR - s.innerR) * progress : s.outerR
      let end = layout.categoryOn == "radius" ? s.start + (s.end - s.start) * progress : s.end
      if outerR <= s.innerR || end <= s.start {
        continue
      }
      out.append(PyreonDrawCmd(kind: "polygon", fill: s.color, points: arcPolygon(c, outerR, s.innerR, s.start, end)))
    }
    for l in layout.lines {
      var lenF = 0.0
      for i in 0..<l.points.count {
        lenF = lenF + 1.0
      }
      var countF = 0.0
      if progress >= 1.0 {
        countF = lenF
      } else {
        while countF + 1.0 <= lenF * progress {
          countF = countF + 1.0
        }
      }
      var pts: [PyreonChartPt] = []
      var iF = 0.0
      for i in 0..<l.points.count {
        if iF >= countF {
          break
        }
        pts.append(l.points[i].at)
        iF = iF + 1.0
      }
      if pts.count > 1 && !l.scatter {
        out.append(PyreonDrawCmd(kind: "polyline", stroke: l.color, width: lineWidth, points: pts))
      }
      for p in pts {
        out.append(PyreonDrawCmd(kind: "circle", fill: l.color, center: p, radius: l.radius))
      }
    }
    if options?.showLabels != false && progress >= 1.0 {
      for lab in layout.categoryLabels {
        out.append(PyreonDrawCmd(kind: "text", fill: labelColor, text: lab.text, at: lab.at, size: fontSize, align: lab.align, baseline: "middle"))
      }
    }
    return out
  }

public func hitPolarIndex(_ layout: PolarLayout, _ px: Double, _ py: Double) -> PolarHitIndex {
    let dx = px - layout.center.x
    let dy = py - layout.center.y
    let dist = sqrt(Double(dx * dx + dy * dy))
    let ang = atan2(Double(dy), Double(dx))
    var sectorIdx = -1
    for i in 0..<layout.sectors.count {
      if sectorIdx >= 0 {
        continue
      }
      let s = layout.sectors[i]
      if dist < s.innerR || dist > s.outerR {
        continue
      }
      var t = ang
      while t < s.start {
        t = t + POLAR_TAU
      }
      while t >= s.start + POLAR_TAU {
        t = t - POLAR_TAU
      }
      if t <= s.end {
        sectorIdx = i
      }
    }
    if sectorIdx >= 0 {
      return PolarHitIndex(sector: sectorIdx, line: -1, point: -1)
    }
    var bestLine = -1
    var bestPoint = -1
    var bestD = 36.0
    for li in 0..<layout.lines.count {
      let l = layout.lines[li]
      for pi in 0..<l.points.count {
        let p = l.points[pi]
        let d = (px - p.at.x) * (px - p.at.x) + (py - p.at.y) * (py - p.at.y)
        if d <= bestD {
          bestLine = li
          bestPoint = pi
          bestD = d
        }
      }
    }
    return PolarHitIndex(sector: -1, line: bestLine, point: bestPoint)
  }

public func sankeyRgba(_ hex: String, _ alpha: Double) -> String {
    if hex.utf16.count < 7 {
      return hex
    }
    let r = hexDigit(Double(Array(hex.utf16)[Int(1)])) * 16.0 + hexDigit(Double(Array(hex.utf16)[Int(2)]))
    let g = hexDigit(Double(Array(hex.utf16)[Int(3)])) * 16.0 + hexDigit(Double(Array(hex.utf16)[Int(4)]))
    let b = hexDigit(Double(Array(hex.utf16)[Int(5)])) * 16.0 + hexDigit(Double(Array(hex.utf16)[Int(6)]))
    return "rgba(\(((Double(r)) + 0.5).rounded(.down)), \(((Double(g)) + 0.5).rounded(.down)), \(((Double(b)) + 0.5).rounded(.down)), \(alpha))"
  }

public func sankeyIndexOf(_ nodes: [SankeyNode], _ name: String) -> Int {
    for i in 0..<nodes.count {
      if nodes[i].name == name {
        return i
      }
    }
    return -1
  }

public func layoutSankey(_ nodes: [SankeyNode], _ links: [SankeyLink], _ box: PyreonChartRect, _ options: SankeyOptions? = nil) -> SankeyLayout {
    let palette = (options?.palette ?? DEFAULT_PALETTE)
    let nodeWidth = (options?.nodeWidth ?? 16.0)
    let padding = (options?.nodePadding ?? 8.0)
    let iterations = (options?.iterations ?? 6.0)
    let align = (options?.align ?? "justify")
    var dropped: [String] = []
    var keptS: [Int] = []
    var keptT: [Int] = []
    var keptV: [Double] = []
    for l in links {
      let s = sankeyIndexOf(nodes, l.source)
      let t = sankeyIndexOf(nodes, l.target)
      if s < 0 || t < 0 || s == t || !(l.value > 0.0) {
        dropped.append("\(l.source) -> \(l.target)")
        continue
      }
      keptS.append(s)
      keptT.append(t)
      keptV.append(l.value)
    }
    let n = nodes.count
    var depth: [Int] = []
    for i in 0..<n {
      depth.append(0)
    }
    var live: [Bool] = []
    for k in 0..<keptS.count {
      live.append(true)
    }
    var round = 0
    var settled = false
    while !settled && round <= n {
      var changed = false
      for k in 0..<keptS.count {
        if !live[k] {
          continue
        }
        let s = keptS[k]
        let t = keptT[k]
        if depth[t] < depth[s] + 1 {
          if round == n {
            live[k] = false
            dropped.append("\(nodes[s].name) -> \(nodes[t].name) (cycle)")
          } else {
            depth[t] = depth[s] + 1
            changed = true
          }
        }
      }
      if !changed {
        settled = true
      }
      round = round + 1
    }
    var flowS: [Int] = []
    var flowT: [Int] = []
    var flowV: [Double] = []
    for k in 0..<keptS.count {
      if !live[k] {
        continue
      }
      flowS.append(keptS[k])
      flowT.append(keptT[k])
      flowV.append(keptV[k])
    }
    var maxDepth = 0
    for i in 0..<n {
      if depth[i] > maxDepth {
        maxDepth = depth[i]
      }
    }
    if align == "justify" {
      var hasOut: [Bool] = []
      for i in 0..<n {
        hasOut.append(false)
      }
      for s in flowS {
        hasOut[s] = true
      }
      for i in 0..<n {
        if !hasOut[i] {
          depth[i] = maxDepth
        }
      }
    }
    var inSum: [Double] = []
    var outSum: [Double] = []
    for i in 0..<n {
      inSum.append(0.0)
      outSum.append(0.0)
    }
    for k in 0..<flowS.count {
      outSum[flowS[k]] = outSum[flowS[k]] + flowV[k]
      inSum[flowT[k]] = inSum[flowT[k]] + flowV[k]
    }
    var value: [Double] = []
    for i in 0..<n {
      value.append(inSum[i] > outSum[i] ? inSum[i] : outSum[i])
    }
    var ky = 0.0
    var kySeen = false
    for d in 0...maxDepth {
      var total = 0.0
      var members = 0.0
      for i in 0..<n {
        if depth[i] != d {
          continue
        }
        total = total + value[i]
        members = members + 1.0
      }
      let avail = box.h - padding * (members > 1.0 ? members - 1.0 : 0.0)
      if total > 0.0 && avail > 0.0 {
        let cand = Double(avail) / Double(total)
        if !kySeen || cand < ky {
          ky = cand
        }
        kySeen = true
      }
    }
    var maxDepthF = 0.0
    for d in 0..<maxDepth {
      maxDepthF = maxDepthF + 1.0
    }
    var y0: [Double] = []
    var hgt: [Double] = []
    for i in 0..<n {
      y0.append(0.0)
      hgt.append(value[i] * ky)
    }
    for d in 0...maxDepth {
      var y = box.y
      for i in 0..<n {
        if depth[i] != d {
          continue
        }
        y0[i] = y
        y = y + hgt[i] + padding
      }
    }
    var itF = 0.0
    for it in 0..<Int(ceil(Double(iterations))) {
      let alpha = 0.99 - itF * (0.99 / (iterations > 1.0 ? iterations : 1.0))
      for pass in 0..<2 {
        let forward = pass == 0
        let dStart = forward ? 1 : maxDepth - 1
        let dEnd = forward ? maxDepth : 0
        let dStep = forward ? 1 : -1
        var d = dStart
        var more = forward ? d <= dEnd : d >= dEnd
        while more {
          for i in 0..<n {
            if depth[i] != d {
              continue
            }
            var w = 0.0
            var acc = 0.0
            for k in 0..<flowS.count {
              let other = forward ? flowS[k] : flowT[k]
              let mine = forward ? flowT[k] : flowS[k]
              if mine != i {
                continue
              }
              acc = acc + (y0[other] + hgt[other] / 2.0) * flowV[k]
              w = w + flowV[k]
            }
            if w > 0.0 {
              y0[i] = y0[i] + (Double(acc) / Double(w) - (y0[i] + hgt[i] / 2.0)) * alpha
            }
          }
          var col: [Int] = []
          for i in 0..<n {
            if depth[i] == d {
              col.append(i)
            }
          }
          for a in 1..<col.count {
            let cur = col[a]
            let cc = y0[cur] + hgt[cur] / 2.0
            var b = a - 1
            while b >= 0 {
              let prev = col[b]
              if y0[prev] + hgt[prev] / 2.0 <= cc {
                break
              }
              col[b + 1] = prev
              b = b - 1
            }
            col[b + 1] = cur
          }
          var y = box.y
          for i in col {
            if y0[i] < y {
              y0[i] = y
            }
            y = y0[i] + hgt[i] + padding
          }
          var bottom = box.y + box.h
          for k in stride(from: col.count - 1, through: 0, by: -1) {
            let i = col[k]
            if y0[i] + hgt[i] > bottom {
              y0[i] = bottom - hgt[i]
            }
            bottom = y0[i] - padding
          }
          d = d + dStep
          more = forward ? d <= dEnd : d >= dEnd
        }
      }
      itF = itF + 1.0
    }
    var outNodes: [SankeyLayoutNode] = []
    for i in 0..<n {
      var depthF = 0.0
      for d in 0..<depth[i] {
        depthF = depthF + 1.0
      }
      let x = maxDepthF <= 0.0 ? box.x : box.x + ((box.w - nodeWidth) * depthF) / maxDepthF
      outNodes.append(SankeyLayoutNode(name: nodes[i].name, index: i, depth: depth[i], value: value[i], rect: PyreonChartRect(x: x, y: y0[i], w: nodeWidth, h: hgt[i]), color: (nodes[i].color ?? paletteAt(palette, i))))
    }
    var outCursor: [Double] = []
    var inCursor: [Double] = []
    for i in 0..<n {
      outCursor.append(y0[i])
      inCursor.append(y0[i])
    }
    var linkY0: [Double] = []
    var linkY1: [Double] = []
    for k in 0..<flowS.count {
      linkY0.append(0.0)
      linkY1.append(0.0)
    }
    var orderOut: [Int] = []
    for k in 0..<flowS.count {
      orderOut.append(k)
    }
    for a in 1..<orderOut.count {
      let cur = orderOut[a]
      let ct = y0[flowT[cur]] + hgt[flowT[cur]] / 2.0
      var b = a - 1
      while b >= 0 {
        let prev = orderOut[b]
        let pt = y0[flowT[prev]] + hgt[flowT[prev]] / 2.0
        if pt < ct || (pt == ct && flowS[prev] <= flowS[cur]) {
          break
        }
        orderOut[b + 1] = prev
        b = b - 1
      }
      orderOut[b + 1] = cur
    }
    for k in orderOut {
      linkY0[k] = outCursor[flowS[k]]
      outCursor[flowS[k]] = outCursor[flowS[k]] + flowV[k] * ky
    }
    var orderIn: [Int] = []
    for k in 0..<flowS.count {
      orderIn.append(k)
    }
    for a in 1..<orderIn.count {
      let cur = orderIn[a]
      let cs = y0[flowS[cur]] + hgt[flowS[cur]] / 2.0
      var b = a - 1
      while b >= 0 {
        let prev = orderIn[b]
        let ps = y0[flowS[prev]] + hgt[flowS[prev]] / 2.0
        if ps < cs || (ps == cs && flowT[prev] <= flowT[cur]) {
          break
        }
        orderIn[b + 1] = prev
        b = b - 1
      }
      orderIn[b + 1] = cur
    }
    for k in orderIn {
      linkY1[k] = inCursor[flowT[k]]
      inCursor[flowT[k]] = inCursor[flowT[k]] + flowV[k] * ky
    }
    var outLinks: [SankeyLayoutLink] = []
    for k in 0..<flowS.count {
      outLinks.append(SankeyLayoutLink(source: flowS[k], target: flowT[k], value: flowV[k], width: flowV[k] * ky, y0: linkY0[k], y1: linkY1[k]))
    }
    return SankeyLayout(nodes: outNodes, links: outLinks, dropped: dropped)
  }

public func ribbonPoints(_ layout: SankeyLayout, _ link: SankeyLayoutLink, _ progress: Double? = nil) -> [PyreonChartPt] {
    let s = layout.nodes[link.source].rect
    let t = layout.nodes[link.target].rect
    let x0 = s.x + s.w
    let x1raw = t.x
    let rawP = (progress ?? 1.0)
    let p = rawP < 0.0 ? 0.0 : rawP > 1.0 ? 1.0 : rawP
    let x1 = x0 + (x1raw - x0) * p
    var top: [PyreonChartPt] = []
    var bottom: [PyreonChartPt] = []
    var iF = 0.0
    for i in 0...16 {
      let u = iF / 16.0
      let e = u * u * (3.0 - 2.0 * u)
      let x = x0 + (x1 - x0) * u
      top.append(PyreonChartPt(x: x, y: link.y0 + (link.y1 - link.y0) * e))
      bottom.append(PyreonChartPt(x: x, y: link.y0 + link.width + (link.y1 + link.width - (link.y0 + link.width)) * e))
      iF = iF + 1.0
    }
    var out: [PyreonChartPt] = []
    for p2 in top {
      out.append(p2)
    }
    var bi = bottom.count - 1
    while bi >= 0 {
      out.append(bottom[bi])
      bi = bi - 1
    }
    return out
  }

public func renderSankey(_ layout: SankeyLayout, _ options: SankeyOptions? = nil) -> [PyreonDrawCmd] {
    var out: [PyreonDrawCmd] = []
    let opacity = (options?.linkOpacity ?? 0.35)
    let rawP = (options?.progress ?? 1.0)
    let progress = rawP < 0.0 ? 0.0 : rawP > 1.0 ? 1.0 : rawP
    let showLabels = (options?.showLabels ?? true)
    let fontSize = (options?.fontSize ?? 11.0)
    let labelColor = (options?.labelColor ?? "#334155")
    var maxDepth = 0
    for nd in layout.nodes {
      if nd.depth > maxDepth {
        maxDepth = nd.depth
      }
    }
    for l in layout.links {
      if l.width <= 0.0 {
        continue
      }
      out.append(PyreonDrawCmd(kind: "polygon", fill: sankeyRgba(layout.nodes[l.source].color, opacity), points: ribbonPoints(layout, l, progress)))
    }
    for nd in layout.nodes {
      if nd.rect.h <= 0.0 {
        continue
      }
      out.append(PyreonDrawCmd(kind: "rect", rect: nd.rect, fill: nd.color))
      if !showLabels || progress < 1.0 {
        continue
      }
      let last = nd.depth == maxDepth
      out.append(PyreonDrawCmd(kind: "text", fill: labelColor, text: nd.name, at: PyreonChartPt(x: last ? nd.rect.x - 4.0 : nd.rect.x + nd.rect.w + 4.0, y: nd.rect.y + Double(nd.rect.h) / 2.0), size: fontSize, align: last ? "end" : "start", baseline: "middle"))
    }
    return out
  }

public func sankeyPointInPolygon(_ pts: [PyreonChartPt], _ px: Double, _ py: Double) -> Bool {
    var inside = false
    var j = pts.count - 1
    for i in 0..<pts.count {
      let a = pts[i]
      let b = pts[j]
      let aAbove = a.y > py
      let bAbove = b.y > py
      if aAbove != bAbove && px < ((b.x - a.x) * (py - a.y)) / Double((b.y - a.y)) + a.x {
        inside = !inside
      }
      j = i
    }
    return inside
  }

public func hitSankeyIndex(_ layout: SankeyLayout, _ px: Double, _ py: Double) -> SankeyHitIndex {
    var nodeIdx = -1
    for i in 0..<layout.nodes.count {
      if nodeIdx >= 0 {
        continue
      }
      let r = layout.nodes[i].rect
      if px >= r.x && px <= r.x + r.w && py >= r.y && py <= r.y + r.h {
        nodeIdx = i
      }
    }
    if nodeIdx >= 0 {
      return SankeyHitIndex(node: nodeIdx, link: -1)
    }
    var linkIdx = -1
    for k in 0..<layout.links.count {
      if linkIdx >= 0 {
        continue
      }
      let l = layout.links[k]
      if l.width > 0.0 && sankeyPointInPolygon(ribbonPoints(layout, l, 1.0), px, py) {
        linkIdx = k
      }
    }
    return SankeyHitIndex(node: -1, link: linkIdx)
  }

public func graphNextSeed(_ state: Double) -> Double {
    let raw = state * 16807.0
    return raw - floor(Double(raw / Double(GRAPH_LCG_M))) * GRAPH_LCG_M
  }

public func graphSeedState(_ seed: Double) -> Double {
    let f = floor(Double(seed < 0.0 ? -seed : seed))
    let wrapped = f - floor(Double(f / (GRAPH_LCG_M - 1.0))) * (GRAPH_LCG_M - 1.0)
    return wrapped + 1.0
  }

public func graphIndexOf(_ nodes: [GraphNode], _ id: String) -> Int {
    for i in 0..<nodes.count {
      if nodes[i].id == id {
        return i
      }
    }
    return -1
  }

public func graphRadius(_ value: Double, _ hasValue: Bool, _ maxValue: Double, _ base: Double) -> Double {
    if !hasValue || maxValue <= 0.0 {
      return base / 2.0
    }
    let v = value < 0.0 ? 0.0 : value
    return (base / 2.0) * (0.6 + 1.4 * sqrt(Double(v / maxValue)))
  }

public func layoutGraph(_ nodes: [GraphNode], _ links: [GraphLink], _ box: PyreonChartRect, _ options: GraphOptions? = nil) -> GraphLayout {
    let palette = (options?.palette ?? DEFAULT_PALETTE)
    let mode = (options?.layout ?? "force")
    let base = (options?.symbolSize ?? 10.0)
    var dropped: [String] = []
    var outLinks: [GraphLayoutLink] = []
    for l in links {
      let s = graphIndexOf(nodes, l.source)
      let t = graphIndexOf(nodes, l.target)
      if s < 0 || t < 0 {
        dropped.append("\(l.source) -> \(l.target)")
        continue
      }
      outLinks.append(GraphLayoutLink(source: s, target: t, value: l.value, index: outLinks.count))
    }
    let n = nodes.count
    var nF = 0.0
    for i in 0..<n {
      nF = nF + 1.0
    }
    var maxValue = 0.0
    for nd in nodes {
      let v = (nd.value ?? -1.0)
      if v > maxValue {
        maxValue = v
      }
    }
    let cx = box.x + box.w / 2.0
    let cy = box.y + box.h / 2.0
    var px: [Double] = []
    var py: [Double] = []
    var radius: [Double] = []
    for i in 0..<n {
      px.append(cx)
      py.append(cy)
      let v = (nodes[i].value ?? -1.0)
      radius.append(graphRadius(v, v >= 0.0, maxValue, base))
    }
    if mode == "circular" {
      let half = (box.w < box.h ? box.w : box.h) / 2.0 - base
      let R = half < 0.0 ? 0.0 : half
      var iF = 0.0
      for i in 0..<n {
        let ang = -Double.pi / 2.0 + (nF <= 0.0 ? 0.0 : (Double(iF) / nF) * GRAPH_TAU)
        px[i] = cx + cos(Double(ang)) * R
        py[i] = cy + sin(Double(ang)) * R
        iF = iF + 1.0
      }
    } else {
      if mode == "none" {
        var minX = 0.0
        var maxX = 0.0
        var minY = 0.0
        var maxY = 0.0
        var seen = false
        for nd in nodes {
          let x = (nd.x ?? 0.0)
          let y = (nd.y ?? 0.0)
          if !seen || x < minX {
            minX = x
          }
          if !seen || x > maxX {
            maxX = x
          }
          if !seen || y < minY {
            minY = y
          }
          if !seen || y > maxY {
            maxY = y
          }
          seen = true
        }
        let spanX = maxX - minX
        let spanY = maxY - minY
        let pad = base
        for i in 0..<n {
          let fx = spanX <= 0.0 ? 0.5 : (((nodes[i].x ?? 0.0)) - minX) / Double(spanX)
          let fy = spanY <= 0.0 ? 0.5 : (((nodes[i].y ?? 0.0)) - minY) / Double(spanY)
          px[i] = box.x + pad + (box.w - pad * 2.0) * fx
          py[i] = box.y + pad + (box.h - pad * 2.0) * fy
        }
      } else {
        var seed = graphSeedState((options?.seed ?? 7.0))
        let rawIt = floor(Double((options?.iterations ?? 200.0)))
        let iterations = rawIt < 0.0 ? 0.0 : rawIt
        let rawArea = box.w * box.h
        let area = rawArea < 1.0 ? 1.0 : rawArea
        let k = sqrt(Double(Double(area) / (nF < 1.0 ? 1.0 : nF)))
        let repulsion = (options?.repulsion ?? k * k)
        let linkDistance = (options?.linkDistance ?? k)
        let gravity = (options?.gravity ?? 0.05)
        let spread = (box.w < box.h ? box.w : box.h) / 3.0
        for i in 0..<n {
          seed = graphNextSeed(seed)
          px[i] = cx + (Double(seed) / Double(GRAPH_LCG_M) - 0.5) * spread
          seed = graphNextSeed(seed)
          py[i] = cy + (Double(seed) / Double(GRAPH_LCG_M) - 0.5) * spread
        }
        var temp = (box.w > box.h ? box.w : box.h) / 10.0
        let cool = iterations <= 0.0 ? 0.0 : Double(temp) / Double(iterations)
        var dx: [Double] = []
        var dy: [Double] = []
        for i in 0..<n {
          dx.append(0.0)
          dy.append(0.0)
        }
        var it = 0.0
        while it < iterations {
          for i in 0..<n {
            dx[i] = 0.0
            dy[i] = 0.0
          }
          for i in 0..<n {
            for j in i + 1..<n {
              var ddx = px[i] - px[j]
              var ddy = py[i] - py[j]
              var d = sqrt(Double(ddx * ddx + ddy * ddy))
              if d < 0.01 {
                seed = graphNextSeed(seed)
                ddx = (Double(seed) / Double(GRAPH_LCG_M) - 0.5) * 0.1
                seed = graphNextSeed(seed)
                ddy = (Double(seed) / Double(GRAPH_LCG_M) - 0.5) * 0.1
                d = 0.01
              }
              let f = Double(repulsion) / Double((d * d))
              let fx = (Double(ddx) / Double(d)) * f
              let fy = (Double(ddy) / Double(d)) * f
              dx[i] = dx[i] + fx
              dy[i] = dy[i] + fy
              dx[j] = dx[j] - fx
              dy[j] = dy[j] - fy
            }
          }
          for l in outLinks {
            var ddx = px[l.source] - px[l.target]
            var ddy = py[l.source] - py[l.target]
            var d = sqrt(Double(ddx * ddx + ddy * ddy))
            if d <= 0.0 {
              continue
            }
            let f = Double((d * d)) / Double(linkDistance)
            let fx = (Double(ddx) / Double(d)) * f
            let fy = (Double(ddy) / Double(d)) * f
            dx[l.source] = dx[l.source] - fx
            dy[l.source] = dy[l.source] - fy
            dx[l.target] = dx[l.target] + fx
            dy[l.target] = dy[l.target] + fy
          }
          for i in 0..<n {
            dx[i] = dx[i] + (cx - px[i]) * gravity * k * 0.1
            dy[i] = dy[i] + (cy - py[i]) * gravity * k * 0.1
            var d = sqrt(Double(dx[i] * dx[i] + dy[i] * dy[i]))
            if d > 0.0 {
              let step = d < temp ? d : temp
              px[i] = px[i] + (Double(dx[i]) / Double(d)) * step
              py[i] = py[i] + (Double(dy[i]) / Double(d)) * step
            }
            let r = radius[i]
            if px[i] < box.x + r {
              px[i] = box.x + r
            }
            if px[i] > box.x + box.w - r {
              px[i] = box.x + box.w - r
            }
            if py[i] < box.y + r {
              py[i] = box.y + r
            }
            if py[i] > box.y + box.h - r {
              py[i] = box.y + box.h - r
            }
          }
          temp = temp - cool
          if temp < 0.5 {
            temp = 0.5
          }
          it = it + 1.0
        }
      }
    }
    var outNodes: [GraphLayoutNode] = []
    for i in 0..<n {
      let nd = nodes[i]
      let cat = nd.category
      let color = (nd.color ?? paletteAt(palette, (cat ?? i)))
      outNodes.append(GraphLayoutNode(id: nd.id, name: (nd.name ?? nd.id), index: i, at: PyreonChartPt(x: px[i], y: py[i]), radius: radius[i], color: color, category: cat, value: nd.value))
    }
    return GraphLayout(mode: mode, nodes: outNodes, links: outLinks, dropped: dropped)
  }

public func graphAt(_ n: GraphLayoutNode, _ cx: Double, _ cy: Double, _ progress: Double) -> PyreonChartPt { PyreonChartPt(x: cx + (n.at.x - cx) * progress, y: cy + (n.at.y - cy) * progress) }

public func renderGraph(_ layout: GraphLayout, _ box: PyreonChartRect, _ options: GraphOptions? = nil) -> [PyreonDrawCmd] {
    var out: [PyreonDrawCmd] = []
    let rawP = (options?.progress ?? 1.0)
    let progress = rawP < 0.0 ? 0.0 : rawP > 1.0 ? 1.0 : rawP
    let cx = box.x + box.w / 2.0
    let cy = box.y + box.h / 2.0
    let linkColor = (options?.linkColor ?? "#94a3b8")
    let showLabels = (options?.showLabels ?? false)
    let fontSize = (options?.fontSize ?? 11.0)
    let labelColor = (options?.labelColor ?? "#334155")
    var maxLink = 0.0
    for l in layout.links {
      let v = (l.value ?? -1.0)
      if v > maxLink {
        maxLink = v
      }
    }
    for l in layout.links {
      let v = (l.value ?? -1.0)
      let width = v < 0.0 || maxLink <= 0.0 ? 1.0 : 1.0 + 3.0 * (Double(v) / maxLink)
      out.append(PyreonDrawCmd(kind: "line", from: graphAt(layout.nodes[l.source], cx, cy, progress), to: graphAt(layout.nodes[l.target], cx, cy, progress), stroke: linkColor, width: width))
    }
    for nd in layout.nodes {
      out.append(PyreonDrawCmd(kind: "circle", fill: nd.color, center: graphAt(nd, cx, cy, progress), radius: nd.radius))
      if !showLabels || progress < 1.0 {
        continue
      }
      out.append(PyreonDrawCmd(kind: "text", fill: labelColor, text: nd.name, at: PyreonChartPt(x: nd.at.x + nd.radius + 3.0, y: nd.at.y), size: fontSize, align: "start", baseline: "middle"))
    }
    return out
  }

public func hitGraphIndex(_ layout: GraphLayout, _ px: Double, _ py: Double) -> Int {
    var best = -1
    var bestD = 0.0
    for i in 0..<layout.nodes.count {
      let nd = layout.nodes[i]
      let dx = px - nd.at.x
      let dy = py - nd.at.y
      let d = dx * dx + dy * dy
      let r = nd.radius + 3.0
      if d <= r * r && (best < 0 || d < bestD) {
        best = i
        bestD = d
      }
    }
    return best
  }

public func daysFromCivil(_ year: Double, _ month: Double, _ day: Double) -> Double {
    let yy = month <= 2.0 ? year - 1.0 : year
    let era = floor(Double(yy / 400.0))
    let yoe = yy - era * 400.0
    let mp = month > 2.0 ? month - 3.0 : month + 9.0
    let doy = floor(Double((153.0 * mp + 2.0) / 5.0)) + day - 1.0
    let doe = yoe * 365.0 + floor(Double(yoe / 4.0)) - floor(Double(yoe / 100.0)) + doy
    return era * 146097.0 + doe - 719468.0
  }

public func civilFromDays(_ days: Double) -> CalendarDate {
    let z = days + 719468.0
    let era = floor(Double(z / 146097.0))
    let doe = z - era * 146097.0
    let yoe = floor(Double((doe - floor(Double(doe / 1460.0)) + floor(Double(doe / 36524.0)) - floor(Double(doe / 146096.0))) / 365.0))
    let y = yoe + era * 400.0
    let doy = doe - (365.0 * yoe + floor(Double(yoe / 4.0)) - floor(Double(yoe / 100.0)))
    let mp = floor(Double((5.0 * doy + 2.0) / 153.0))
    let d = doy - floor(Double((153.0 * mp + 2.0) / 5.0)) + 1.0
    let m = mp < 10.0 ? mp + 3.0 : mp - 9.0
    return CalendarDate(year: m <= 2.0 ? y + 1.0 : y, month: m, day: d)
  }

public func weekdayOfDays(_ days: Double) -> Double {
    let x = days + 4.0
    return x - floor(Double(x / 7.0)) * 7.0
  }

public func calendarDigit(_ c: Double) -> Double {
    if c >= 48.0 && c <= 57.0 {
      return c - 48.0
    }
    return -1.0
  }

public func parseIsoDays(_ s: String) -> CalendarParsed {
    if s.utf16.count != 10 || Double(Array(s.utf16)[Int(4)]) != 45.0 || Double(Array(s.utf16)[Int(7)]) != 45.0 {
      return CalendarParsed(ok: false, days: 0.0)
    }
    let y0 = calendarDigit(Double(Array(s.utf16)[Int(0)]))
    let y1 = calendarDigit(Double(Array(s.utf16)[Int(1)]))
    let y2 = calendarDigit(Double(Array(s.utf16)[Int(2)]))
    let y3 = calendarDigit(Double(Array(s.utf16)[Int(3)]))
    let m0 = calendarDigit(Double(Array(s.utf16)[Int(5)]))
    let m1 = calendarDigit(Double(Array(s.utf16)[Int(6)]))
    let d0 = calendarDigit(Double(Array(s.utf16)[Int(8)]))
    let d1 = calendarDigit(Double(Array(s.utf16)[Int(9)]))
    if y0 < 0.0 || y1 < 0.0 || y2 < 0.0 || y3 < 0.0 || m0 < 0.0 || m1 < 0.0 || d0 < 0.0 || d1 < 0.0 {
      return CalendarParsed(ok: false, days: 0.0)
    }
    let y = y0 * 1000.0 + y1 * 100.0 + y2 * 10.0 + y3
    let m = m0 * 10.0 + m1
    let d = d0 * 10.0 + d1
    if m < 1.0 || m > 12.0 || d < 1.0 || d > 31.0 {
      return CalendarParsed(ok: false, days: 0.0)
    }
    let days = daysFromCivil(y, m, d)
    let back = civilFromDays(days)
    if back.month != m || back.day != d {
      return CalendarParsed(ok: false, days: 0.0)
    }
    return CalendarParsed(ok: true, days: days)
  }

public func formatIsoDays(_ days: Double) -> String {
    let c = civilFromDays(days)
    let mp = c.month < 10.0 ? "0" : ""
    let dp = c.day < 10.0 ? "0" : ""
    let yp = c.year < 1000.0 ? (c.year < 100.0 ? (c.year < 10.0 ? "000" : "00") : "0") : ""
    return "\(yp)\(((Double(c.year)) + 0.5).rounded(.down))-\(mp)\(((Double(c.month)) + 0.5).rounded(.down))-\(dp)\(((Double(c.day)) + 0.5).rounded(.down))"
  }

public func layoutCalendar(_ start: String, _ end: String, _ box: PyreonChartRect, _ options: CalendarOptions? = nil) -> CalendarLayout {
    let p0 = parseIsoDays(start)
    let p1 = parseIsoDays(end)
    if !p0.ok || !p1.ok || p1.days < p0.days {
      return CalendarLayout(cells: [], monthLabels: [], dayLabels: [], cellSize: 0.0, startDay: 0.0, days: 0.0)
    }
    let rawFirst = floor(Double((options?.firstDay ?? 0.0)))
    let firstDay = rawFirst < 0.0 ? 0.0 : rawFirst > 6.0 ? 6.0 : rawFirst
    let gap = (options?.cellGap ?? 2.0)
    let fontSize = (options?.fontSize ?? 10.0)
    let showMonths = (options?.showMonthLabels ?? true)
    let showDays = (options?.showDayLabels ?? true)
    let gutterX = showDays ? fontSize * 2.6 : 0.0
    let gutterY = showMonths ? fontSize * 1.6 : 0.0
    let sr = weekdayOfDays(p0.days) - firstDay + 7.0
    let startRow = sr - floor(Double(sr / 7.0)) * 7.0
    let days = p1.days - p0.days + 1.0
    let weeksRaw = (startRow + days) / 7.0
    let weeksF = floor(Double(weeksRaw))
    let weeks = weeksF < weeksRaw ? weeksF + 1.0 : weeksF
    let fitW = weeks <= 0.0 ? 0.0 : (box.w - gutterX) / weeks
    let fitH = (box.h - gutterY) / 7.0
    let fitRaw = fitW < fitH ? fitW : fitH
    let fit = fitRaw < 0.0 ? 0.0 : fitRaw
    let fixed = (options?.cellSize ?? -1.0)
    let pitch = fixed >= 0.0 ? fixed + gap : fit
    let rawCell = pitch - gap
    let cellSize = rawCell < 0.0 ? 0.0 : rawCell
    let originX = box.x + gutterX
    let originY = box.y + gutterY
    var cells: [CalendarCell] = []
    var monthLabels: [CalendarLabel] = []
    var lastMonthKey = -1.0
    var iF = 0.0
    while iF < days {
      let t = p0.days + iF
      let c = civilFromDays(t)
      let idx = startRow + iF
      let week = floor(Double(Double(idx) / 7.0))
      let row = idx - week * 7.0
      let rect = PyreonChartRect(x: originX + week * pitch, y: originY + row * pitch, w: cellSize, h: cellSize)
      cells.append(CalendarCell(date: formatIsoDays(t), rect: rect, row: row, week: week, month: c.month - 1.0, day: c.day, year: c.year))
      let key = c.year * 12.0 + c.month
      if key != lastMonthKey {
        lastMonthKey = key
        var mi = 0
        var miF = 1.0
        while miF < c.month {
          mi = mi + 1
          miF = miF + 1.0
        }
        monthLabels.append(CalendarLabel(kind: "month", text: CALENDAR_MONTHS[mi], at: PyreonChartPt(x: originX + week * pitch, y: originY - fontSize * 0.4)))
      }
      iF = iF + 1.0
    }
    var dayLabels: [CalendarLabel] = []
    var rF = 0.0
    for r in 0..<7 {
      if r % 2 == 1 {
        let raw = firstDay + rF
        let dIdx = raw - floor(Double(Double(raw) / 7.0)) * 7.0
        var di = 0
        var diF = 0.0
        while diF < dIdx {
          di = di + 1
          diF = diF + 1.0
        }
        dayLabels.append(CalendarLabel(kind: "day", text: CALENDAR_DAYS[di], at: PyreonChartPt(x: originX - fontSize * 0.4, y: originY + rF * pitch + cellSize / 2.0)))
      }
      rF = rF + 1.0
    }
    return CalendarLayout(cells: cells, monthLabels: showMonths ? monthLabels : [], dayLabels: showDays ? dayLabels : [], cellSize: cellSize, startDay: p0.days, days: days)
  }

public func calendarCellValues(_ layout: CalendarLayout, _ values: [CalendarValue]) -> CalendarCellValues {
    var has: [Bool] = []
    var value: [Double] = []
    for i in 0..<layout.cells.count {
      has.append(false)
      value.append(0.0)
    }
    var vDays: [Double] = []
    var vOk: [Bool] = []
    for v in values {
      let p = parseIsoDays(v.date)
      vDays.append(p.days)
      vOk.append(p.ok && isFiniteNumber(v.value))
    }
    var iF = 0.0
    for i in 0..<layout.cells.count {
      let day = layout.startDay + iF
      for k in 0..<values.count {
        if !vOk[k] || vDays[k] != day {
          continue
        }
        has[i] = true
        value[i] = values[k].value
      }
      iF = iF + 1.0
    }
    return CalendarCellValues(has: has, value: value)
  }

public func calendarDomain(_ layout: CalendarLayout, _ values: [CalendarValue]) -> Domain {
    let cv = calendarCellValues(layout, values)
    var lo = 0.0
    var hi = 0.0
    var seen = false
    for i in 0..<cv.has.count {
      if !cv.has[i] {
        continue
      }
      let v = cv.value[i]
      if !seen || v < lo {
        lo = v
      }
      if !seen || v > hi {
        hi = v
      }
      seen = true
    }
    return Domain(min: lo, max: hi)
  }

public func renderCalendar(_ layout: CalendarLayout, _ values: [CalendarValue], _ options: CalendarOptions? = nil) -> [PyreonDrawCmd] {
    var out: [PyreonDrawCmd] = []
    let stops = (options?.stops ?? HEAT_RAMP)
    let emptyColor = (options?.emptyColor ?? "#e2e8f0")
    let domain = (options?.domain ?? calendarDomain(layout, values))
    let span = domain.max - domain.min
    let rawP = (options?.progress ?? 1.0)
    let progress = rawP < 0.0 ? 0.0 : rawP > 1.0 ? 1.0 : rawP
    var weeks = 0.0
    for c in layout.cells {
      if c.week + 1.0 > weeks {
        weeks = c.week + 1.0
      }
    }
    let shownWeeks = progress >= 1.0 ? weeks : floor(Double(weeks * progress))
    let fontSize = (options?.fontSize ?? 10.0)
    let labelColor = (options?.labelColor ?? "#64748b")
    let cv = calendarCellValues(layout, values)
    for i in 0..<layout.cells.count {
      let c = layout.cells[i]
      if c.week >= shownWeeks {
        continue
      }
      let hasV = cv.has[i]
      let raw = !hasV ? 0.0 : span <= 0.0 ? 1.0 : (cv.value[i] - domain.min) / span
      let t = raw < 0.0 ? 0.0 : raw > 1.0 ? 1.0 : raw
      let outside = hasV && visualOutside(cv.value[i], options?.inRange, options?.outBands)
      out.append(PyreonDrawCmd(kind: "rect", rect: c.rect, fill: !hasV ? emptyColor : outside ? (options?.outColor ?? "#cccccc") : rampColor(stops, t)))
    }
    if progress < 1.0 {
      return out
    }
    for m in layout.monthLabels {
      out.append(PyreonDrawCmd(kind: "text", fill: labelColor, text: m.text, at: m.at, size: fontSize, align: "start", baseline: "bottom"))
    }
    for d in layout.dayLabels {
      out.append(PyreonDrawCmd(kind: "text", fill: labelColor, text: d.text, at: d.at, size: fontSize, align: "end", baseline: "middle"))
    }
    return out
  }

public func hitCalendarIndex(_ layout: CalendarLayout, _ px: Double, _ py: Double) -> Int {
    var hit = -1
    for i in 0..<layout.cells.count {
      if hit >= 0 {
        continue
      }
      let r = layout.cells[i].rect
      if px >= r.x && px <= r.x + r.w && py >= r.y && py <= r.y + r.h {
        hit = i
      }
    }
    return hit
  }

public func geoValueOf(_ values: [GeoValue], _ name: String) -> Double {
    for v in values {
      if v.region == name {
        return v.value
      }
    }
    return GEO_NA
  }

public func geoProject(_ t: GeoTransform, _ lon: Double, _ lat: Double) -> PyreonChartPt {
    let p = projectLonLat(lon, lat, t.projection)
    return PyreonChartPt(x: t.ox + (p.x - t.minX) * t.scale, y: t.oy + (t.maxY - p.y) * t.scale)
  }

public func projectLonLat(_ lon: Double, _ lat: Double, _ projection: GeoProjection) -> PyreonChartPt {
    if projection == .mercator {
      let clamped = lat > 85.0 ? 85.0 : lat < -85.0 ? -85.0 : lat
      let phi = (clamped * Double.pi) / 180.0
      return PyreonChartPt(x: lon, y: (log(Double(tan(Double(Double.pi / 4.0 + Double(phi) / 2.0)))) * 180.0) / Double.pi)
    }
    return PyreonChartPt(x: lon, y: lat)
  }

public func ringArea(_ ring: [PyreonChartPt]) -> Double {
    var a = 0.0
    for i in 0..<ring.count {
      let j = i == 0 ? ring.count - 1 : i - 1
      a = a + (ring[j].x * ring[i].y - ring[i].x * ring[j].y)
    }
    return a / 2.0
  }

public func ringCentroid(_ ring: [PyreonChartPt]) -> PyreonChartPt? {
    let a = ringArea(ring)
    if Double(abs(a)) < 1e-12 {
      return nil
    }
    var cx = 0.0
    var cy = 0.0
    for i in 0..<ring.count {
      let j = i == 0 ? ring.count - 1 : i - 1
      let f = ring[j].x * ring[i].y - ring[i].x * ring[j].y
      cx = cx + (ring[j].x + ring[i].x) * f
      cy = cy + (ring[j].y + ring[i].y) * f
    }
    return PyreonChartPt(x: cx / (6.0 * a), y: cy / (6.0 * a))
  }

public func layoutGeoShapes(_ shapes: [GeoShape], _ box: PyreonChartRect, _ options: GeoOptions? = nil) -> GeoLayout {
    let projection = (options?.projection ?? .equirectangular)
    let pad = (options?.padding ?? 4.0)
    let raw = shapes
    var minX = 0.0
    var maxX = 0.0
    var minY = 0.0
    var maxY = 0.0
    var seen = 0
    for sh in raw {
      for ring in sh.rings {
        for p in ring {
          if seen == 0 {
            minX = p.x
            maxX = p.x
            minY = p.y
            maxY = p.y
          }
          if p.x < minX {
            minX = p.x
          }
          if p.x > maxX {
            maxX = p.x
          }
          if p.y < minY {
            minY = p.y
          }
          if p.y > maxY {
            maxY = p.y
          }
          seen = seen + 1
        }
      }
    }
    let innerW = max(0.0, box.w - pad * 2.0)
    let innerH = max(0.0, box.h - pad * 2.0)
    let spanX = maxX - minX
    let spanY = maxY - minY
    let fitScale = raw.count == 0 || spanX <= 0.0 || spanY <= 0.0 ? 1.0 : min(innerW / spanX, innerH / spanY)
    let fitOx = box.x + pad + (innerW - spanX * fitScale) / 2.0
    let fitOy = box.y + pad + (innerH - spanY * fitScale) / 2.0
    let zoom = ((options?.zoom ?? 1.0)) > 0.0 ? (options?.zoom ?? 1.0) : 1.0
    let cx = box.x + box.w / 2.0
    let cy = box.y + box.h / 2.0
    let scale = fitScale * zoom
    let ox = cx + (fitOx - cx) * zoom + ((options?.panX ?? 0.0))
    let oy = cy + (fitOy - cy) * zoom + ((options?.panY ?? 0.0))
    let toPx = { (p: PyreonChartPt) in (PyreonChartPt(x: ox + (p.x - minX) * scale, y: oy + (maxY - p.y) * scale)) }
    let regions = raw.map({ r in
      let rings = r.rings.map({ ring in ring.map(toPx) })
      var bx0 = 0.0
      var by0 = 0.0
      var bx1 = 0.0
      var by1 = 0.0
      var bseen = 0
      var bestAt = -1
      var bestArea = -1.0
      for ri in 0..<rings.count {
        let ring = rings[ri]
        for p in ring {
          if bseen == 0 {
            bx0 = p.x
            by0 = p.y
            bx1 = p.x
            by1 = p.y
          }
          if p.x < bx0 {
            bx0 = p.x
          }
          if p.y < by0 {
            by0 = p.y
          }
          if p.x > bx1 {
            bx1 = p.x
          }
          if p.y > by1 {
            by1 = p.y
          }
          bseen = bseen + 1
        }
        let a = abs(ringArea(ring))
        if a > bestArea {
          bestArea = a
          bestAt = ri
        }
      }
      let bbox = bseen == 0 ? PyreonChartRect(x: box.x, y: box.y, w: 0.0, h: 0.0) : PyreonChartRect(x: bx0, y: by0, w: bx1 - bx0, h: by1 - by0)
      let fallback = PyreonChartPt(x: bbox.x + bbox.w / 2.0, y: bbox.y + bbox.h / 2.0)
      let centroid = bestAt < 0 ? fallback : (ringCentroid(rings[bestAt]) ?? fallback)
      return GeoRegion(name: r.name, rings: rings, centroid: centroid, bbox: bbox)
    })
    return GeoLayout(regions: regions, transform: GeoTransform(minX: minX, maxY: maxY, scale: scale, ox: ox, oy: oy, projection: projection))
  }

public func geoRoamZoom(_ view: GeoView, _ factor: Double, _ px: Double, _ py: Double, _ box: PyreonChartRect, _ minZoom: Double, _ maxZoom: Double) -> GeoView {
    let lo = minZoom > 0.0 ? minZoom : 0.1
    let hi = maxZoom >= lo ? maxZoom : lo
    let wanted = view.zoom * factor
    let zoom = wanted < lo ? lo : wanted > hi ? hi : wanted
    let k = zoom / view.zoom
    let cx = box.x + box.w / 2.0
    let cy = box.y + box.h / 2.0
    let panX = (px - cx) - (px - cx - view.panX) * k
    let panY = (py - cy) - (py - cy - view.panY) * k
    return GeoView(zoom: zoom, panX: panX, panY: panY)
  }

public func geoRoamPan(_ view: GeoView, _ dx: Double, _ dy: Double) -> GeoView { GeoView(zoom: view.zoom, panX: view.panX + dx, panY: view.panY + dy) }

public func geoDomain(_ layout: GeoLayout, _ values: [GeoValue]) -> Domain {
    var lo = 0.0
    var hi = 0.0
    var seen = 0
    for r in layout.regions {
      let v = geoValueOf(values, r.name)
      if !isFiniteNumber(v) {
        continue
      }
      if seen == 0 {
        lo = v
        hi = v
      }
      if v < lo {
        lo = v
      }
      if v > hi {
        hi = v
      }
      seen = seen + 1
    }
    return seen == 0 ? Domain(min: 0.0, max: 0.0) : Domain(min: lo, max: hi)
  }

public func renderGeo(_ layout: GeoLayout, _ values: [GeoValue], _ options: GeoOptions? = nil, _ measure: ((String, Double) -> Double)? = nil) -> [PyreonDrawCmd] {
    var out: [PyreonDrawCmd] = []
    let stops = (options?.stops ?? HEAT_RAMP)
    let emptyColor = (options?.emptyColor ?? "#e2e8f0")
    let border = (options?.borderColor ?? "#ffffff")
    let borderWidth = (options?.borderWidth ?? 1.0)
    let dom = (options?.domain ?? geoDomain(layout, values))
    let lo = dom.min
    let hi = dom.max
    let span = hi - lo
    let rawP = (options?.progress ?? 1.0)
    let progress = rawP < 0.0 ? 0.0 : rawP > 1.0 ? 1.0 : rawP
    let fontSize = (options?.fontSize ?? 10.0)
    let labelColor = (options?.labelColor ?? "#1e293b")
    let m = (measure ?? approxTextWidth)
    for r in layout.regions {
      let v = geoValueOf(values, r.name)
      let has = isFiniteNumber(v) && progress > 0.0
      let t = !has ? 0.0 : span <= 0.0 ? 1.0 : ((v - lo) / span) * progress
      let fill = !has ? emptyColor : visualOutside(v, options?.inRange, options?.outBands) ? (options?.outColor ?? "#cccccc") : rampColor(stops, t < 0.0 ? 0.0 : t > 1.0 ? 1.0 : t)
      for ring in r.rings {
        out.append(PyreonDrawCmd(kind: "polygon", fill: fill, points: ring))
      }
    }
    for r in layout.regions {
      for ring in r.rings {
        var closed: [PyreonChartPt] = []
        for p in ring {
          closed.append(p)
        }
        closed.append(ring[0])
        out.append(PyreonDrawCmd(kind: "polyline", stroke: border, width: borderWidth, points: closed))
      }
    }
    if options?.showLabels == true && progress >= 1.0 {
      for r in layout.regions {
        var hostAt = -1
        for hri in 0..<r.rings.count {
          if pointInRing(r.rings[hri], r.centroid.x, r.centroid.y) {
            hostAt = hri
          }
        }
        if hostAt < 0 {
          continue
        }
        let b = ringBox(r.rings[hostAt])
        if m(r.name, fontSize) > b.w || fontSize > b.h {
          continue
        }
        out.append(PyreonDrawCmd(kind: "text", fill: labelColor, text: r.name, at: r.centroid, size: fontSize, align: "middle", baseline: "middle"))
      }
    }
    return out
  }

public func ringBox(_ ring: [PyreonChartPt]) -> PyreonChartRect {
    var x0 = 0.0
    var y0 = 0.0
    var x1 = 0.0
    var y1 = 0.0
    var seen = 0
    for p in ring {
      if seen == 0 {
        x0 = p.x
        y0 = p.y
        x1 = p.x
        y1 = p.y
      }
      if p.x < x0 {
        x0 = p.x
      }
      if p.y < y0 {
        y0 = p.y
      }
      if p.x > x1 {
        x1 = p.x
      }
      if p.y > y1 {
        y1 = p.y
      }
      seen = seen + 1
    }
    return seen == 0 ? PyreonChartRect(x: 0.0, y: 0.0, w: 0.0, h: 0.0) : PyreonChartRect(x: x0, y: y0, w: x1 - x0, h: y1 - y0)
  }

public func pointInRing(_ ring: [PyreonChartPt], _ px: Double, _ py: Double) -> Bool {
    var inside = false
    for i in 0..<ring.count {
      let j = i == 0 ? ring.count - 1 : i - 1
      let a = ring[i]
      let b = ring[j]
      if (a.y > py) != (b.y > py) && px < ((b.x - a.x) * (py - a.y)) / Double((b.y - a.y)) + a.x {
        inside = !inside
      }
    }
    return inside
  }

public func hitGeo(_ layout: GeoLayout, _ px: Double, _ py: Double) -> GeoRegion? {
    let i = hitGeoIndex(layout, px, py)
    return i < 0 ? nil : layout.regions[i]
  }

public func hitGeoIndex(_ layout: GeoLayout, _ px: Double, _ py: Double) -> Int {
    for i in stride(from: layout.regions.count - 1, through: 0, by: -1) {
      let r = layout.regions[i]
      if px < r.bbox.x || px > r.bbox.x + r.bbox.w || py < r.bbox.y || py > r.bbox.y + r.bbox.h {
        continue
      }
      for ring in r.rings {
        if pointInRing(ring, px, py) {
          return i
        }
      }
    }
    return -1
  }

public func geoOverlayPointRadii(_ points: [GeoOverlayPoint], _ base: Double) -> [Double] {
    var hi = 0.0
    for p in points {
      let value = (p.value ?? 0.0)
      if value > hi {
        hi = value
      }
    }
    var out: [Double] = []
    for p in points {
      let hasValue = p.value != nil
      let value = (p.value ?? 0.0)
      out.append(!hasValue || hi <= 0.0 ? base : base * (0.6 + 1.4 * sqrt(Double(max(0.0, value) / hi))))
    }
    return out
  }

public func renderGeoOverlayPoints(_ layout: GeoLayout, _ points: [GeoOverlayPoint], _ options: GeoOverlayOptions? = nil) -> [PyreonDrawCmd] {
    var out: [PyreonDrawCmd] = []
    let base = (options?.radius ?? 5.0)
    let color = (options?.color ?? "#b42318")
    let rawP = (options?.progress ?? 1.0)
    let progress = rawP < 0.0 ? 0.0 : rawP > 1.0 ? 1.0 : rawP
    let fontSize = (options?.fontSize ?? 10.0)
    let labelColor = (options?.labelColor ?? "#1e293b")
    let radii = geoOverlayPointRadii(points, base)
    for i in 0..<points.count {
      let p = points[i]
      let at = geoProject(layout.transform, p.lon, p.lat)
      let r = radii[i] * progress
      let fill = (p.color ?? color)
      if options?.effect == true || p.effect == true {
        out.append(PyreonDrawCmd(kind: "circle", fill: withAlpha(fill, 0.12), center: at, radius: r * 2.6))
        out.append(PyreonDrawCmd(kind: "circle", fill: withAlpha(fill, 0.25), center: at, radius: r * 1.7))
      }
      out.append(PyreonDrawCmd(kind: "circle", fill: fill, center: at, radius: r))
      if options?.showLabels == true && progress >= 1.0 && p.name != nil {
        out.append(PyreonDrawCmd(kind: "text", fill: labelColor, text: p.name, at: PyreonChartPt(x: at.x + r + 3.0, y: at.y), size: fontSize, align: "start", baseline: "middle"))
      }
    }
    return out
  }

public func renderGeoOverlayPaths(_ layout: GeoLayout, _ paths: [GeoOverlayPath], _ options: GeoOverlayOptions? = nil) -> [PyreonDrawCmd] {
    var out: [PyreonDrawCmd] = []
    let color = (options?.color ?? "#b42318")
    let rawP = (options?.progress ?? 1.0)
    let progress = rawP < 0.0 ? 0.0 : rawP > 1.0 ? 1.0 : rawP
    for path in paths {
      let pts = path.coords.map({ c in geoProject(layout.transform, c.lon, c.lat) })
      if pts.count < 2 || progress <= 0.0 {
        continue
      }
      var length = 0.0
      for _p in pts {
        length = length + 1.0
      }
      let visibleCount = progress >= 1.0 ? length : max(2.0, floor(Double(length * progress)))
      var visible: [PyreonChartPt] = []
      var index = 0.0
      for point in pts {
        if index < visibleCount {
          visible.append(point)
        }
        index = index + 1.0
      }
      out.append(PyreonDrawCmd(kind: "polyline", stroke: (path.color ?? color), width: (path.width ?? 1.5), points: visible))
    }
    return out
  }

public func hitGeoOverlayPoint(_ layout: GeoLayout, _ points: [GeoOverlayPoint], _ px: Double, _ py: Double, _ base: Double? = nil) -> Int {
    let radii = geoOverlayPointRadii(points, (base ?? 5.0))
    var best = -1
    var bestD = 999999999999.0
    for i in 0..<points.count {
      let at = geoProject(layout.transform, points[i].lon, points[i].lat)
      let d = (px - at.x) * (px - at.x) + (py - at.y) * (py - at.y)
      let r = radii[i] + 3.0
      if d <= r * r && d < bestD {
        best = i
        bestD = d
      }
    }
    return best
  }

public func renderGeoHeat(_ layout: GeoLayout, _ points: [GeoHeatPoint], _ stops: [String], _ radius: Double, _ progress: Double) -> [PyreonDrawCmd] {
    var out: [PyreonDrawCmd] = []
    var lo = 0.0
    var hi = 0.0
    var seen = 0
    for p in points {
      if seen == 0 || p.value < lo {
        lo = p.value
      }
      if seen == 0 || p.value > hi {
        hi = p.value
      }
      seen = seen + 1
    }
    let span = hi - lo
    let alpha = progress < 0.0 ? 0.0 : progress > 1.0 ? 1.0 : progress
    let ramp = stops.count > 0 ? stops : ["#3b82f6", "#facc15", "#ef4444"]
    for p in points {
      let at = geoProject(layout.transform, p.lon, p.lat)
      let color = rampColor(ramp, span > 0.0 ? (p.value - lo) / span : 1.0)
      let ring = arcPolygon(at, radius, 0.0, 0.0, Double.pi * 2.0)
      out.append(PyreonDrawCmd(kind: "polygon", fill: withAlpha(color, 0.5 * alpha), grad: PyreonChartGradient(from: at, to: PyreonChartPt(x: at.x + radius, y: at.y), stops: [PyreonChartGradientStop(offset: 0.0, color: withAlpha(color, 0.85 * alpha)), PyreonChartGradientStop(offset: 1.0, color: withAlpha(color, 0.0))], radial: true), points: ring))
    }
    return out
  }

public func geoHeatStops(_ stops: [String], _ fallback: [String]?) -> [String] {
    if stops.count > 0 {
      return stops
    }
    return (fallback ?? [])
  }

public func renderGeoPies(_ layout: GeoLayout, _ pies: [GeoPie], _ progress: Double) -> [PyreonDrawCmd] {
    var out: [PyreonDrawCmd] = []
    let t = progress < 0.0 ? 0.0 : progress > 1.0 ? 1.0 : progress
    for pie in pies {
      let at = geoProject(layout.transform, pie.lon, pie.lat)
      let inner = pie.radius * (pie.innerRadius < 0.0 ? 0.0 : pie.innerRadius > 0.95 ? 0.95 : pie.innerRadius)
      for a in layoutArcs(pie.slices) {
        if !(a.end > a.start) {
          continue
        }
        out.append(PyreonDrawCmd(kind: "polygon", fill: a.slice.color, points: arcPolygon(at, pie.radius, inner, a.start * t, a.end * t)))
      }
    }
    return out
  }

public func renderGeoTrails(_ layout: GeoLayout, _ paths: [GeoOverlayPath], _ trail: GeoTrail, _ time: Double, _ fallbackColor: String) -> [PyreonDrawCmd] {
    var out: [PyreonDrawCmd] = []
    let period = trail.period > 0.0 ? trail.period : 4.0
    let cycles = time / period
    let phase = cycles - floor(Double(cycles))
    let share = trail.trailLength < 0.0 ? 0.0 : trail.trailLength > 1.0 ? 1.0 : trail.trailLength
    for path in paths {
      let pts = path.coords.map({ c in geoProject(layout.transform, c.lon, c.lat) })
      if pts.count < 2 {
        continue
      }
      let total = pathLength(pts)
      if !(total > 0.0) {
        continue
      }
      let color = trail.color != "" ? trail.color : (path.color ?? fallbackColor)
      let head = phase * total
      let tail = head - share * total > 0.0 ? head - share * total : 0.0
      if share > 0.0 && head > tail {
        out.append(PyreonDrawCmd(kind: "polyline", stroke: withAlpha(color, 0.85), width: ((path.width ?? 1.5)) + 1.0, points: subPath(pts, tail, head)))
      }
      out.append(PyreonDrawCmd(kind: "circle", fill: color, center: pointAlong(pts, head), radius: trail.symbolSize / 2.0))
    }
    return out
  }

public func renderGeoTrailsIfAny(_ layout: GeoLayout, _ paths: [GeoOverlayPath], _ trail: GeoTrail?, _ time: Double, _ fallbackColor: String) -> [PyreonDrawCmd] {
    let t = (trail ?? GeoTrail(period: 4.0, trailLength: 0.0, color: "", symbolSize: 0.0))
    if trail == nil {
      return []
    }
    return renderGeoTrails(layout, paths, t, time, fallbackColor)
  }

public func ganttUnitFor(_ spanDays: Double) -> String {
    if spanDays <= 21.0 {
      return "day"
    }
    if spanDays <= 120.0 {
      return "week"
    }
    if spanDays <= 730.0 {
      return "month"
    }
    if spanDays <= 3000.0 {
      return "quarter"
    }
    return "year"
  }

public func ganttUnitDays(_ unit: String) -> Double {
    if unit == "day" {
      return 1.0
    }
    if unit == "week" {
      return 7.0
    }
    if unit == "month" {
      return 30.0
    }
    if unit == "quarter" {
      return 91.0
    }
    return 365.0
  }

public func ganttMonthName(_ month: Double) -> String {
    var mi = 0
    var miF = 1.0
    while miF < month {
      mi = mi + 1
      miF = miF + 1.0
    }
    return GANTT_MONTHS[mi]
  }

public func ganttAlignStart(_ lo: Double, _ unit: String) -> Double {
    let day = floor(Double(lo))
    let c = civilFromDays(day)
    if unit == "day" {
      return day
    }
    if unit == "week" {
      let back = weekdayOfDays(day) + 6.0
      return day - (back - floor(Double(Double(back) / 7.0)) * 7.0)
    }
    if unit == "month" {
      return daysFromCivil(c.year, c.month, 1.0)
    }
    if unit == "quarter" {
      let off = c.month - 1.0
      return daysFromCivil(c.year, c.month - (off - floor(Double(Double(off) / 3.0)) * 3.0), 1.0)
    }
    return daysFromCivil(c.year, 1.0, 1.0)
  }

public func ganttNextTick(_ t: Double, _ unit: String) -> Double {
    if unit == "day" {
      return t + 1.0
    }
    if unit == "week" {
      return t + 7.0
    }
    let c = civilFromDays(t)
    if unit == "month" {
      return c.month >= 12.0 ? daysFromCivil(c.year + 1.0, 1.0, 1.0) : daysFromCivil(c.year, c.month + 1.0, 1.0)
    }
    if unit == "quarter" {
      return c.month >= 10.0 ? daysFromCivil(c.year + 1.0, c.month - 9.0, 1.0) : daysFromCivil(c.year, c.month + 3.0, 1.0)
    }
    return daysFromCivil(c.year + 1.0, 1.0, 1.0)
  }

public func ganttTicks(_ lo: Double, _ hi: Double, _ unit: String) -> [GanttTick] {
    var out: [GanttTick] = []
    let sameYear = civilFromDays(floor(Double(lo))).year == civilFromDays(floor(Double(hi))).year
    var t = ganttAlignStart(lo, unit)
    var `guard` = 0
    while t <= hi && `guard` < 400 {
      `guard` = `guard` + 1
      if t >= lo {
        let c = civilFromDays(t)
        let q = floor(Double((c.month - 1.0) / 3.0)) + 1.0
        let year = "\(((Double(c.year)) + 0.5).rounded(.down))"
        let label = unit == "day" || unit == "week" ? "\(((Double(c.day)) + 0.5).rounded(.down)) \(ganttMonthName(c.month))" : unit == "month" ? (sameYear ? ganttMonthName(c.month) : "\(ganttMonthName(c.month)) \(year)") : unit == "quarter" ? "Q\(((Double(q)) + 0.5).rounded(.down)) \(year)" : year
        out.append(GanttTick(at: t, x: 0.0, label: label))
      }
      t = ganttNextTick(t, unit)
    }
    return out
  }

public func ganttRowIndex(_ rows: [GanttRow], _ id: String) -> Int {
    var found = -1
    for i in 0..<rows.count {
      if found < 0 && rows[i].task.id == id {
        found = i
      }
    }
    return found
  }

public func layoutGantt(_ tasks: [GanttTask], _ box: PyreonChartRect, _ options: GanttOptions? = nil, _ measure: ((String, Double) -> Double)? = nil) -> GanttLayout {
    let fontSize = (options?.fontSize ?? 12.0)
    let m = (measure ?? approxTextWidth)
    let palette = (options?.palette ?? DEFAULT_PALETTE)
    var sDay: [Double] = []
    var eDay: [Double] = []
    for task in tasks {
      let ps = parseIsoDays(task.start)
      let s = ps.ok ? ps.days : 0.0
      let pe = parseIsoDays((task.end ?? ""))
      let eRaw = pe.ok ? pe.days : s
      let e = task.milestone == true ? s : eRaw < s ? s : eRaw
      sDay.append(s)
      eDay.append(e)
    }
    var lo = 0.0
    var hi = 0.0
    var seen = false
    for i in 0..<sDay.count {
      if !seen || sDay[i] < lo {
        lo = sDay[i]
      }
      if !seen || eDay[i] > hi {
        hi = eDay[i]
      }
      seen = true
    }
    if !seen {
      lo = daysFromCivil(2024.0, 1.0, 1.0)
      hi = lo + 30.0
    }
    if hi <= lo {
      hi = lo + 1.0
    }
    let pToday = parseIsoDays((options?.today ?? ""))
    let hasToday = pToday.ok
    let todayDay = pToday.days
    if hasToday {
      if todayDay < lo {
        lo = todayDay
      }
      if todayDay > hi {
        hi = todayDay
      }
    }
    let pA = parseIsoDays((options?.domain?.start ?? ""))
    let pB = parseIsoDays((options?.domain?.end ?? ""))
    let explicit = pA.ok && pB.ok && pB.days > pA.days
    if explicit {
      lo = pA.days
      hi = pB.days
    } else {
      let pad = ganttUnitDays(ganttUnitFor(hi - lo)) * 0.25
      lo = lo - pad
      hi = hi + pad
    }
    let unit = ganttUnitFor(hi - lo)
    var labelW = 0.0
    for task in tasks {
      let w = m(task.name, fontSize)
      if w > labelW {
        labelW = w
      }
    }
    var groups: [String] = []
    for task in tasks {
      let g = (task.group ?? "")
      if g == "" {
        continue
      }
      var known = false
      for k in groups {
        if k == g {
          known = true
        }
      }
      if !known {
        groups.append(g)
      }
    }
    for g in groups {
      let w = m(g, fontSize + 1.0)
      if w > labelW {
        labelW = w
      }
    }
    let cap = box.w * ((options?.labelFraction ?? 0.35))
    let labelCol = labelW + 16.0 < cap ? labelW + 16.0 : cap
    let axisH = fontSize + 12.0
    let axisW = box.w - labelCol
    let axis = PyreonChartRect(x: box.x + labelCol, y: box.y, w: axisW < 0.0 ? 0.0 : axisW, h: axisH)
    var lineCount = 0.0
    var lastGroup = ""
    for task in tasks {
      let g = (task.group ?? "")
      if g != "" && g != lastGroup {
        lineCount = lineCount + 1.0
        lastGroup = g
      }
      lineCount = lineCount + 1.0
    }
    let availRaw = box.h - axisH
    let avail = availRaw < 0.0 ? 0.0 : availRaw
    let fitRow = lineCount <= 0.0 ? 28.0 : avail / lineCount
    let clampedRow = fitRow < 12.0 ? 12.0 : fitRow > 28.0 ? 28.0 : fitRow
    let rowHeight = (options?.rowHeight ?? clampedRow)
    let plotH = rowHeight * lineCount
    let plot = PyreonChartRect(x: axis.x, y: box.y + axisH, w: axis.w, h: avail > plotH ? avail : plotH)
    let span = hi - lo
    var rows: [GanttRow] = []
    var lanes: [GanttLane] = []
    var y = plot.y
    var laneGroup = ""
    let labelX = box.x + (groups.count > 0 ? 14.0 : 4.0)
    for i in 0..<tasks.count {
      let task = tasks[i]
      let g = (task.group ?? "")
      if g != "" && g != laneGroup {
        lanes.append(GanttLane(text: g, at: PyreonChartPt(x: box.x + 4.0, y: y + rowHeight / 2.0), band: PyreonChartRect(x: box.x, y: y, w: box.w, h: rowHeight)))
        y = y + rowHeight
        laneGroup = g
      }
      let x0 = plot.x + ((sDay[i] - lo) / span) * plot.w
      let x1 = plot.x + ((eDay[i] - lo) / span) * plot.w
      let barRaw = rowHeight * 0.6
      let barH = barRaw < 4.0 ? 4.0 : barRaw
      let isMilestone = task.milestone == true || eDay[i] == sDay[i]
      let bw = x1 - x0 < 1.0 ? 1.0 : x1 - x0
      let rect = isMilestone ? PyreonChartRect(x: x0 - Double(barH) / 2.0, y: y + (rowHeight - barH) / 2.0, w: barH, h: barH) : PyreonChartRect(x: x0, y: y + (rowHeight - barH) / 2.0, w: bw, h: barH)
      rows.append(GanttRow(task: task, index: i, rect: rect, band: PyreonChartRect(x: box.x, y: y, w: box.w, h: rowHeight), startDay: sDay[i], endDay: eDay[i], color: (task.color ?? palette[i % palette.count]), label: task.name, labelAt: PyreonChartPt(x: labelX, y: y + rowHeight / 2.0)))
      y = y + rowHeight
    }
    var dependencies: [GanttDependency] = []
    for row in rows {
      let deps = (row.task.dependencies ?? [])
      for dep in deps {
        let fi = ganttRowIndex(rows, dep)
        if fi < 0 {
          continue
        }
        let from = rows[fi]
        let fx = from.rect.x + from.rect.w
        let fy = from.rect.y + Double(from.rect.h) / 2.0
        let tx = row.rect.x
        let ty = row.rect.y + Double(row.rect.h) / 2.0
        var points: [PyreonChartPt] = []
        points.append(PyreonChartPt(x: fx, y: fy))
        if fx + 8.0 <= tx {
          points.append(PyreonChartPt(x: fx + 8.0, y: fy))
          points.append(PyreonChartPt(x: fx + 8.0, y: ty))
        } else {
          let above = ty - Double(row.rect.h) / 2.0 - 2.0
          points.append(PyreonChartPt(x: fx + 8.0, y: fy))
          points.append(PyreonChartPt(x: fx + 8.0, y: above))
          points.append(PyreonChartPt(x: tx - 8.0, y: above))
          points.append(PyreonChartPt(x: tx - 8.0, y: ty))
        }
        points.append(PyreonChartPt(x: tx, y: ty))
        dependencies.append(GanttDependency(from: dep, to: row.task.id, points: points))
      }
    }
    var ticks: [GanttTick] = []
    for t in ganttTicks(lo, hi, unit) {
      ticks.append(GanttTick(at: t.at, x: plot.x + ((t.at - lo) / span) * plot.w, label: t.label))
    }
    return GanttLayout(rows: rows, lanes: lanes, dependencies: dependencies, ticks: ticks, unit: unit, axis: axis, plot: plot, domain: Domain(min: lo, max: hi), hasToday: hasToday, todayX: hasToday ? plot.x + ((todayDay - lo) / span) * plot.w : 0.0, rowHeight: rowHeight)
  }

public func renderGantt(_ layout: GanttLayout, _ options: GanttOptions? = nil) -> [PyreonDrawCmd] {
    var out: [PyreonDrawCmd] = []
    let fontSize = (options?.fontSize ?? 12.0)
    let labelColor = (options?.labelColor ?? "#374151")
    let gridColor = (options?.gridColor ?? "#e5e7eb")
    let laneColor = (options?.laneColor ?? "#f3f4f6")
    let rawP = (options?.progress ?? 1.0)
    let progress = rawP < 0.0 ? 0.0 : rawP > 1.0 ? 1.0 : rawP
    let showDeps = (options?.showDependencies ?? true)
    for lane in layout.lanes {
      out.append(PyreonDrawCmd(kind: "rect", rect: lane.band, fill: laneColor))
      out.append(PyreonDrawCmd(kind: "text", fill: labelColor, text: lane.text, at: lane.at, size: fontSize + 1.0, align: "start", baseline: "middle"))
    }
    let plotBottom = layout.plot.y + layout.plot.h
    for t in layout.ticks {
      out.append(PyreonDrawCmd(kind: "line", from: PyreonChartPt(x: t.x, y: layout.axis.y + layout.axis.h), to: PyreonChartPt(x: t.x, y: plotBottom), stroke: gridColor, width: 1.0))
      out.append(PyreonDrawCmd(kind: "text", fill: labelColor, text: t.label, at: PyreonChartPt(x: t.x + 3.0, y: layout.axis.y + layout.axis.h / 2.0), size: fontSize - 1.0, align: "start", baseline: "middle"))
    }
    for row in layout.rows {
      out.append(PyreonDrawCmd(kind: "text", fill: labelColor, text: row.label, at: row.labelAt, size: fontSize, align: "start", baseline: "middle"))
      let r = row.rect
      if row.task.milestone == true || row.endDay == row.startDay {
        let cx = r.x + Double(r.w) / 2.0
        let cy = r.y + Double(r.h) / 2.0
        let hw = (Double(r.w) / 2.0) * progress
        var diamond: [PyreonChartPt] = []
        diamond.append(PyreonChartPt(x: cx, y: cy - hw))
        diamond.append(PyreonChartPt(x: cx + hw, y: cy))
        diamond.append(PyreonChartPt(x: cx, y: cy + hw))
        diamond.append(PyreonChartPt(x: cx - hw, y: cy))
        out.append(PyreonDrawCmd(kind: "polygon", fill: row.color, points: diamond))
        continue
      }
      let w = r.w * progress
      out.append(PyreonDrawCmd(kind: "rect", rect: PyreonChartRect(x: r.x, y: r.y, w: w, h: r.h), fill: row.color))
      let done = (row.task.progress ?? 0.0)
      if done > 0.0 {
        let dw = w * (done > 1.0 ? 1.0 : done)
        out.append(PyreonDrawCmd(kind: "rect", rect: PyreonChartRect(x: r.x, y: r.y + r.h * 0.25, w: dw, h: r.h * 0.5), fill: "rgba(0,0,0,0.35)"))
      }
    }
    if progress >= 1.0 && showDeps {
      for d in layout.dependencies {
        out.append(PyreonDrawCmd(kind: "polyline", stroke: "#6b7280", width: 1.0, points: d.points))
      }
    }
    if layout.hasToday {
      out.append(PyreonDrawCmd(kind: "line", from: PyreonChartPt(x: layout.todayX, y: layout.axis.y), to: PyreonChartPt(x: layout.todayX, y: plotBottom), stroke: (options?.todayColor ?? "#dc2626"), width: 1.5, dash: [4.0, 3.0]))
    }
    return out
  }

public func hitGanttIndex(_ layout: GanttLayout, _ px: Double, _ py: Double) -> Int {
    var hit = -1
    for i in 0..<layout.rows.count {
      if hit >= 0 {
        continue
      }
      let r = layout.rows[i].rect
      if px >= r.x && px <= r.x + r.w && py >= r.y && py <= r.y + r.h {
        hit = i
      }
    }
    if hit >= 0 {
      return hit
    }
    for i in 0..<layout.rows.count {
      if hit >= 0 {
        continue
      }
      let b = layout.rows[i].band
      if px >= layout.plot.x && py >= b.y && py <= b.y + b.h {
        hit = i
      }
    }
    return hit
  }

public func ganttDurationDays(_ row: GanttRow) -> Double {
    let raw = row.endDay - row.startDay
    let f = floor(Double(raw))
    return raw - f < 0.5 ? f : f + 1.0
  }

public func parallelPlace(_ axis: ParallelLayoutAxis, _ v: Double) -> ParallelPlaced {
    if !isFiniteNumber(v) {
      return ParallelPlaced(ok: false, y: 0.0)
    }
    let lo = axis.domain.min
    let span = axis.domain.max - lo
    if axis.isCategory && (v < 0.0 || v > axis.domain.max) {
      return ParallelPlaced(ok: false, y: 0.0)
    }
    let raw = axis.isCategory ? (span <= 0.0 ? 0.5 : v / span) : span <= 0.0 ? 0.5 : (v - lo) / span
    let t = raw < 0.0 ? 0.0 : raw > 1.0 ? 1.0 : raw
    let y = axis.inverse ? axis.y0 + (axis.y1 - axis.y0) * t : axis.y1 - (axis.y1 - axis.y0) * t
    return ParallelPlaced(ok: true, y: y)
  }

public func parallelHighlighted(_ highlight: [Double], _ index: Double) -> Bool {
    var found = false
    for h in highlight {
      if h == index {
        found = true
      }
    }
    return found
  }

public func layoutParallel(_ axes: [ParallelAxis], _ rows: [[Double]], _ box: PyreonChartRect, _ options: ParallelOptions? = nil) -> ParallelLayout {
    let fontSize = (options?.fontSize ?? 11.0)
    let top = box.y + fontSize * 1.8
    let bottom = box.y + box.h - fontSize * 1.4
    let n = axes.count
    var nF = 0.0
    for i in 0..<n {
      nF = nF + 1.0
    }
    var outAxes: [ParallelLayoutAxis] = []
    var aF = 0.0
    for a in 0..<n {
      let axis = axes[a]
      let x = n <= 1 ? box.x + box.w / 2.0 : box.x + (box.w * aF) / (nF - 1.0)
      let isCat = axis.type == "category"
      let cats = (axis.categories ?? [])
      let dMin = (axis.domain?.min ?? 0.0)
      let dMax = (axis.domain?.max ?? -1.0)
      let hasDomain = dMax >= dMin
      var lo = 0.0
      var hi = 0.0
      if isCat {
        var catsF = 0.0
        for i in 0..<cats.count {
          catsF = catsF + 1.0
        }
        hi = catsF > 1.0 ? catsF - 1.0 : 0.0
      } else {
        if hasDomain {
          lo = dMin
          hi = dMax
        } else {
          var seen = false
          for r in rows {
            if a >= r.count {
              continue
            }
            let v = r[a]
            if !isFiniteNumber(v) {
              continue
            }
            if !seen || v < lo {
              lo = v
            }
            if !seen || v > hi {
              hi = v
            }
            seen = true
          }
          if !seen {
            hi = 1.0
          }
        }
      }
      let inverse = axis.inverse == true
      let resolved = ParallelLayoutAxis(name: axis.name, x: x, y0: top, y1: bottom, domain: Domain(min: lo, max: hi), ticks: [], isCategory: isCat, inverse: inverse)
      var ticks: [ParallelTick] = []
      if isCat {
        var iF = 0.0
        for i in 0..<cats.count {
          ticks.append(ParallelTick(y: parallelPlace(resolved, iF).y, label: cats[i]))
          iF = iF + 1.0
        }
      } else {
        ticks.append(ParallelTick(y: inverse ? top : bottom, label: plain(lo)))
        ticks.append(ParallelTick(y: inverse ? bottom : top, label: plain(hi)))
      }
      outAxes.append(ParallelLayoutAxis(name: axis.name, x: x, y0: top, y1: bottom, domain: Domain(min: lo, max: hi), ticks: ticks, isCategory: isCat, inverse: inverse))
      aF = aF + 1.0
    }
    var lines: [ParallelLine] = []
    let colors = (options?.lineColors ?? [])
    let fallback = (options?.lineColor ?? paletteAt((options?.palette ?? DEFAULT_PALETTE), 0))
    for i in 0..<rows.count {
      let row = rows[i]
      var points: [PyreonChartPt] = []
      var present: [Bool] = []
      for a in 0..<n {
        let v = a < row.count ? row[a] : 0.0 / 0.0
        let placed = parallelPlace(outAxes[a], v)
        points.append(PyreonChartPt(x: outAxes[a].x, y: placed.y))
        present.append(placed.ok)
      }
      let color = i < colors.count ? colors[i] : fallback
      lines.append(ParallelLine(index: i, points: points, present: present, color: color))
    }
    return ParallelLayout(axes: outAxes, lines: lines)
  }

public func renderParallel(_ layout: ParallelLayout, _ options: ParallelOptions? = nil) -> [PyreonDrawCmd] {
    var out: [PyreonDrawCmd] = []
    let opacity = (options?.lineOpacity ?? 0.45)
    let width = (options?.lineWidth ?? 1.0)
    let rawP = (options?.progress ?? 1.0)
    let progress = rawP < 0.0 ? 0.0 : rawP > 1.0 ? 1.0 : rawP
    let n = layout.axes.count
    var nF = 0.0
    for i in 0..<n {
      nF = nF + 1.0
    }
    let shown = progress >= 1.0 ? nF : floor(Double(nF * progress))
    let highlight = (options?.highlight ?? [])
    let highlightColor = (options?.highlightColor ?? "#b42318")
    let fontSize = (options?.fontSize ?? 11.0)
    let labelColor = (options?.labelColor ?? "#334155")
    let axisColor = (options?.axisColor ?? "#94a3b8")
    for pass in 0..<2 {
      var lineF = 0.0
      for line in layout.lines {
        let isHl = parallelHighlighted(highlight, lineF)
        lineF = lineF + 1.0
        if (pass == 1) != isHl {
          continue
        }
        let stroke = isHl ? highlightColor : sankeyRgba(line.color, opacity)
        let w = isHl ? width + 1.0 : width
        var runStart = -1
        var iF = 0.0
        for i in 0..<line.points.count {
          let visible = iF < shown && line.present[i]
          if visible && runStart < 0 {
            runStart = i
          }
          if !visible && runStart >= 0 {
            if i - runStart >= 2 {
              var run: [PyreonChartPt] = []
              for k in runStart..<i {
                run.append(line.points[k])
              }
              out.append(PyreonDrawCmd(kind: "polyline", stroke: stroke, width: w, points: run))
            }
            runStart = -1
          }
          iF = iF + 1.0
        }
        if runStart >= 0 && line.points.count - runStart >= 2 {
          var run: [PyreonChartPt] = []
          for k in runStart..<line.points.count {
            run.append(line.points[k])
          }
          out.append(PyreonDrawCmd(kind: "polyline", stroke: stroke, width: w, points: run))
        }
      }
    }
    for axis in layout.axes {
      out.append(PyreonDrawCmd(kind: "line", from: PyreonChartPt(x: axis.x, y: axis.y0), to: PyreonChartPt(x: axis.x, y: axis.y1), stroke: axisColor, width: 1.0))
      if progress < 1.0 {
        continue
      }
      out.append(PyreonDrawCmd(kind: "text", fill: labelColor, text: axis.name, at: PyreonChartPt(x: axis.x, y: axis.y0 - fontSize * 0.5), size: fontSize, align: "middle", baseline: "bottom"))
      for t in axis.ticks {
        out.append(PyreonDrawCmd(kind: "line", from: PyreonChartPt(x: axis.x - 3.0, y: t.y), to: PyreonChartPt(x: axis.x + 3.0, y: t.y), stroke: axisColor, width: 1.0))
        out.append(PyreonDrawCmd(kind: "text", fill: labelColor, text: t.label, at: PyreonChartPt(x: axis.x + 5.0, y: t.y), size: fontSize * 0.9, align: "start", baseline: "middle"))
      }
    }
    return out
  }

public func parallelSegmentDistance(_ px: Double, _ py: Double, _ a: PyreonChartPt, _ b: PyreonChartPt) -> Double {
    let dx = b.x - a.x
    let dy = b.y - a.y
    let len2 = dx * dx + dy * dy
    let rawT = len2 <= 0.0 ? 0.0 : ((px - a.x) * dx + (py - a.y) * dy) / len2
    let t = rawT < 0.0 ? 0.0 : rawT > 1.0 ? 1.0 : rawT
    let qx = a.x + dx * t
    let qy = a.y + dy * t
    return sqrt(Double((px - qx) * (px - qx) + (py - qy) * (py - qy)))
  }

public func hitParallelIndex(_ layout: ParallelLayout, _ px: Double, _ py: Double, _ tolerance: Double? = nil) -> Int {
    let tol = (tolerance ?? 4.0)
    var best = -1
    var bestD = tol
    for k in 0..<layout.lines.count {
      let line = layout.lines[k]
      for i in 1..<line.points.count {
        if !line.present[i - 1] || !line.present[i] {
          continue
        }
        let d = parallelSegmentDistance(px, py, line.points[i - 1], line.points[i])
        if d <= bestD {
          best = k
          bestD = d
        }
      }
    }
    return best
  }

public func niceTicks(_ lo: Double, _ hi: Double, _ count: Int) -> [Double] {
    if hi <= lo {
      return [lo]
    }
    let raw = (hi - lo) / Double(count)
    let mag = pow(Double(10.0), Double(floor(Double(log10(Double(raw))))))
    let norm = raw / mag
    let step = (norm >= 5.0 ? 5.0 : norm >= 2.0 ? 2.0 : 1.0) * mag
    var out: [Double] = []
    var v = ceil(Double(lo / step)) * step
    while v <= hi + 1e-9 {
      out.append(((Double(v * 1000000.0)) + 0.5).rounded(.down) / 1000000.0)
      v = v + step
    }
    return out
  }

public func layoutSingleAxis(_ axis: SingleAxisSpec, _ points: [SingleAxisPoint], _ box: PyreonChartRect, _ options: SingleAxisOptions? = nil) -> SingleAxisLayout {
    let fontSize = (options?.fontSize ?? 11.0)
    let base = (options?.radius ?? 5.0)
    let isCat = axis.type == "category"
    let gutter = fontSize * 2.0
    let x0 = box.x + gutter
    let x1 = box.x + box.w - gutter
    let y = box.y + box.h / 2.0
    var lo: Double
    var hi: Double
    if isCat {
      lo = 0.0
      hi = max(0.0, Double(((axis.categories ?? [])).count) * 1.0 - 1.0)
    } else {
      if axis.domain != nil {
        let domain = (axis.domain ?? Domain(min: 0.0, max: 1.0))
        lo = domain.min
        hi = domain.max
      } else {
        lo = 999999999999999.0
        hi = -999999999999999.0
        for p in points {
          if p.x < lo {
            lo = p.x
          }
          if p.x > hi {
            hi = p.x
          }
        }
        if lo == 999999999999999.0 {
          lo = 0.0
          hi = 1.0
        }
      }
    }
    let span = hi - lo
    let px = { (v: Double) in (span <= 0.0 ? (x0 + x1) / 2.0 : x0 + ((v - lo) / Double(span)) * (x1 - x0)) }
    var ticks: [SingleAxisTick] = []
    if isCat {
      let cats = (axis.categories ?? [])
      for i in 0..<cats.count {
        ticks.append(SingleAxisTick(x: px(Double(i) * 1.0), label: cats[i], index: i))
      }
    } else {
      var index = 0
      for v in niceTicks(lo, hi, 6) {
        ticks.append(SingleAxisTick(x: px(v), label: String(v), index: index))
        index += 1
      }
    }
    var maxSize = 0.0
    for p in points {
      let pointSize = (p.size ?? 0.0)
      if pointSize > maxSize {
        maxSize = pointSize
      }
    }
    let color = (options?.color ?? "#0f766e")
    var laid: [SingleAxisLayoutPoint] = []
    for i in 0..<points.count {
      let p = points[i]
      let pointSize = (p.size ?? 0.0)
      let hasSize = p.size != nil
      laid.append(SingleAxisLayoutPoint(index: i, at: PyreonChartPt(x: px(p.x), y: y), radius: !hasSize || maxSize <= 0.0 ? base : base * (0.6 + 1.4 * sqrt(Double(max(0.0, pointSize) / maxSize))), color: (p.color ?? color), name: p.name))
    }
    return SingleAxisLayout(axis: SingleAxisLayoutAxis(y: y, x0: x0, x1: x1, ticks: ticks, name: axis.name), points: laid)
  }

public func renderSingleAxis(_ layout: SingleAxisLayout, _ options: SingleAxisOptions? = nil) -> [PyreonDrawCmd] {
    var out: [PyreonDrawCmd] = []
    let fontSize = (options?.fontSize ?? 11.0)
    let axisColor = (options?.axisColor ?? "#94a3b8")
    let labelColor = (options?.labelColor ?? "#334155")
    let rawP = (options?.progress ?? 1.0)
    let progress = rawP < 0.0 ? 0.0 : rawP > 1.0 ? 1.0 : rawP
    let a = layout.axis
    out.append(PyreonDrawCmd(kind: "line", from: PyreonChartPt(x: a.x0, y: a.y), to: PyreonChartPt(x: a.x1, y: a.y), stroke: axisColor, width: 1.0))
    for t in a.ticks {
      out.append(PyreonDrawCmd(kind: "line", from: PyreonChartPt(x: t.x, y: a.y), to: PyreonChartPt(x: t.x, y: a.y + 4.0), stroke: axisColor, width: 1.0))
      out.append(PyreonDrawCmd(kind: "text", fill: labelColor, text: t.label, at: PyreonChartPt(x: t.x, y: a.y + 8.0), size: fontSize, align: "middle", baseline: "top"))
    }
    if a.name != nil {
      out.append(PyreonDrawCmd(kind: "text", fill: labelColor, text: a.name, at: PyreonChartPt(x: a.x1, y: a.y + fontSize * 2.2), size: fontSize, align: "end", baseline: "top"))
    }
    for p in layout.points {
      out.append(PyreonDrawCmd(kind: "circle", fill: p.color, center: p.at, radius: p.radius * progress))
      if options?.showLabels == true && progress >= 1.0 && p.name != nil {
        out.append(PyreonDrawCmd(kind: "text", fill: labelColor, text: p.name, at: PyreonChartPt(x: p.at.x, y: p.at.y - p.radius - 4.0), size: fontSize, align: "middle", baseline: "bottom"))
      }
    }
    return out
  }

public func hitSingleAxis(_ layout: SingleAxisLayout, _ px: Double, _ py: Double) -> Int {
    var best = -1
    var bestD = 999999999999999.0
    for p in layout.points {
      let d = (px - p.at.x) * (px - p.at.x) + (py - p.at.y) * (py - p.at.y)
      let r = p.radius + 3.0
      if d <= r * r && d < bestD {
        best = p.index
        bestD = d
      }
    }
    return best
  }

public func candlestickFrame(_ candles: [Ohlc], _ w: Double, _ h: Double, _ categories: [String], _ fontSize: Double, _ measure: (String, Double) -> Double) -> CandlestickFrame {
    let domain = niceDomain(ohlcExtent(candles), 5.0)
    let n = candles.count
    let cfg = LayoutConfig(width: w, height: h, xDomain: Domain(min: 0.0, max: n > 1 ? Double(n - 1) : 1.0), yDomain: domain, categories: categories, fontSize: fontSize, xTickCount: 5.0, yTickCount: 5.0, showXAxis: true, showYAxis: true)
    let layout = computeLayout(cfg, measure)
    return CandlestickFrame(candles: candles, domain: domain, layout: layout)
  }

public func renderCandlestickChart(_ candles: [Ohlc], _ w: Double, _ h: Double, _ categories: [String], _ theme: ChartTheme, _ options: CandleOptions?, _ measure: (String, Double) -> Double) -> [PyreonDrawCmd] {
    let f = candlestickFrame(candles, w, h, categories, theme.fontSize, measure)
    let l = f.layout
    var cmds: [PyreonDrawCmd] = []
    for tick in l.yTicks {
      cmds.append(PyreonDrawCmd(kind: "line", from: PyreonChartPt(x: l.plot.x, y: tick.pos), to: PyreonChartPt(x: l.plot.x + l.plot.w, y: tick.pos), stroke: theme.grid, width: 1.0))
      cmds.append(PyreonDrawCmd(kind: "text", fill: theme.label, text: tick.label, at: PyreonChartPt(x: l.plot.x - 6.0, y: tick.pos), size: theme.fontSize, align: "end", baseline: "middle"))
    }
    for tick in l.xTicks {
      cmds.append(PyreonDrawCmd(kind: "text", fill: theme.label, text: tick.label, at: PyreonChartPt(x: tick.pos, y: l.plot.y + l.plot.h + 6.0), size: theme.fontSize, align: "middle", baseline: "top"))
    }
    let body = renderCandles(candles, l.plot, f.domain, CandleOptions(upColor: (options?.upColor ?? theme.positive), downColor: (options?.downColor ?? theme.negative), widthRatio: options?.widthRatio))
    for c in body {
      cmds.append(c)
    }
    return cmds
  }

public func hitCandlestickChart(_ candles: [Ohlc], _ w: Double, _ h: Double, _ categories: [String], _ fontSize: Double, _ measure: (String, Double) -> Double, _ px: Double, _ py: Double) -> Int {
    let f = candlestickFrame(candles, w, h, categories, fontSize, measure)
    return hitCandle(candles.count, f.layout.plot, px, py)
  }

public func fiveNumber(_ values: [Double]) -> FiveNumber {
    var sorted: [Double] = []
    for v in values {
      if isFiniteNumber(v) {
        sorted.append(v)
      }
    }
    sorted.sorted(by: { a, b in (a - b) < 0 })
    let n = sorted.count
    if n == 0 {
      return FiveNumber(min: 0.0, q1: 0.0, median: 0.0, q3: 0.0, max: 0.0, outliers: [])
    }
    let at = { (p: Double) in
      let pos = p * (Double(n) - 1.0)
      var lo = 0
      var jf = 1.0
      for k in 1..<n {
        if jf <= pos {
          lo = k
        }
        jf = jf + 1.0
      }
      let hi = lo + 1 < n ? lo + 1 : lo
      var loF = 0.0
      for k in 0..<lo {
        loF = loF + 1.0
      }
      let frac = pos - loF
      return sorted[lo] + (sorted[hi] - sorted[lo]) * frac
    }
    let q1 = at(0.25)
    let median = at(0.5)
    let q3 = at(0.75)
    let iqr = q3 - q1
    let loFence = q1 - 1.5 * iqr
    let hiFence = q3 + 1.5 * iqr
    var min = sorted[0]
    var max = sorted[n - 1]
    var outliers: [Double] = []
    var minSet = false
    var maxSet = false
    for v in sorted {
      if v < loFence || v > hiFence {
        outliers.append(v)
      } else {
        if !minSet {
          min = v
          minSet = true
        }
        max = v
        maxSet = true
      }
    }
    if !minSet {
      min = q1
    }
    if !maxSet {
      max = q3
    }
    return FiveNumber(min: min, q1: q1, median: median, q3: q3, max: max, outliers: outliers)
  }

public func boxplotExtent(_ rows: [FiveNumber]) -> Domain {
    if rows.count == 0 {
      return Domain(min: 0.0, max: 1.0)
    }
    var lo = rows[0].min
    var hi = rows[0].max
    for r in rows {
      if r.min < lo {
        lo = r.min
      }
      if r.max > hi {
        hi = r.max
      }
      for o in r.outliers {
        if o < lo {
          lo = o
        }
        if o > hi {
          hi = o
        }
      }
    }
    if hi <= lo {
      return Domain(min: lo - 1.0, max: lo + 1.0)
    }
    return Domain(min: lo, max: hi)
  }

public func renderBoxplot(_ rows: [FiveNumber], _ plot: PyreonChartRect, _ domain: Domain, _ options: BoxplotOptions? = nil) -> [PyreonDrawCmd] {
    var out: [PyreonDrawCmd] = []
    let n = rows.count
    if n == 0 {
      return out
    }
    let fill = (options?.fill ?? "rgba(99,102,241,0.35)")
    let stroke = (options?.stroke ?? "#4649c8")
    let rawRatio = (options?.widthRatio ?? 0.5)
    let ratio = rawRatio < 0.05 ? 0.05 : rawRatio > 0.9 ? 0.9 : rawRatio
    let radius = (options?.outlierRadius ?? 3.0)
    let rawP = (options?.progress ?? 1.0)
    let progress = rawP < 0.0 ? 0.0 : rawP > 1.0 ? 1.0 : rawP
    let band = plot.w / Double(n)
    let bw = band * ratio
    let yOf = { (v: Double) in scaleLinear(domain, plot.y + plot.h, plot.y, v) }
    for i in 0..<n {
      let r = rows[i]
      let cx = plot.x + band * Double(i) + band / 2.0
      let yMed = yOf(r.median)
      let grow = { (y: Double) in yMed + (y - yMed) * progress }
      let yQ1 = grow(yOf(r.q1))
      let yQ3 = grow(yOf(r.q3))
      let yMin = grow(yOf(r.min))
      let yMax = grow(yOf(r.max))
      out.append(PyreonDrawCmd(kind: "line", from: PyreonChartPt(x: cx, y: yMax), to: PyreonChartPt(x: cx, y: yQ3), stroke: stroke, width: 1.0))
      out.append(PyreonDrawCmd(kind: "line", from: PyreonChartPt(x: cx, y: yQ1), to: PyreonChartPt(x: cx, y: yMin), stroke: stroke, width: 1.0))
      out.append(PyreonDrawCmd(kind: "line", from: PyreonChartPt(x: cx - bw / 4.0, y: yMax), to: PyreonChartPt(x: cx + bw / 4.0, y: yMax), stroke: stroke, width: 1.0))
      out.append(PyreonDrawCmd(kind: "line", from: PyreonChartPt(x: cx - bw / 4.0, y: yMin), to: PyreonChartPt(x: cx + bw / 4.0, y: yMin), stroke: stroke, width: 1.0))
      let top = yQ3 < yQ1 ? yQ3 : yQ1
      let h = yQ1 > yQ3 ? yQ1 - yQ3 : yQ3 - yQ1
      out.append(PyreonDrawCmd(kind: "rect", rect: PyreonChartRect(x: cx - bw / 2.0, y: top, w: bw, h: h < 1.0 ? 1.0 : h), fill: fill))
      out.append(PyreonDrawCmd(kind: "line", from: PyreonChartPt(x: cx - bw / 2.0, y: yMed), to: PyreonChartPt(x: cx + bw / 2.0, y: yMed), stroke: stroke, width: 2.0))
      if progress >= 1.0 {
        for o in r.outliers {
          out.append(PyreonDrawCmd(kind: "circle", fill: stroke, center: PyreonChartPt(x: cx, y: yOf(o)), radius: radius))
        }
      }
    }
    return out
  }

public func hitBox(_ count: Int, _ plot: PyreonChartRect, _ px: Double, _ py: Double) -> Int {
    if count == 0 || px < plot.x || px > plot.x + plot.w || py < plot.y || py > plot.y + plot.h {
      return -1
    }
    let band = plot.w / Double(count)
    var idx = 0
    var jf = 1.0
    for k in 1..<count {
      if plot.x + band * jf <= px {
        idx = k
      }
      jf = jf + 1.0
    }
    return idx
  }

public func boxplotFrame(_ rows: [FiveNumber], _ width: Double, _ height: Double, _ categories: [String], _ fontSize: Double, _ measure: (String, Double) -> Double, _ format: ((Double) -> String)? = nil) -> BoxplotFrame {
    let domain = niceDomain(boxplotExtent(rows), 5.0)
    let cfg = LayoutConfig(width: width, height: height, xDomain: Domain(min: 0.0, max: rows.count > 1 ? Double(rows.count - 1) : 1.0), yDomain: domain, categories: categories, fontSize: fontSize, xTickCount: 5.0, yTickCount: 5.0, showXAxis: true, showYAxis: true, yFormat: format)
    return BoxplotFrame(domain: domain, layout: computeLayout(cfg, measure))
  }

public func renderBoxplotChart(_ rows: [FiveNumber], _ width: Double, _ height: Double, _ categories: [String], _ theme: ChartTheme, _ options: BoxplotOptions, _ measure: (String, Double) -> Double, _ format: ((Double) -> String)? = nil, _ progress: Double? = nil) -> [PyreonDrawCmd] {
    let f = boxplotFrame(rows, width, height, categories, theme.fontSize, measure, format)
    let l = f.layout
    var out: [PyreonDrawCmd] = []
    for tick in l.yTicks {
      out.append(PyreonDrawCmd(kind: "line", from: PyreonChartPt(x: l.plot.x, y: tick.pos), to: PyreonChartPt(x: l.plot.x + l.plot.w, y: tick.pos), stroke: theme.grid, width: 1.0))
      out.append(PyreonDrawCmd(kind: "text", fill: theme.label, text: tick.label, at: PyreonChartPt(x: l.plot.x - 6.0, y: tick.pos), size: theme.fontSize, align: "end", baseline: "middle"))
    }
    for tick in l.xTicks {
      out.append(PyreonDrawCmd(kind: "text", fill: theme.label, text: tick.label, at: PyreonChartPt(x: tick.pos, y: l.plot.y + l.plot.h + 6.0), size: theme.fontSize, align: "middle", baseline: "top"))
    }
    let p = (progress ?? options.progress)
    let opts = BoxplotOptions(fill: options.fill, stroke: options.stroke, widthRatio: options.widthRatio, outlierRadius: options.outlierRadius, progress: p)
    for c in renderBoxplot(rows, l.plot, f.domain, opts) {
      out.append(c)
    }
    return out
  }

public func hitBoxplotChart(_ count: Int, _ width: Double, _ height: Double, _ categories: [String], _ fontSize: Double, _ measure: (String, Double) -> Double, _ px: Double, _ py: Double, _ rows: [FiveNumber]) -> Int {
    let f = boxplotFrame(rows, width, height, categories, fontSize, measure)
    return hitBox(count, f.layout.plot, px, py)
  }

public func heatGridFrom(_ xs: [String], _ ys: [String], _ values: [Double]) -> HeatGrid {
    var cols: [String] = []
    var rows: [String] = []
    var colOf: [Double] = []
    var rowOf: [Double] = []
    var vals: [Double] = []
    let n = xs.count
    for i in 0..<n {
      let x = xs[i]
      var ci = -1.0
      var cf = 0.0
      for j in 0..<cols.count {
        if cols[j] == x {
          ci = cf
        }
        cf += 1.0
      }
      if ci < 0.0 {
        ci = cf
        cols.append(x)
      }
      colOf.append(ci)
      let y = i < ys.count ? ys[i] : ""
      var ri = -1.0
      var rf = 0.0
      for j in 0..<rows.count {
        if rows[j] == y {
          ri = rf
        }
        rf += 1.0
      }
      if ri < 0.0 {
        ri = rf
        rows.append(y)
      }
      rowOf.append(ri)
      let v = i < values.count ? values[i] : 0.0
      vals.append(isFiniteNumber(v) ? v : 0.0)
    }
    return buildHeatGrid(cols, rows, colOf, rowOf, vals)
  }

public func heatPlotFor(_ grid: HeatGrid, _ w: Double, _ h: Double, _ fontSize: Double, _ measure: (String, Double) -> Double) -> PyreonChartRect {
    var widest = 0.0
    for r in grid.rows {
      let lw = measure(r, fontSize)
      if lw > widest {
        widest = lw
      }
    }
    let left = widest + 8.0
    let bottom = fontSize + 8.0
    return PyreonChartRect(x: left, y: 4.0, w: max(0.0, w - left - 4.0), h: max(0.0, h - 4.0 - bottom))
  }

public func renderHeatChart(_ grid: HeatGrid, _ w: Double, _ h: Double, _ theme: ChartTheme, _ stops: [String], _ gap: Double, _ measure: (String, Double) -> Double, _ progress: Double? = nil, _ selection: HeatSelection? = nil) -> [PyreonDrawCmd] {
    let plot = heatPlotFor(grid, w, h, theme.fontSize, measure)
    var cmds: [PyreonDrawCmd] = []
    let cells = renderHeat(HeatmapOptions(grid: grid, plot: plot, stops: stops, gap: gap, progress: (progress ?? 1.0), inRange: selection?.inRange, outBands: selection?.outBands, outColor: selection?.outColor, domain: selection?.domain))
    for c in cells {
      cmds.append(c)
    }
    var nrF = 0.0
    for i in 0..<grid.rows.count {
      nrF += 1.0
    }
    var ncF = 0.0
    for i in 0..<grid.cols.count {
      ncF += 1.0
    }
    let rowStep = plot.h / max(1.0, nrF)
    let colStep = plot.w / max(1.0, ncF)
    var rf = 0.0
    for r in grid.rows {
      cmds.append(PyreonDrawCmd(kind: "text", fill: theme.label, text: r, at: PyreonChartPt(x: plot.x - 4.0, y: plot.y + rowStep * (rf + 0.5)), size: theme.fontSize, align: "end", baseline: "middle"))
      rf += 1.0
    }
    var cf = 0.0
    for c in grid.cols {
      cmds.append(PyreonDrawCmd(kind: "text", fill: theme.label, text: c, at: PyreonChartPt(x: plot.x + colStep * (cf + 0.5), y: plot.y + plot.h + 4.0), size: theme.fontSize, align: "middle", baseline: "top"))
      cf += 1.0
    }
    return cmds
  }

public func hitHeatChart(_ grid: HeatGrid, _ w: Double, _ h: Double, _ fontSize: Double, _ gap: Double, _ measure: (String, Double) -> Double, _ px: Double, _ py: Double) -> Int { hitHeatCell(grid, heatPlotFor(grid, w, h, fontSize, measure), gap, px, py) }

public func plotHitBars(_ spec: ChartSpec, _ measure: (String, Double) -> Double, _ px: Double, _ py: Double) -> Int { plotHitBarsIn(spec, layoutChart(spec, measure), px, py) }

public func plotHitBarsIn(_ spec: ChartSpec, _ l: PlotLayout, _ px: Double, _ py: Double) -> Int {
    for i in 0..<spec.series.count {
      let kind = spec.series[i].kind
      if kind != "bars" && kind != "waterfall" {
        continue
      }
      let idx = hitBar(barsForIn(spec, i, l.plot), px, py)
      if idx >= 0 {
        return categoryIndex(spec, idx)
      }
    }
    return stackedHitIn(spec, l.plot, px, py)
  }

public func plotHitIndex(_ spec: ChartSpec, _ measure: (String, Double) -> Double, _ px: Double, _ py: Double) -> Int { plotHitIndexIn(spec, layoutChart(spec, measure), px, py) }

public func plotHitIndexIn(_ raw: ChartSpec, _ l: PlotLayout, _ px: Double, _ py: Double) -> Int {
    let barHit = plotHitBarsIn(raw, l, px, py)
    if barHit >= 0 {
      return barHit
    }
    let spec = geometrySpec(raw)
    if spec.series.count == 0 {
      return -1
    }
    let first = spec.series[0]
    if first.kind == "bars" || first.kind == "stacked" || first.kind == "grouped" || first.kind == "waterfall" {
      return -1
    }
    return categoryIndex(raw, hitNearestX(categoryPoints(spec, first.values, l.plot, resolveYDomain(spec)), px))
  }

public func plotHitSeriesIn(_ spec: ChartSpec, _ l: PlotLayout, _ px: Double, _ py: Double, _ reach: Double) -> Int {
    let geo = geometrySpec(spec)
    var bars = -1
    var bi = 0
    for s in geo.series {
      if (s.kind == "bars" || s.kind == "waterfall") && bars < 0 {
        if hitBar(barsForIn(spec, bi, l.plot), px, py) >= 0 {
          bars = bi
        }
      }
      bi = bi + 1
    }
    if bars >= 0 {
      return bars
    }
    var sets = -1
    var si = 0
    for s in geo.series {
      if (s.kind == "stacked" || s.kind == "grouped") && sets < 0 {
        for p in brushDatumPoints(spec, l, si) {
          let dxs = px - p.x
          let dys = py - p.y
          if dxs * dxs + dys * dys <= reach * reach && sets < 0 {
            sets = si
          }
        }
      }
      si = si + 1
    }
    if sets >= 0 {
      return sets
    }
    var best = -1
    var bestD = reach * reach
    var pi = 0
    for s in geo.series {
      if s.kind != "bars" && s.kind != "waterfall" && s.kind != "stacked" && s.kind != "grouped" {
        for p in brushDatumPoints(spec, l, pi) {
          let dx = px - p.x
          let dy = py - p.y
          let d = dx * dx + dy * dy
          if d <= bestD {
            bestD = d
            best = pi
          }
        }
      }
      pi = pi + 1
    }
    return best
  }

public func renderTitle(_ text: String, _ subtitle: String?, _ box: PyreonChartRect, _ opts: TitleOptions) -> TitleLayout {
    var cmds: [PyreonDrawCmd] = []
    if text == "" && (subtitle == nil || subtitle == "") {
      return TitleLayout(cmds: cmds, height: 0.0)
    }
    let align = (opts.align ?? "start")
    let gap = (opts.gap ?? 8.0)
    let subSize = (opts.subtitleSize ?? opts.fontSize * 0.8)
    let subColor = (opts.subtitleColor ?? opts.color)
    let x = align == "start" ? box.x : align == "end" ? box.x + box.w : box.x + box.w / 2.0
    var y = box.y
    if text != "" {
      cmds.append(PyreonDrawCmd(kind: "text", fill: opts.color, text: text, at: PyreonChartPt(x: x, y: y), size: opts.fontSize, align: align, baseline: "top"))
      y = y + opts.fontSize
    }
    if subtitle != nil && subtitle != "" {
      if text != "" {
        y = y + gap / 2.0
      }
      cmds.append(PyreonDrawCmd(kind: "text", fill: subColor, text: subtitle, at: PyreonChartPt(x: x, y: y), size: subSize, align: align, baseline: "top"))
      y = y + subSize
    }
    return TitleLayout(cmds: cmds, height: y - box.y + gap)
  }

public func legendPlan(_ entries: [LegendEntry], _ box: PyreonChartRect, _ opts: LegendOptions, _ measure: (String, Double) -> Double, _ wrapW: Double) -> LegendPlan {
    var row: [Double] = []
    var xs: [Double] = []
    var x = box.x
    var r = 0.0
    for e in entries {
      let entryW = opts.swatch + 4.0 + measure(e.label, opts.fontSize) + opts.gap
      if opts.orientation == "horizontal" && x + entryW > box.x + wrapW && x > box.x {
        x = box.x
        r = r + 1.0
      }
      row.append(r)
      xs.append(x)
      if opts.orientation == "horizontal" {
        x = x + entryW
      } else {
        r = r + 1.0
      }
    }
    var count = 0.0
    for i in 0..<entries.count {
      count = count + 1.0
    }
    let rows = opts.orientation == "horizontal" ? r + 1.0 : count
    return LegendPlan(row: row, xs: xs, rows: rows)
  }

public func ceilPositive(_ v: Double) -> Double {
    let f = floor(Double(v))
    return f < v ? f + 1.0 : f
  }

public func renderLegend(_ entries: [LegendEntry], _ box: PyreonChartRect, _ opts: LegendOptions, _ measure: (String, Double) -> Double) -> LegendLayout {
    var cmds: [PyreonDrawCmd] = []
    var boxes: [PyreonChartRect] = []
    if entries.count == 0 {
      return LegendLayout(cmds: cmds, height: 0.0, boxes: boxes)
    }
    let rowH = Double(max(opts.swatch, opts.fontSize)) + opts.gap
    let pagerW = opts.fontSize * 5.0 + opts.gap
    let maxRows = (opts.maxRows ?? 0.0)
    let capped = maxRows >= 1.0
    var plan = legendPlan(entries, box, opts, measure, box.w)
    var overflow = capped && plan.rows > maxRows
    if overflow && opts.orientation == "horizontal" {
      plan = legendPlan(entries, box, opts, measure, max(opts.swatch + 4.0, box.w - pagerW))
      overflow = plan.rows > maxRows
    }
    let pages = overflow ? ceilPositive(plan.rows / maxRows) : 1.0
    let rawPage = (opts.page ?? 0.0)
    let page = overflow ? max(0.0, min(pages - 1.0, floor(Double(rawPage)))) : 0.0
    let firstRow = overflow ? page * maxRows : 0.0
    let lastRow = overflow ? min(plan.rows, firstRow + maxRows) : plan.rows
    for i in 0..<entries.count {
      let e = entries[i]
      let r = plan.row[i]
      if r < firstRow || r >= lastRow {
        boxes.append(PyreonChartRect(x: 0.0, y: 0.0, w: -1.0, h: -1.0))
        continue
      }
      let x = plan.xs[i]
      let y = box.y + (r - firstRow) * rowH
      let textW = measure(e.label, opts.fontSize)
      let entryW = opts.swatch + 4.0 + textW + opts.gap
      boxes.append(PyreonChartRect(x: x, y: y, w: entryW - opts.gap, h: rowH - opts.gap))
      cmds.append(PyreonDrawCmd(kind: "rect", rect: PyreonChartRect(x: x, y: y + (rowH - opts.gap - opts.swatch) / 2.0, w: opts.swatch, h: opts.swatch), fill: e.muted == true ? withAlpha(e.color, 0.25) : e.color))
      cmds.append(PyreonDrawCmd(kind: "text", fill: e.muted == true ? withAlpha(opts.labelColor, 0.45) : opts.labelColor, text: e.label, at: PyreonChartPt(x: x + opts.swatch + 4.0, y: y + (rowH - opts.gap) / 2.0), size: opts.fontSize, align: "start", baseline: "middle"))
    }
    let visibleRows = lastRow - firstRow
    let height = visibleRows * rowH
    if !overflow {
      return LegendLayout(cmds: cmds, height: height, boxes: boxes)
    }
    let py = box.y + (visibleRows - 1.0) * rowH
    let arrowW = opts.fontSize
    let right = box.x + box.w
    let prevX = right - pagerW
    let nextX = right - arrowW
    let canPrev = page > 0.0
    let canNext = page < pages - 1.0
    let mid = (rowH - opts.gap) / 2.0
    cmds.append(PyreonDrawCmd(kind: "text", fill: canPrev ? opts.labelColor : withAlpha(opts.labelColor, 0.35), text: "‹", at: PyreonChartPt(x: prevX + arrowW / 2.0, y: py + mid), size: opts.fontSize, align: "middle", baseline: "middle"))
    cmds.append(PyreonDrawCmd(kind: "text", fill: opts.labelColor, text: "\(plain(page + 1.0))/\(plain(pages))", at: PyreonChartPt(x: (prevX + arrowW + nextX) / 2.0, y: py + mid), size: opts.fontSize, align: "middle", baseline: "middle"))
    cmds.append(PyreonDrawCmd(kind: "text", fill: canNext ? opts.labelColor : withAlpha(opts.labelColor, 0.35), text: "›", at: PyreonChartPt(x: nextX + arrowW / 2.0, y: py + mid), size: opts.fontSize, align: "middle", baseline: "middle"))
    let pager = LegendPager(page: page, pages: pages, hasPrev: canPrev, prev: PyreonChartRect(x: prevX, y: py, w: arrowW, h: rowH - opts.gap), hasNext: canNext, next: PyreonChartRect(x: nextX, y: py, w: arrowW, h: rowH - opts.gap))
    return LegendLayout(cmds: cmds, height: height, boxes: boxes, pager: pager)
  }

public func legendColumnWidth(_ entries: [LegendEntry], _ opts: LegendOptions, _ measure: (String, Double) -> Double) -> Double {
    var w = 0.0
    for e in entries {
      let ew = opts.swatch + 4.0 + measure(e.label, opts.fontSize) + opts.gap
      if ew > w {
        w = ew
      }
    }
    return w
  }

public func placeLegend(_ entries: [LegendEntry], _ area: PyreonChartRect, _ position: LegendPosition, _ opts: LegendOptions, _ measure: (String, Double) -> Double) -> LegendPlacement {
    let empty = LegendPlacement(cmds: [], top: 0.0, bottom: 0.0, left: 0.0, right: 0.0, boxes: [])
    if entries.count == 0 {
      return empty
    }
    let pad = 8.0
    if position == .left || position == .right {
      let col = min(legendColumnWidth(entries, opts, measure), area.w * 0.4)
      let lx = position == .left ? area.x + pad : area.x + area.w - col
      let vertical = { var c = opts; c.orientation = "vertical"; return c }()
      let l = renderLegend(entries, PyreonChartRect(x: lx, y: area.y + pad, w: col, h: area.h), vertical, measure)
      let inset = col + pad
      return LegendPlacement(cmds: l.cmds, top: 0.0, bottom: 0.0, left: position == .left ? inset : 0.0, right: position == .right ? inset : 0.0, boxes: l.boxes, pager: l.pager)
    }
    let horizontal = { var c = opts; c.orientation = "horizontal"; return c }()
    let wrapW = area.w - pad * 2.0
    if position == .bottom {
      let rows = legendPlan(entries, PyreonChartRect(x: pad, y: 0.0, w: wrapW, h: area.h), horizontal, measure, wrapW).rows
      let rowH = max(10.0, opts.fontSize) + 12.0
      let lh = rows * rowH
      let l = renderLegend(entries, PyreonChartRect(x: area.x + pad, y: area.y + area.h - lh, w: wrapW, h: lh), horizontal, measure)
      return LegendPlacement(cmds: l.cmds, top: 0.0, bottom: l.height + pad, left: 0.0, right: 0.0, boxes: l.boxes, pager: l.pager)
    }
    let l = renderLegend(entries, PyreonChartRect(x: area.x + pad, y: area.y + pad, w: wrapW, h: area.h), horizontal, measure)
    return LegendPlacement(cmds: l.cmds, top: l.height + pad, bottom: 0.0, left: 0.0, right: 0.0, boxes: l.boxes, pager: l.pager)
  }

public func tooltipAt(_ index: Int, _ categories: [String], _ series: [TooltipSeries]) -> TooltipContent {
    var rows: [TooltipRow] = []
    for s in series {
      let v = s.values[index]
      if v == nil || !isFiniteNumber(v) {
        continue
      }
      var row = TooltipRow(label: s.label, value: v, color: s.color)
      let other = (s.values2 ?? [])
      if index < other.count {
        let v2 = other[index]
        if isFiniteNumber(v2) {
          row = TooltipRow(label: s.label, value: v, color: s.color, value2: v2)
        }
      }
      let rs = (s.rValues ?? [])
      if index < rs.count {
        let r = rs[index]
        if isFiniteNumber(r) {
          row = TooltipRow(label: row.label, value: row.value, color: row.color, value2: row.value2, size: r)
        }
      }
      rows.append(row)
      let extras = (s.extras ?? [])
      for e in extras {
        let nums = (e.numbers ?? [])
        let strs = (e.texts ?? [])
        if index < nums.count {
          let ev = nums[index]
          if isFiniteNumber(ev) {
            let numRow = TooltipRow(label: e.label, value: ev, color: s.color)
            rows.append(numRow)
          }
        } else {
          if index < strs.count {
            let textRow = TooltipRow(label: e.label, value: 0.0 / 0.0, color: s.color, text: strs[index])
            rows.append(textRow)
          }
        }
      }
    }
    return TooltipContent(title: (categories[index] ?? "\(index + 1)"), rows: rows)
  }

public func tooltipLines(_ c: TooltipContent, _ format: ((Double) -> String)? = nil) -> [String] {
    let fmt = (format ?? plain)
    var out = [c.title]
    for r in c.rows {
      let lo = (r.value2 ?? (0.0 / 0.0))
      let sz = (r.size ?? (0.0 / 0.0))
      let txt = (r.text ?? "")
      if lo == lo {
        out.append("\(r.label): \(fmt(lo)) to \(fmt(r.value))")
      } else {
        if sz == sz {
          out.append("\(r.label): \(fmt(r.value)) (size \(fmt(sz)))")
        } else {
          if r.value != r.value {
            out.append("\(r.label): \(txt)")
          } else {
            out.append("\(r.label): \(fmt(r.value))")
          }
        }
      }
    }
    return out
  }

public func placeTooltip(_ at: PyreonChartPt, _ size: Size, _ bounds: PyreonChartRect, _ offset: Double) -> PyreonChartPt {
    var x = at.x + offset
    if x + size.w > bounds.x + bounds.w {
      x = at.x - offset - size.w
    }
    if x < bounds.x {
      x = bounds.x
    }
    var y = at.y - size.h / 2.0
    if y < bounds.y {
      y = bounds.y
    }
    if y + size.h > bounds.y + bounds.h {
      y = bounds.y + bounds.h - size.h
    }
    return PyreonChartPt(x: x, y: y)
  }

public func toolboxGlyph(_ tool: String) -> String {
    if tool == "saveAsImage" {
      return "⤓"
    }
    if tool == "restore" {
      return "↺"
    }
    if tool == "magicLine" {
      return "∿"
    }
    if tool == "magicBar" {
      return "▥"
    }
    if tool == "magicStack" {
      return "☰"
    }
    if tool == "magicTiled" {
      return "▦"
    }
    if tool == "dataZoom" {
      return "⊕"
    }
    if tool == "dataZoomBack" {
      return "⊖"
    }
    if tool == "brushRect" {
      return "▭"
    }
    if tool == "brushPolygon" {
      return "⬠"
    }
    if tool == "brushLineX" {
      return "⇹"
    }
    if tool == "brushLineY" {
      return "⇳"
    }
    if tool == "brushKeep" {
      return "⧉"
    }
    if tool == "brushClear" {
      return "⌫"
    }
    return "▤"
  }

public func renderToolbox(_ tools: [String], _ box: PyreonChartRect, _ opts: ToolboxOptions) -> ToolboxLayout {
    var cmds: [PyreonDrawCmd] = []
    var boxes: [PyreonChartRect] = []
    if tools.count == 0 {
      return ToolboxLayout(cmds: cmds, boxes: boxes, height: 0.0)
    }
    let gap = (opts.gap ?? 6.0)
    let size = opts.fontSize + 8.0
    var n = 0.0
    for _t in tools {
      n = n + 1.0
    }
    var i = 0.0
    for tool in tools {
      let x = box.x + box.w - size - (n - 1.0 - i) * (size + gap)
      var active = opts.active == tool
      for a in (opts.actives ?? []) {
        if a == tool {
          active = true
        }
      }
      boxes.append(PyreonChartRect(x: x, y: box.y, w: size, h: size))
      if active {
        cmds.append(PyreonDrawCmd(kind: "rect", rect: PyreonChartRect(x: x, y: box.y, w: size, h: size), fill: "rgba(99,102,241,0.18)"))
      }
      cmds.append(PyreonDrawCmd(kind: "text", fill: opts.color, text: toolboxGlyph(tool), at: PyreonChartPt(x: x + size / 2.0, y: box.y + size / 2.0), size: opts.fontSize + 2.0, align: "middle", baseline: "middle"))
      i = i + 1.0
    }
    return ToolboxLayout(cmds: cmds, boxes: boxes, height: size + gap)
  }

public func hitToolbox(_ tools: [String], _ boxes: [PyreonChartRect], _ px: Double, _ py: Double) -> String? {
    for i in 0..<boxes.count {
      let b = boxes[i]
      if b == nil {
        continue
      }
      if px >= b.x && px <= b.x + b.w && py >= b.y && py <= b.y + b.h {
        return (tools[i] ?? nil)
      }
    }
    return nil
  }

